window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0100", [{"word":"weathering","ipa_uk":"/ˈweðərɪŋ/","ipa_us":"/ˈweðərɪŋ/","definition_zh":"风化（作用）；岩石在原地被雨、霜、风分解的过程；因长期暴露而造成的损耗","definition_en":"the slow breakdown of rock or other material where it lies, caused by rain, frost, wind, sun and living things","core_image":"岩壁上一条细缝，夜里的雨水冻成冰楔，白天把碎石一点点撬下来","scene":"峡谷步道上，向导指着岩壁上一道被冰楔撑开的细缝，说这些碎石不是被洪水搬来的。 Salt and frost drive the slow weathering that opens these cracks.","sceneCN":"这里 weathering 指「岩石在原位被风化分解的过程」（第 1 个义项：岩石在原地被雨、冻、风分解而不被搬走）；句意为盐分与霜冻驱动缓慢的风化，把岩壁上的裂缝一点点撑开。图中可辨识物件：岩壁裂缝、冰楔、脚下碎屑堆、向导抬起的手。","pos":[{"tag":"n.","zh":"风化（作用）；暴露于风雨造成的损耗（不可数）"},{"tag":"v.","zh":"weather 的现在分词：经受住风雨或难关；使受日晒雨淋而变质"}],"collocations":[{"phrase":"chemical weathering","zh":"化学风化"},{"phrase":"mechanical weathering","zh":"机械风化"},{"phrase":"frost weathering","zh":"冻融风化"},{"phrase":"accelerated weathering","zh":"加速风化"},{"phrase":"weathering resistance","zh":"抗风化能力"},{"phrase":"the weathering of rock","zh":"岩石的风化"}],"forms":[{"label":"名词（本义，通常不可数）","form":"weathering"},{"label":"动词原形（weather）","form":"weather"},{"label":"三单（he/she/it）","form":"weathers"},{"label":"过去式","form":"weathered"},{"label":"过去分词","form":"weathered"},{"label":"现在分词","form":"weathering"}],"derivatives":[{"word":"weather","pos":"v./n.","zh":"风化；天气；经受住"},{"word":"weathered","pos":"adj.","zh":"风化的；饱经风霜的"},{"word":"weather-beaten","pos":"adj.","zh":"被风雨磨蚀的；饱经风霜的"},{"word":"weatherproof","pos":"adj./v.","zh":"防风雨的；使能抗风雨"},{"word":"weatherability","pos":"n.","zh":"耐候性；抗风化能力"}],"senses":[{"no":"01","title":"Breakdown of rock in place","titleCN":"岩石在原位被分解","definition":"the process by which solid rock is broken into fragments where it lies, without being carried away","definitionCN":"坚硬的岩石在原地碎成小块，碎屑没有被搬走","example":"Frost and rain begin the weathering that turns granite into loose grains.","exampleCN":"霜冻与雨水启动了把花岗岩变成松散颗粒的风化。","why":"the -ing noun names a process, and geology reserves it for decay in place, as opposed to erosion, which removes the debris.","whyCN":"加 -ing 的名词表示一种过程，地质学专指原位分解，与把碎屑搬走的侵蚀相对。"},{"no":"02","title":"Chemical weathering","titleCN":"化学风化","definition":"the breakdown of minerals by dissolution, oxidation or hydrolysis when water and air react with them","definitionCN":"水与空气和矿物发生反应，通过溶解、氧化或水解使矿物分解","example":"Feldspar is lost first during chemical weathering, leaving clay behind.","exampleCN":"化学风化中最先失去的是长石，剩下黏土。","why":"chemical agents do not split the rock mechanically; they change the minerals themselves, so the residue is a new material.","whyCN":"化学营力不靠机械力劈开岩石，而是改变矿物本身，因此残余物已是新材料。"},{"no":"03","title":"Frost wedging","titleCN":"冻融作用把岩石撑裂","definition":"the splitting of rock when water in its cracks freezes, expands and forces the walls apart","definitionCN":"裂缝中的水结冰膨胀，把两侧岩壁推开的撑裂过程","example":"Water in the joint expands at night, and frost weathering pries the block loose.","exampleCN":"夜里裂缝中的水膨胀，冻融风化把这块岩石撬松。","why":"water expands as it freezes, so a crack that holds water is worked open year after year; this is the most familiar mechanical agent.","whyCN":"水结冰时体积膨胀，因此蓄水的裂缝年复一年被撑开，这是最常见的机械风化方式。"},{"no":"04","title":"Biological weathering","titleCN":"生物风化","definition":"the loosening and alteration of rock by roots, burrowing animals, lichens and their acids","definitionCN":"根系、穴居动物、地衣及其酸性分泌物造成的岩石松动与改变","example":"Lichen crusts and wedging roots add biological weathering to the cliff face.","exampleCN":"地衣结壳与楔入的根系在崖面上叠加生物风化。","why":"living things act both mechanically, by pushing rock apart, and chemically, by releasing acids that dissolve minerals.","whyCN":"生物既靠机械力把岩石顶开，也靠分泌酸类溶解矿物，两种方式同时起作用。"},{"no":"05","title":"Accelerated weathering from pollution","titleCN":"污染造成的加速风化","definition":"the unusually fast decay of stone caused by acids and salts released by industry or traffic","definitionCN":"工业或交通释放的酸与盐使石材异常迅速地损坏","example":"Sulfur in the air speeds up the weathering of limestone statues.","exampleCN":"空气中的硫使石灰岩雕像加速风化。","why":"the natural process is the same, but the rate changes: acid deposition supplies reactants far faster than clean rain does.","whyCN":"过程本身没变，变的是速度：酸性沉降提供的反应物远多于洁净雨水。"},{"no":"06","title":"Weathering of building stone","titleCN":"建筑石材的风化损伤","definition":"the surface damage that stone, brick or mortar suffers through long exposure to the elements","definitionCN":"石材、砖或灰浆因长期暴露于天气而受到的表面损伤","example":"The survey mapped weathering on the cathedral's south wall.","exampleCN":"测绘记录了主教座堂南墙上的风化损伤。","why":"conservation uses the same technical noun for damage that has to be measured, mapped and slowed.","whyCN":"文物保护沿用同一术语，指需要测量、绘图并加以减缓的损伤。"},{"no":"07","title":"Slow wearing down of anything","titleCN":"抽象义：任何事物被时间慢慢磨薄","definition":"the gradual weakening of an institution, idea or relationship under prolonged pressure","definitionCN":"制度、观念或关系在长期压力下逐渐被削弱","example":"Decades of compromise produced a slow weathering of the party's founding promises.","exampleCN":"数十年的妥协使该党最初的承诺被慢慢磨蚀。","why":"the metaphor borrows the cliff: nothing strikes it, yet repeated small exposures change its outline.","whyCN":"这个比喻借自崖壁：并无重击，只是反复的小小暴露改变了它的轮廓。"},{"no":"08","title":"A bone's weathering stage","titleCN":"考古埋藏学中的骨骼风化等级","definition":"a graded measure of how long a bone has been exposed on the surface before burial, scored from the damage visible on it","definitionCN":"依骨骼表面损伤评定其在埋藏前于地表暴露了多久的分级指标","example":"The bones were scored for weathering before the site was dated.","exampleCN":"在给遗址定年之前，先对骨骼的风化等级做了评分。","why":"burial science turned the process noun into a countable diagnostic scale, so a skeleton can be read like a clock.","whyCN":"埋藏学把这个过程名词变成可计数的诊断尺度，于是骨架可以像钟表一样被读取。"}],"etymology":{"intro":{"en":"Weathering is the gerund of the verb weather, which comes from Old English weder 'air, sky, storm'. The geological noun is a nineteenth-century extension of the older verb 'to expose to the weather'. Dates are approximate.","cn":"weathering 是动词 weather 的动名词，源自古英语 weder「空气、天空、风暴」。这个地质学名词是十九世纪从旧动词义「暴露于天气之中」扩展而来。年代均为约数。"},"items":[{"era":"OLD ENGLISH WEDER","en":"Weder meant 'air, sky, storm', and its deeper origin is not established; the Germanic form usually cited, *wedra-, is a reconstruction, not a recorded word.","cn":"weder 意为「空气、天空、风暴」，其更深来源未得到证明；通常引用的日耳曼语形式 *wedra- 属重构形式，并非有记录的词。"},{"era":"VERB 'TO EXPOSE'","en":"From the fifteenth century the verb weather meant to expose something to sun, rain and wind, and also to come through such exposure safely.","cn":"自十五世纪起，动词 weather 指让某物暴露于日晒、雨淋与风中，也指安全地经受住这种暴露。"},{"era":"GEOLOGICAL NOUN","en":"In the nineteenth century geologists made the gerund a technical noun for the decay of rock in place, and set it against erosion.","cn":"十九世纪地质学家把这个动名词变为专门名词，指岩石在原地的分解，并与侵蚀概念对举。"},{"era":"CHEMICAL SPLIT","en":"Twentieth-century work divided the process into mechanical, chemical and biological weathering, each with its own agents.","cn":"二十世纪的研究把这一过程分为机械风化、化学风化与生物风化，各有自己的营力。"},{"era":"BURIAL SCIENCE","en":"Late twentieth-century taphonomy borrowed the word for graded bone damage, giving archaeologists a way to estimate surface exposure.","cn":"二十世纪后期的埋藏学借这个词指分级的骨骼损伤，使考古学家可以估算地表暴露时间。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): no agreed pre-Germanic source for weder exists, and every older form offered for it is a reconstruction.","cn":"来源不确定（更深词源）：weder 在日耳曼语之前没有公认的来源，凡为其提供更早形式者均属重构形式。"}]},"similar":{"note":{"en":"Group one gathers words that look close to weathering but do not share its history; group two gathers processes that also break material down but by different means.","cn":"第一组列的是与 weathering 形近却不同源的词；第二组列的是同样使材料分解、但营力不同的过程词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"weather","ipa":"/ˈweðə/","tag":"same family","definition":"The base verb and noun of the same word stock: it names the exposure itself, while weathering names the resulting process.","definitionCN":"同一词族的动词与名词：它指暴露本身，weathering 则指由此形成的过程。"},{"word":"wither","ipa":"/ˈwɪðə/","tag":"different root","definition":"From Old English wiþerian 'to become dry, shrivel'; the resemblance to weather is accidental, since it has no sense of sky or storm.","definitionCN":"源自古英语 wiþerian「变干、枯萎」；与 weather 的相似只是偶然，它并无天空或风暴之义。"},{"word":"withering","ipa":"/ˈwɪðərɪŋ/","tag":"suffix look-alike","definition":"Also ends in -ing, but it means shrivelling or a crushing remark, never rock decay.","definitionCN":"同样以 -ing 结尾，但指枯萎或令人难堪的言辞，与岩石分解无关。"},{"word":"weathered","ipa":"/ˈweðəd/","tag":"same family, other form","definition":"The past participle used as an adjective: it describes the result, while weathering names the process that produced it.","definitionCN":"过去分词作形容词：它描写结果，weathering 指造成该结果的过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"erosion","ipa":"/ɪˈrəʊʒn/","tag":"removal after breakdown","definition":"Weathering breaks rock where it lies; erosion then carries the loosened material away with water, wind or ice.","definitionCN":"风化在原地把岩石打碎；侵蚀随后用水、风或冰把松动的物质搬走。"},{"word":"corrosion","ipa":"/kəˈrəʊʒn/","tag":"chemical eating away","definition":"The chemical attack of metal or stone by acids and salts; it is one path within chemical weathering, not the whole process.","definitionCN":"酸与盐对金属或石材的化学侵蚀，是化学风化中的一条途径，不等于整个风化过程。"},{"word":"abrasion","ipa":"/əˈbreɪʒn/","tag":"rubbing wear","definition":"Wear caused by moving particles grinding a surface, a mechanical agent that works only where sediment is in motion.","definitionCN":"运动颗粒磨擦表面造成的磨损，只在有沉积物移动处起作用，属机械营力。"},{"word":"decay","ipa":"/dɪˈkeɪ/","tag":"general spoiling","definition":"A broad word for going bad, used of wood, food or stone; it adds no information about the agents involved.","definitionCN":"泛指变坏的通用词，可用于木材、食物或石材，但不说明具体营力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Old English weder 'sky, storm' plus -ing: what the sky keeps doing to stone.","cn":"古英语 weder「天空、风暴」加 -ing：天空对石头反复做的事。"},{"en":"The family runs weather, weathered, weather-beaten, weatherproof, weatherability.","cn":"同族词包括 weather、weathered、weather-beaten、weatherproof、weatherability。"},{"en":"Textbooks pair the word: weathering breaks rock, erosion carries it away.","cn":"教材常成对使用：风化打碎岩石，侵蚀将其搬走。"},{"en":"Fixed phrases mark the types: chemical, mechanical, frost weathering.","cn":"固定搭配标出类型：化学风化、机械风化、冻融风化。"},{"en":"The word is uncountable in its geological sense, so one says the weathering of the cliff, not a weathering.","cn":"地质义不可数，应说崖壁的风化，而不说一个风化。"}],"abstract":[{"en":"Picture a stone face losing a grain of dust each year until the features go soft.","cn":"想象一张石脸每年掉一粒尘，直到五官变圆钝。"},{"en":"Picture a letter left on a windowsill until the ink fades to grey.","cn":"想象一封信留在窗台上，字迹被晒褪成灰色。"},{"en":"Picture an old rule that nobody repeals but nobody obeys any more.","cn":"想象一条没人废除、却也无人再遵守的旧规矩。"}]},"examples":[{"en":"Weathering has smoothed the carved letters until they can barely be read.","cn":"风化把刻字磨平，几乎读不出来了。"},{"en":"In dry valleys, salt crystallization is the main agent of weathering.","cn":"在干旱谷地，盐结晶是风化的主要营力。"},{"en":"The report separates weathering damage from the cracks caused by traffic.","cn":"报告把风化损伤与交通造成的裂缝分开处理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「weather（天气）+ ing（过程）」——天气天天磨，石头慢慢散 → 风化","word":"weathering"},"root":"古英语 weder「天空、风暴」+ 动名词后缀 -ing；weder 的更深来源不确定，常见日耳曼语 *wedra- 属重构形式。","sensesIntro":{"en":"Eight senses follow one physical story: exposure opens the rock, agents split it, and then the same image is measured, blamed on industry, applied to buildings and finally to institutions.","cn":"八个义项沿同一条物理线索展开：暴露使岩石开口，营力把它分开；随后同一意象被用于计量、归咎于工业、用于建筑，最后用于制度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cliff losing one grain at a time while the weather works on it.","cn":"核心意象：崖壁在天气反复作用下，一次掉下一粒碎屑。"},"chain":["EXPOSURE","SPLITTING","IN PLACE","MINERAL CHANGE","HUMAN SPEED-UP","SLOW WEAR OF ANYTHING"],"branches":[{"senses":"S1 · S3","en":"MECHANICAL SPLIT: water and ice open the joints before anything is carried off.","cn":"机械撑裂：水与冰先把节理撑开，尚未搬走任何东西。"},{"senses":"S2 · S4","en":"LIVING AND CHEMICAL AGENTS: acids from air, water and lichens alter the minerals themselves.","cn":"化学与生物营力：来自空气、水和地衣的酸改变矿物本身。"},{"senses":"S5 · S6","en":"HUMAN-ADDED WEAR: the same process, but faster and mapped on standing buildings.","cn":"人为叠加的损耗：过程相同，只是更快，并被测绘在现存建筑上。"},{"senses":"S8","en":"MEASURED EXPOSURE: burial science turns the process into a countable grade.","cn":"可计量的暴露：埋藏学把过程变成可计数的等级。"},{"senses":"S7","en":"INSTITUTIONAL METAPHOR: pressure that never strikes still changes the outline.","cn":"制度的隐喻：从未重击的压力仍会改变轮廓。"}]},"affixes":{"intro":{"en":"Weathering is a Germanic base plus a native suffix, so its parts are read as English morphemes rather than Latin ones.","cn":"weathering 是日耳曼语词基加本族后缀构成，其成分应按英语语素而非拉丁语素来读。"},"latinIntro":{"en":"The base weder has no reliable Latin cognate, so latinEntries is left empty rather than filled with a guessed form.","cn":"词基 weder 没有可靠的拉丁同族词，因此 latinEntries 留空，而不填入猜测形式。"},"items":[{"word":"weather","structure":"weder (Old English noun 'air, sky, storm')","meaning":"sky, storm","meaningCN":"天空；风暴","example":"The weather turned before we reached the col.","exampleCN":"我们还没到垭口，天气就变了。"},{"word":"-ing","structure":"-ing (Old English gerund and noun suffix)","meaning":"process or result","meaningCN":"过程；结果","example":"The breaking of the rock took centuries.","exampleCN":"岩石的破碎历经数百年。"},{"word":"weathering","structure":"weather + -ing","meaning":"the process of being worn by exposure","meaningCN":"暴露于天气而被磨蚀的过程","example":"Weathering widened the joint year by year.","exampleCN":"风化年复一年地把节理撑宽。"},{"word":"weathered","structure":"weather + -ed (past participle as adjective)","meaning":"worn by long exposure","meaningCN":"久经风雨而磨损的","example":"The weathered stone crumbled under the trowel.","exampleCN":"风化的石头在铲下碎成粉末。"},{"word":"weather-beaten","structure":"weather + beaten (compound with a participle)","meaning":"marked by long exposure","meaningCN":"被风雨刻出痕迹的","example":"A weather-beaten sign hung over the door.","exampleCN":"门上方挂着一块饱经风雨的旧招牌。"},{"word":"weatherproof","structure":"weather + -proof (free from)","meaning":"resisting wind and rain","meaningCN":"防风雨的","example":"The case is weatherproof and floats.","exampleCN":"这箱子防风雨，还能浮起来。"},{"word":"weatherability","structure":"weather + -able (capable) + -ity (state)","meaning":"the capacity to resist weather","meaningCN":"抗风化能力","example":"Tests rank the stone by weatherability.","exampleCN":"试验按抗风化能力给石料排序。"},{"word":"weatherize","structure":"weather + -ize (make)","meaning":"to make a building resistant","meaningCN":"使建筑耐候","example":"They weatherized the windows before winter.","exampleCN":"入冬前他们给窗户做了耐候处理。"},{"word":"weathering steel","structure":"weathering + steel (compound)","meaning":"steel that forms a protective rust layer","meaningCN":"耐候钢","example":"The bridge uses weathering steel instead of paint.","exampleCN":"这座桥用耐候钢，不刷漆。"}],"latinEntries":[]}},{"word":"weather","ipa_uk":"/ˈweðə/","ipa_us":"/ˈweðər/","definition_zh":"天气；恶劣天气；经受住、渡过（难关）；使受日晒雨淋而风化；上风的","definition_en":"the state of the atmosphere at a particular place and time, or to come through a difficult period safely","core_image":"山顶的风把旗子吹得笔直，云从西边一层层压过来","scene":"山顶气象站外，风向标转得飞快，值班员把领子竖起来才敢推门。 A front is moving in, and the weather on the ridge turns foul by noon.","sceneCN":"这里 weather 指「某时某地的天气状况」（第 1 个义项：大气在特定时间地点的状态）；句意为一道锋面正在移来，中午前山脊上的天气就会变坏。图中可辨识物件：风向标、翻卷的云、百叶箱、被风压弯的草。","pos":[{"tag":"n.","zh":"天气；恶劣天气；（航海）上风的一侧"},{"tag":"v.","zh":"经受住、渡过；使受日晒雨淋而风化；使露天放置陈化"},{"tag":"adj.","zh":"上风的、迎风的（航海用语）"}],"collocations":[{"phrase":"weather forecast","zh":"天气预报"},{"phrase":"bad weather","zh":"恶劣天气"},{"phrase":"weather the storm","zh":"渡过风暴；挺过难关"},{"phrase":"weather conditions","zh":"天气状况"},{"phrase":"weather pattern","zh":"天气型；天气格局"},{"phrase":"under the weather","zh":"身体不适"}],"forms":[{"label":"名词（天气，不可数）","form":"weather"},{"label":"名词复数（多种天气类型，少用）","form":"weathers"},{"label":"三单（he/she/it）","form":"weathers"},{"label":"过去式","form":"weathered"},{"label":"过去分词","form":"weathered"},{"label":"现在分词","form":"weathering"}],"derivatives":[{"word":"weathering","pos":"n.","zh":"风化（作用）"},{"word":"weathered","pos":"adj.","zh":"风化的；饱经风霜的"},{"word":"weatherly","pos":"adj.","zh":"能抢风航行的；上风的"},{"word":"weatherproof","pos":"adj./v.","zh":"防风雨的；使能抗风雨"},{"word":"weatherman","pos":"n.","zh":"气象播报员（口语）"}],"senses":[{"no":"01","title":"Atmospheric state","titleCN":"某时某地的大气状态","definition":"the condition of the atmosphere at a given place and time, described in terms of heat, cloud, wind and rain","definitionCN":"特定地点与时间的大气状况，以冷热、云量、风与雨来描述","example":"The weather on the coast changes faster than any forecast can follow.","exampleCN":"海岸的天气变化之快，任何预报都跟不上。","why":"the noun is uncountable here because it names a continuous state rather than one countable event.","whyCN":"此处名词不可数，因为它指一种持续状态，而非一次可计数的事件。"},{"no":"02","title":"Rough weather","titleCN":"恶劣天气、风暴","definition":"stormy or otherwise severe conditions that threaten travel, crops or safety","definitionCN":"威胁出行、作物或安全的暴烈天气","example":"Fishing boats stayed in harbour through three days of weather.","exampleCN":"渔船在恶劣天气里躲进港内三天。","why":"English often uses the bare noun where other languages need an adjective: the weather turned means it turned bad.","whyCN":"英语常用光秃秃的名词表达贬义，天气变了就等于天气变坏了。"},{"no":"03","title":"Come through safely","titleCN":"经受住、平安渡过","definition":"to survive a storm, a crisis or a period of difficulty without being destroyed","definitionCN":"在风暴、危机或困难时期中幸存而不被摧毁","example":"The small bank weathered the panic better than its rivals.","exampleCN":"这家小银行比对手更好地挺过了那场恐慌。","why":"the nautical image is of a ship that stays afloat through rough seas; the verb keeps that sense of enduring rather than avoiding.","whyCN":"航海意象是一艘船在狂浪中仍浮着；动词保留的是「承受而非避开」的意思。"},{"no":"04","title":"Wear away by exposure","titleCN":"因日晒雨淋而风化、变色","definition":"to become worn, faded or cracked through long exposure to sun, rain and frost","definitionCN":"长期暴露于日晒、雨淋与霜冻而磨损、褪色或开裂","example":"The unpainted shutters had weathered to a pale grey.","exampleCN":"没上漆的百叶窗已被风雨磨成浅灰色。","why":"this is the intransitive twin of the geological noun: the object does the changing itself, without any agent acting on it.","whyCN":"这是地质名词的不及物孪生用法：物件自行改变，并无外力直接施为。"},{"no":"05","title":"Season timber in the open","titleCN":"把木材露天放置使其陈化","definition":"to leave timber or stone exposed to the air so that it dries and stabilises before use","definitionCN":"把木材或石料露天放置，使其在使用前干燥稳定","example":"They weather the oak boards for two years before planing them.","exampleCN":"他们把橡木板露天放两年，再刨平使用。","why":"the same exposure that damages rock is deliberately used here to prevent later warping, so the sense is technical rather than negative.","whyCN":"使岩石受损的同一种暴露，此处被有意用来防止日后变形，因此这一义偏技术而非贬义。"},{"no":"06","title":"Windward side","titleCN":"上风的、迎风的一侧","definition":"the side of a ship or ridge from which the wind blows, or the adjective describing that side","definitionCN":"船或山脊迎风的一侧，或形容该侧的形容词","example":"Keep to the weather side of the buoy as you round it.","exampleCN":"绕过浮标时，要保持在它的上风侧。","why":"sailors needed a word for the side that takes the wind first, and the noun already meant storm, so the sense came free.","whyCN":"水手需要一个词指最先受风的一侧，而名词本已含风暴义，这一用法便自然生出。"},{"no":"07","title":"Under the weather","titleCN":"习语：身体不适","definition":"feeling slightly ill or out of sorts, without naming a specific disease","definitionCN":"略感不适、精神不振，而不特指某种疾病","example":"She stayed home because she was a little under the weather.","exampleCN":"她觉得有点不舒服，就留在家里了。","why":"the idiom comes from sailors sent below when seasick; being under the weather meant being under the deck in bad conditions.","whyCN":"这个习语来自晕船的水手被送到舱下：在不佳的天气里待在甲板之下。"},{"no":"08","title":"Survive a public storm","titleCN":"抽象义：熬过舆论风波","definition":"to keep a reputation or an institution intact through public criticism or scandal","definitionCN":"在公众批评或丑闻中保持声誉或机构完整","example":"The university weathered the scandal without losing its accreditation.","exampleCN":"这所大学熬过了丑闻，没有失去认证资格。","why":"the metaphor transfers rough seas to public opinion: the vessel is a reputation, and staying afloat is staying credible.","whyCN":"比喻把狂浪移到舆论上：船成了声誉，不沉就是仍可信。"}],"etymology":{"intro":{"en":"Weather descends from Old English weder 'air, sky, storm', a word shared across the Germanic languages. Its deeper pre-Germanic source is unknown. Dates are approximate.","cn":"weather 源自古英语 weder「空气、天空、风暴」，为日耳曼诸语共有。其在日耳曼语之前的更早来源不明。年代均为约数。"},"items":[{"era":"OLD ENGLISH WEDER","en":"Weder named the sky and whatever came out of it, including storms; the modern restriction to atmospheric conditions came later.","cn":"weder 指天空以及从天而降的一切，包括风暴；后来才收窄为大气状况。"},{"era":"VERB OF EXPOSURE","en":"From the fifteenth century the verb meant to expose something to the open air, and by extension to endure such exposure.","cn":"自十五世纪起，动词指让某物暴露于露天，并引申为承受这种暴露。"},{"era":"NAUTICAL USE","en":"Sailors used the noun for the windward side and the verb for coming through a gale, and both senses entered general English.","cn":"水手用名词指上风侧，用动词指闯过狂风，这两个义项都进入了通用英语。"},{"era":"IDIOM","en":"The phrase under the weather, recorded in the nineteenth century, referred to sailors sent below decks when seasick.","cn":"under the weather 这一短语见于十九世纪，指晕船的水手被送到甲板之下。"},{"era":"GEOLOGICAL SHIFT","en":"Geology took the same verb for rock decay, giving weathering, where the exposure itself is the agent.","cn":"地质学用同一个动词指岩石分解，由此产生 weathering，其中暴露本身即是营力。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Germanic ancestry of weder is unsettled, and any Indo-European root proposed for it is a reconstruction.","cn":"来源不确定（更深词源）：weder 在日耳曼语之前的谱系无定论，凡为其提出的印欧词根均属重构形式。"}]},"similar":{"note":{"en":"Group one separates weather from look-alikes that share its spelling pattern but not its history; group two separates it from words about climate, storms and exposure.","cn":"第一组把 weather 与拼写相近却不同源的词分开；第二组区分它与气候、风暴、暴露相关的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"whether","ipa":"/ˈweðə/","tag":"different word entirely","definition":"A conjunction from Old English hwæther 'which of two', built on the interrogative stem; it is homophonous with weather but unrelated.","definitionCN":"源自古英语 hwæther「两者中哪一个」的连词，建立在疑问词干上；与 weather 同音但无亲缘关系。"},{"word":"wither","ipa":"/ˈwɪðə/","tag":"different root","definition":"From Old English wiþerian 'to shrivel'; the shared -ther ending is coincidence, since wither has nothing to do with sky or storm.","definitionCN":"源自古英语 wiþerian「枯萎」；共有的 -ther 结尾只是巧合，wither 与天空或风暴无关。"},{"word":"weatherly","ipa":"/ˈweðəli/","tag":"same family, nautical","definition":"Weather plus -ly: able to sail close to the wind, a technical cousin rather than a synonym.","definitionCN":"weather 加 -ly：能抢风航行，是同族的技术用语，而非同义词。"},{"word":"weathered","ipa":"/ˈweðəd/","tag":"same family, other form","definition":"The participle used adjectivally for surfaces worn by exposure; it describes the result, not the atmospheric state.","definitionCN":"分词作形容词，指因暴露而磨损的表面；它描写结果，不指大气状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"climate","ipa":"/ˈklaɪmət/","tag":"long-term average","definition":"The usual pattern of weather over many years; weather is what you get today, climate is what you expect.","definitionCN":"多年天气的常规格局：weather 是今天遇到的，climate 是预期中的。"},{"word":"storm","ipa":"/stɔːm/","tag":"one severe event","definition":"A single violent disturbance with strong wind and rain; it is one kind of bad weather, not the general state.","definitionCN":"一次伴有强风与暴雨的剧烈扰动，是恶劣天气中的一种，而非一般状态。"},{"word":"conditions","ipa":"/kənˈdɪʃnz/","tag":"technical stand-in","definition":"A neutral plural used in reports for the state of the atmosphere, often when numbers follow.","definitionCN":"报告中用于指大气状态的中性复数，常在后接数据时使用。"},{"word":"exposure","ipa":"/ɪkˈspəʊʒə/","tag":"the action of exposing","definition":"Being left open to the elements; it names the cause that weather, as a verb, sets in motion.","definitionCN":"被置于露天之中；它指 weather 作动词时所启动的那个原因。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The noun is uncountable: one says fine weather, not a fine weather.","cn":"名词不可数：应说好天气，而不说一个好天气。"},{"en":"The verb keeps the nautical sense of enduring: weather the storm, weather the recession.","cn":"动词保留航海的「承受」义：渡过风暴、挺过衰退。"},{"en":"The family runs weathering, weathered, weatherly, weatherproof, weatherman.","cn":"同族词包括 weathering、weathered、weatherly、weatherproof、weatherman。"},{"en":"The idiom under the weather is about being seasick below decks, not about rain.","cn":"习语 under the weather 指在舱下晕船，与下雨无关。"},{"en":"Do not confuse the homophone whether, which introduces alternatives.","cn":"勿与同音词 whether 混淆，后者引出两种选择。"}],"abstract":[{"en":"Picture a flag nailed to a mast, taking whatever the sky sends.","cn":"想象一面钉在桅杆上的旗，天空给什么它就受什么。"},{"en":"Picture a ship that stays upright not by hiding but by riding each wave.","cn":"想象一艘船不靠躲避、而靠随浪起伏而保持直立。"},{"en":"Picture a wooden bench outdoors, silvered by years of sun and rain.","cn":"想象一张户外木凳，被多年日晒雨淋漂成银灰色。"}]},"examples":[{"en":"The weather closed in and the ferry stopped running.","cn":"天气变坏，渡轮停航了。"},{"en":"Their savings weathered the recession better than expected.","cn":"他们的储蓄比预期更好地挺过了衰退。"},{"en":"Leave the planks outdoors to weather before you oil them.","cn":"上油之前先把木板放在户外陈化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「喂（wea）— 遮（ther）」——天要变，先给自己遮一遮 → 天气；扛过去 → 经受住","word":"weather"},"root":"古英语 weder「空气、天空、风暴」，日耳曼诸语共有；其日耳曼语之前的来源不明，不作臆测。","sensesIntro":{"en":"Eight senses run from the sky itself to the act of surviving it: first the state, then the storm, then endurance, then the slow damage exposure causes, and at last a reputation that stays afloat.","cn":"八个义项从天空本身走到「承受天空」这一动作：先是状态，再是风暴，再是承受，再是暴露造成的缓慢损伤，最后是仍浮着的声誉。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flag on a mast taking whatever the sky sends, and still standing.","cn":"核心意象：桅杆上的旗承受天空送来的一切，却仍立着。"},"chain":["SKY STATE","SEVERE TURN","ENDURE","WORN BY OPEN AIR","SEASONED IN OPEN AIR","WINDWARD SIDE"],"branches":[{"senses":"S1 · S2","en":"THE SKY ITSELF: a neutral state that can turn hostile without changing its name.","cn":"天空本身：中性的状态可以在不改名的情况下转为敌意。"},{"senses":"S3 · S8","en":"ENDURE: the ship that stays afloat is first a hull, then a reputation.","cn":"承受：仍浮着的先是船体，后来是声誉。"},{"senses":"S4 · S5","en":"OPEN AIR AT WORK: the same exposure either damages or deliberately seasons.","cn":"露天的作用：同一种暴露，或造成损伤，或被有意用于陈化。"},{"senses":"S6","en":"WINDWARD: the side that meets the weather first gives the noun a physical position.","cn":"上风侧：最先迎受天气的一侧，使名词有了实体的方位。"},{"senses":"S7","en":"BELOW DECKS: seasickness became a mild everyday phrase for feeling unwell.","cn":"甲板之下：晕船变成了日常说身体不适的轻微说法。"}]},"affixes":{"intro":{"en":"Weather is a native Germanic word with native suffixes and compounds, so each part is English rather than Latin.","cn":"weather 是日耳曼语本族词，配本族后缀与复合成分，各部分属英语而非拉丁语。"},"latinIntro":{"en":"No reliable Latin cognate of weder is known, so latinEntries is left empty instead of carrying a reconstruction.","cn":"weder 没有已知可靠的拉丁同族词，因此 latinEntries 留空，不填重构形式。"},"items":[{"word":"weather","structure":"weder (Old English noun 'air, sky, storm')","meaning":"sky, storm","meaningCN":"天空；风暴","example":"The weather broke at dawn.","exampleCN":"天一亮，天气就变了。"},{"word":"-ly","structure":"-ly (Old English adjectival suffix)","meaning":"having the quality of","meaningCN":"具有……性质的","example":"A weatherly hull can hold the wind.","exampleCN":"上风的船体吃得住风。"},{"word":"-ed","structure":"-ed (past participle as adjective)","meaning":"affected by","meaningCN":"受……影响的","example":"The weathered paint flaked away.","exampleCN":"风化的漆皮一片片剥落。"},{"word":"-proof","structure":"-proof (compound suffix 'resisting')","meaning":"resistant to","meaningCN":"防……的","example":"A weatherproof jacket keeps the rain out.","exampleCN":"防风雨的外套能挡住雨。"},{"word":"-man","structure":"-man (agent suffix in compounds)","meaning":"person concerned with","meaningCN":"从事……的人","example":"The weatherman promised a dry weekend.","exampleCN":"气象播报员说周末无雨。"},{"word":"weathering","structure":"weather + -ing","meaning":"the process of decay by exposure","meaningCN":"因暴露而损耗的过程","example":"Weathering roughened the carved stone.","exampleCN":"风化使石刻表面变糙。"},{"word":"weathered","structure":"weather + -ed","meaning":"worn or seasoned by exposure","meaningCN":"因暴露而磨损或陈化的","example":"Weathered oak needs no stain.","exampleCN":"陈化的橡木不必上色。"},{"word":"weather-beaten","structure":"weather + beaten","meaning":"marked by long exposure","meaningCN":"被风雨刻出痕迹的","example":"A weather-beaten hut stood on the point.","exampleCN":"岬角上立着一间饱经风雨的小屋。"},{"word":"weatherize","structure":"weather + -ize","meaning":"to make resistant to weather","meaningCN":"使耐候","example":"They weatherized the roof seams.","exampleCN":"他们给屋顶接缝做了耐候处理。"}],"latinEntries":[]}},{"word":"deposit","ipa_uk":"/dɪˈpɒzɪt/","ipa_us":"/dɪˈpɑːzɪt/","definition_zh":"沉积物；矿床；押金；存款；沉积、沉淀；存放","definition_en":"material laid down by water, wind or ice, a sum of money held as security or in a bank, or the act of laying something down","core_image":"洪水退去，河滩上留下一层均匀的细泥，草叶被埋住半截","scene":"河湾内侧的水流慢下来，细沙一层层落下，测量员插下标杆记录淤高。 Fine sand began to deposit along the inner bend, thickening the bar each flood.","sceneCN":"这里 deposit 指「沉积物被水流放下、堆积起来」（第 5 个义项：水流搬运的物质因流速降低而落下）；句意为细沙开始沉积在河湾内侧，每场洪水都把沙坝垫高一点。图中可辨识物件：缓流、落下的细沙、标杆、被埋半截的草。","pos":[{"tag":"n.","zh":"沉积物；沉积层；矿床；押金；存款；寄存物"},{"tag":"v.","zh":"沉积；使沉淀；存放；放下；付押金"}],"collocations":[{"phrase":"ore deposit","zh":"矿床"},{"phrase":"sediment deposit","zh":"沉积层"},{"phrase":"security deposit","zh":"押金"},{"phrase":"bank deposit","zh":"银行存款"},{"phrase":"mineral deposit","zh":"矿藏"},{"phrase":"deposit account","zh":"存款账户"}],"forms":[{"label":"名词（沉积物；押金；存款）","form":"deposit"},{"label":"名词复数","form":"deposits"},{"label":"三单（he/she/it）","form":"deposits"},{"label":"过去式","form":"deposited"},{"label":"过去分词","form":"deposited"},{"label":"现在分词","form":"depositing"}],"derivatives":[{"word":"deposition","pos":"n.","zh":"沉积（作用）；沉淀；证词"},{"word":"depositional","pos":"adj.","zh":"沉积的；沉积形成的"},{"word":"depositor","pos":"n.","zh":"存款人；寄存人"},{"word":"depository","pos":"n.","zh":"存放处；储藏库"},{"word":"redeposit","pos":"v.","zh":"再沉积；再存入"}],"senses":[{"no":"01","title":"Layer left by water or wind","titleCN":"水或风留下的沉积层","definition":"a body of loose material that has settled out of water, wind or ice and now forms a layer","definitionCN":"由水、风或冰携来并落下的松散物质所构成的层","example":"A thick deposit of silt covered the floodplain after the spring flood.","exampleCN":"春汛过后，一层厚厚的粉砂覆盖了河漫滩。","why":"the noun begins as the thing that has been put down, so any agent that drops its load produces a deposit.","whyCN":"这个名词起初指被放下的东西，因此任何卸下负载的营力都会留下沉积物。"},{"no":"02","title":"Ore or mineral deposit","titleCN":"矿床、矿藏","definition":"a concentration of ore or mineral in the ground rich enough to be worked","definitionCN":"地壳中富集到可开采程度的矿石或矿物","example":"The copper deposit lies under two hundred metres of sandstone.","exampleCN":"这座铜矿位于两百米厚的砂岩之下。","why":"economic geology narrowed the general noun: what matters here is not the layer but the value that can be extracted from it.","whyCN":"经济地质学收窄了这个通用名词：这里要紧的不是层本身，而是可从中提取的价值。"},{"no":"03","title":"Money paid as security","titleCN":"作为担保支付的押金","definition":"a sum handed over in advance and held in case of damage, loss or default","definitionCN":"预先交付并被留存、以备损坏、遗失或违约的款项","example":"The landlord returned the deposit after the flat was inspected.","exampleCN":"房东在检查公寓之后退还了押金。","why":"the medieval sense of something entrusted for safekeeping produced the financial one: the sum is placed with another party and later returned.","whyCN":"中世纪「交托保管之物」的义项衍生出金融义：款项被放在对方手中，日后归还。"},{"no":"04","title":"Money placed in a bank","titleCN":"存入银行的款项","definition":"money put into a bank account, or the credit so created","definitionCN":"存入银行账户的钱，或由此形成的贷方余额","example":"She made a deposit of three hundred pounds at the counter.","exampleCN":"她在柜台存入三百英镑。","why":"banking extended the same idea from goods to money: the bank holds what you have placed with it.","whyCN":"银行业把同一观念从货物移到金钱：银行替你保管你所放置之物。"},{"no":"05","title":"Lay sediment down","titleCN":"使沉积物落下堆积","definition":"to let carried sediment settle out of water, wind or ice at a new place","definitionCN":"使被搬运的沉积物在水、风或冰中于新地点落下","example":"The river deposits sand where its current slows at the bend.","exampleCN":"河流在弯道流速减慢处沉积细沙。","why":"as a verb the word describes the agent's action, the exact counterpart of the noun sense one.","whyCN":"作动词时描述营力的动作，正好与第一义的名词用法对应。"},{"no":"06","title":"Put something down","titleCN":"把某物放下、存放","definition":"to place something somewhere, often carefully or officially, so that it stays there","definitionCN":"把某物放在某处，常含谨慎或正式意味，使其留在那里","example":"He deposited the samples in a locked cabinet and signed the log.","exampleCN":"他把样品放进上锁的柜子，并在登记簿上签字。","why":"the Latin verb simply meant to put down; English kept that plain physical sense alongside all the technical ones.","whyCN":"拉丁动词本义只是「放下」；英语把这个朴素的实义与全部技术义并存下来。"},{"no":"07","title":"Chemical precipitate","titleCN":"化学沉淀物、水垢","definition":"solid matter separated from a solution by a chemical reaction or by evaporation","definitionCN":"因化学反应或蒸发而从溶液中析出的固体","example":"A hard white deposit furred the inside of the kettle.","exampleCN":"水壶内壁结了一层坚硬的白色水垢。","why":"chemistry uses the noun for the solid left behind, which is laid down like sediment though the mechanism is different.","whyCN":"化学用这个名词指留下的固体，虽然机制不同，它同样是被「放下」的。"},{"no":"08","title":"Object held in trust","titleCN":"寄存的藏品或文件","definition":"an object or collection placed with a museum or archive for safekeeping rather than given outright","definitionCN":"为保管而非无偿转让而交由博物馆或档案馆保存的物件或藏品","example":"The letters arrived as a deposit and may be recalled by the family.","exampleCN":"这批书信是作为寄存品来的，家属可以取回。","why":"the legal sense of bailment survives in collecting institutions, where a deposit is held but not owned.","whyCN":"法律上的寄托关系在收藏机构中延续：寄存品被保管但不被拥有。"}],"etymology":{"intro":{"en":"Deposit comes from Latin deponere 'to put down', built on de- 'down' and ponere 'to place'. It reached English through French in the seventeenth century. Dates are approximate.","cn":"deposit 来自拉丁 deponere「放下」，由 de-「向下」与 ponere「放置」构成，十七世纪经法语进入英语。年代均为约数。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant 'to put, place, set down'; its perfect participle positus underlies position, positive and compose as well.","cn":"一般认为 ponere 意为「放、置、放下」；其完成分词 positus 也构成 position、positive 与 compose。"},{"era":"LATIN DEPONERE","en":"De- 'down' plus ponere produced deponere 'to put down, lay aside, entrust', whose participle depositus gives the English stem.","cn":"de-「向下」加 ponere 构成 deponere「放下、搁置、交托」，其分词 depositus 提供英语词干。"},{"era":"FRENCH ROUTE","en":"Old French deposer and the noun deposit passed into English in the seventeenth century, first in the sense of entrusting goods.","cn":"古法语 deposer 与名词 deposit 于十七世纪进入英语，最初指交托货物。"},{"era":"BANKING SENSE","en":"By the eighteenth and nineteenth centuries the word covered money placed with a banker and the security sum paid on a lease.","cn":"到十八、十九世纪，这个词已涵盖存入银行的钱与租约中支付的保证金。"},{"era":"GEOLOGICAL SENSE","en":"Geology then applied the same noun to material laid down by water, wind and ice, and to the ores so concentrated.","cn":"地质学随后用同一名词指水、风、冰放下的物质，以及由此富集的矿石。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (only the first dating is in doubt): the French noun and verb are well attested, but the exact century of their entry into English varies by sense.","cn":"来源不确定（仅首见年代存疑）：法语的名词与动词均有确证，但它们进入英语的确切世纪随义项而异。"}]},"similar":{"note":{"en":"Group one sorts deposit from look-alikes whose second element is a different verb; group two sorts it from other words for material that settles or money that is held.","cn":"第一组把 deposit 与第二个成分来自别的动词的形近词分开；第二组区分它与「沉降之物」「被留存的款项」的其它说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"depose","ipa":"/dɪˈpəʊz/","tag":"different root","definition":"From Old French deposer, built on de- plus poser from Late Latin pausare 'to rest'; it means to remove from office, not to lay down.","definitionCN":"来自古法语 deposer，由 de- 加后期拉丁 pausare「休息」派生的 poser 构成；意为免职，与放下无关。"},{"word":"depot","ipa":"/ˈdiːpəʊ/","tag":"same Latin line","definition":"From French dépôt, ultimately the same deponere: a place where things are deposited, hence a store or bus station.","definitionCN":"来自法语 dépôt，最终同出 deponere：存放东西之处，因此指仓库或车站。"},{"word":"deposition","ipa":"/dɪˈpɒzɪʃn/","tag":"same family","definition":"Deposit plus -ion: the act of laying down, whether sediment or sworn testimony.","definitionCN":"deposit 加 -ion：放下的动作，可用于沉积，也可指宣誓证词。"},{"word":"depository","ipa":"/dɪˈpɒzɪtəri/","tag":"same family","definition":"Deposit plus -ory: the place or institution that holds what has been deposited.","definitionCN":"deposit 加 -ory：保管寄存之物的场所或机构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sediment","ipa":"/ˈsedɪmənt/","tag":"material, not the act","definition":"The collective term for particles settled by water or wind; deposit often names one such layer or body.","definitionCN":"水或风沉降颗粒的集合名词；deposit 常指其中一个层或一个矿体。"},{"word":"precipitate","ipa":"/prɪˈsɪpɪteɪt/","tag":"chemistry only","definition":"Solid matter thrown down from a solution by reaction; narrower than deposit, which also covers geological layers.","definitionCN":"反应使固体从溶液中析出；范围窄于 deposit，后者还包含地质层。"},{"word":"stake","ipa":"/steɪk/","tag":"a held sum","definition":"Money risked or pledged in a venture; it is put up rather than handed over for safekeeping.","definitionCN":"投入或押在某项事业上的钱；是拿出来冒险，而非交托保管。"},{"word":"collateral","ipa":"/kəˈlætərəl/","tag":"security in assets","definition":"Property pledged against a loan; it secures a debt without being a cash deposit.","definitionCN":"为贷款而抵押的财产；为债务担保，但不是现金押金。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"de- 'down' + ponere 'place': to put something down, and whatever ends up lying there.","cn":"de-「向下」+ ponere「放置」：把某物放下，以及由此留在那里的东西。"},{"en":"The same ponere builds position, positive, compose, expose and impose.","cn":"同一 ponere 还构成 position、positive、compose、expose 与 impose。"},{"en":"Geology says a deposit; chemistry says a precipitate; banking says a deposit too, but the thing held is money.","cn":"地质说 deposit，化学说 precipitate，银行也说 deposit，只是被留存的东西是钱。"},{"en":"Fixed phrases: ore deposit, security deposit, bank deposit.","cn":"固定搭配：矿床、押金、银行存款。"},{"en":"The verb and the noun share one form, so context decides whether an action or a thing is meant.","cn":"动词与名词同形，由语境判断指动作还是指物。"}],"abstract":[{"en":"Picture a flood dropping its load and walking away, leaving a smooth sheet behind.","cn":"想象洪水卸下负载后走开，留下一片平滑的淤层。"},{"en":"Picture a key handed to a neighbour and returned only when you ask.","cn":"想象把钥匙交给邻居，只有你开口才拿回来。"},{"en":"Picture a kettle bottom furred white by every boiled litre.","cn":"想象壶底被每一升煮过的水结出白垢。"}]},"examples":[{"en":"Rich deposits of tin were found along the valley floor.","cn":"沿谷底发现了富锡矿藏。"},{"en":"The tenant paid one month's rent as a deposit.","cn":"租客付了一个月租金作押金。"},{"en":"Wind deposits fine loess hundreds of kilometres from its source.","cn":"风把细黄土沉积在距源地数百公里之外。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「de（下）+ posit（放）」——放到底下去 → 沉积；先放下的钱 → 押金、存款","word":"deposit"},"root":"拉丁 deponere「放下、交托」= de-（向下）+ ponere（放置），分词 depositus；英语经法语 deposit 进入。","sensesIntro":{"en":"Eight senses follow one gesture: something is put down and stays. That gesture covers silt, ore, cash handed over, cash banked, a sample on a shelf and a solid formed in a kettle.","cn":"八个义项沿同一个动作展开：某物被放下并留在那里。这个动作覆盖粉砂、矿石、交付的现金、存入的钱、架上样品，以及壶中结成的固体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand releasing something that settles and stays where it landed.","cn":"核心意象：一只手松开，某物沉降并留在落下的位置。"},"chain":["SET DOWN","SETTLE OUT","LIE IN LAYERS","ACCUMULATE VALUE","HAND OVER","HOLD ON BEHALF"],"branches":[{"senses":"S1 · S5","en":"SEDIMENT: the same event seen as a thing and as an action.","cn":"沉积：同一事件，一面看作物体，一面看作动作。"},{"senses":"S2","en":"VALUE IN THE GROUND: a layer becomes a resource when it can be worked.","cn":"地下价值：层一旦可开采便成为资源。"},{"senses":"S3 · S4","en":"MONEY HELD: first as security, then as a bank balance.","cn":"留存的钱：先是担保，后是银行余额。"},{"senses":"S6 · S8","en":"PLACED AND KEPT: a sample in a cabinet, a collection in an archive.","cn":"放置并保管：柜中的样品，档案中的藏品。"},{"senses":"S7","en":"SOLID FROM SOLUTION: chemistry reaches the same shape by a different route.","cn":"溶液中的固体：化学以另一条路径得到同样的形态。"}]},"affixes":{"intro":{"en":"Deposit is a Latin verb whose prefix and root both recur in English, so the family can be read morpheme by morpheme.","cn":"deposit 是拉丁动词，其前缀与词根都在英语中反复出现，因此这个词族可逐语素读出。"},"latinIntro":{"en":"Latin ponere 'to place' gives deposit, position, positive, compose, expose and impose; de- adds the sense of downward movement or completion.","cn":"拉丁 ponere「放置」衍生 deposit、position、positive、compose、expose、impose；de- 增添向下或完成之意。"},"items":[{"word":"de-","structure":"de- (Latin prefix 'down, away, completely')","meaning":"down; away; fully","meaningCN":"向下；离开；完全","example":"The prefix marks a downward movement.","exampleCN":"这个前缀标出向下的动作。"},{"word":"ponere","structure":"ponere (Latin verb, third conjugation; participle positus)","meaning":"to put, place","meaningCN":"放置；安放","example":"The root is the plain verb of placing.","exampleCN":"这个词根就是「放置」的朴素动词。"},{"word":"deposit","structure":"de- + ponere","meaning":"to put down","meaningCN":"放下；沉积","example":"The river deposits silt at the bend.","exampleCN":"河流在弯道沉积粉砂。"},{"word":"deposition","structure":"deposit + -ion (action or result)","meaning":"a laying down","meaningCN":"沉积（动作或结果）","example":"Deposition built the delta outward.","exampleCN":"沉积使三角洲向外生长。"},{"word":"depositor","structure":"deposit + -or (one who acts)","meaning":"one who places money","meaningCN":"存款人","example":"The depositor kept the receipt.","exampleCN":"存款人保留了回执。"},{"word":"depository","structure":"deposit + -ory (place)","meaning":"a place of safekeeping","meaningCN":"存放处；储藏库","example":"The map room serves as a depository.","exampleCN":"地图室兼作储藏库。"},{"word":"depositional","structure":"deposition + -al (relating to)","meaning":"of the laying down of sediment","meaningCN":"沉积的","example":"The depositional plain is flat and wet.","exampleCN":"沉积平原平坦而潮湿。"},{"word":"redeposit","structure":"re- (again) + deposit","meaning":"to lay down again","meaningCN":"再沉积；再存入","example":"Storms redeposit sand on the bar.","exampleCN":"风暴把沙再沉积到沙坝上。"},{"word":"deposit account","structure":"deposit + account (compound)","meaning":"an account for saved money","meaningCN":"存款账户","example":"Interest is paid on the deposit account.","exampleCN":"存款账户计付利息。"}],"latinEntries":[{"word":"deponere","structure":"deponere, deposui, depositum (verb, third conjugation)","meaning":"to put down, lay aside, entrust","meaningCN":"放下；搁置；交托"},{"word":"ponere","structure":"ponere, posui, positum (verb, third conjugation)","meaning":"to place, set","meaningCN":"放置；安放"},{"word":"depositum","structure":"depositum, depositi (n., second declension)","meaning":"a thing deposited; a trust","meaningCN":"寄存物；寄托"},{"word":"depositor","structure":"depositor, depositoris (m., third declension)","meaning":"one who deposits","meaningCN":"寄存人；存放者"}]}},{"word":"stratification","ipa_uk":"/ˌstrætɪfɪˈkeɪʃn/","ipa_us":"/ˌstrætəfəˈkeɪʃn/","definition_zh":"分层；层理；社会分层；温度或密度分层；种子层积处理","definition_en":"the arrangement of material, people or data in distinct layers, or the process that produces such layers","core_image":"一段被切开的土坡，深浅相间的薄层像被压紧的书页","scene":"老湖床被采砂场切开，深浅交替的薄层像压紧的书页，学生用尺量每一层的厚度。 Each color band records a year of stratification in the old lake bed.","sceneCN":"这里 stratification 指「沉积物按时间层层叠积形成层理的过程与结果」（第 1 个义项：地质上物质分层排列）；句意为每一道色带都记录了老湖床中一年的分层沉积。图中可辨识物件：采砂切面、深浅色带、卷尺、记录本。","pos":[{"tag":"n.","zh":"分层；层理；分层作用；社会阶层化；层积处理"}],"collocations":[{"phrase":"social stratification","zh":"社会分层"},{"phrase":"rock stratification","zh":"岩层分层"},{"phrase":"thermal stratification","zh":"温度分层"},{"phrase":"stratification system","zh":"分层体系"},{"phrase":"seed stratification","zh":"种子层积处理"},{"phrase":"stratification of society","zh":"社会的阶层化"}],"forms":[{"label":"名词（分层，本义）","form":"stratification"},{"label":"名词复数（较少用）","form":"stratifications"},{"label":"相关动词","form":"stratify"},{"label":"动词三单","form":"stratifies"},{"label":"过去分词（形容词）","form":"stratified"},{"label":"现在分词","form":"stratifying"}],"derivatives":[{"word":"stratify","pos":"v.","zh":"使分层；层积；按层排列"},{"word":"stratified","pos":"adj.","zh":"分层的；分层的（抽样）"},{"word":"stratum","pos":"n.","zh":"层；地层；阶层"},{"word":"stratigraphic","pos":"adj.","zh":"地层学的；地层描述的"},{"word":"destratification","pos":"n.","zh":"去分层；打破分层"}],"senses":[{"no":"01","title":"Rock arranged in layers","titleCN":"岩石按层排列形成的层理","definition":"the layering of sedimentary rock, in which each bed records a separate episode of deposition","definitionCN":"沉积岩成层排列，每一层记录一次独立的沉积事件","example":"Stratification in the cliff is so regular that each bed can be traced for a mile.","exampleCN":"崖壁上的层理十分规整，每一层都能追踪一英里远。","why":"the suffix -fication marks a making or forming, so the noun names both the layered result and the process that produced it.","whyCN":"后缀 -fication 表示「使形成」，因此名词同时指分层的结果与造成它的过程。"},{"no":"02","title":"Social ranking into strata","titleCN":"社会划分为阶层","definition":"the division of a society into ranked groups distinguished by wealth, occupation or status","definitionCN":"社会按财富、职业或地位划分为有高低之别的群体","example":"Studies of stratification ask why birth still predicts income so strongly.","exampleCN":"分层研究追问：为何出身仍能如此强烈地预测收入。","why":"sociology borrowed the geological image deliberately: layers lie one above another, and the lower ones are hard to climb out of.","whyCN":"社会学有意借用地质意象：层一层压一层，下面的层难以爬出。"},{"no":"03","title":"The act of layering","titleCN":"使成层的动作或过程","definition":"the process by which material becomes arranged in layers, whether by settling, sorting or design","definitionCN":"物质因沉降、分选或人为设计而排列成层的过程","example":"Stratification began as soon as the current slowed and the coarse grains dropped out.","exampleCN":"流速一慢、粗颗粒落下，分层就开始了。","why":"as a process noun it answers how, not what: the emphasis falls on the sorting that separates one layer from the next.","whyCN":"作为过程名词它回答「如何」而非「什么」，重点在把一层与下一层分开的分选作用。"},{"no":"04","title":"Thermal or density layering","titleCN":"温度或密度造成的分层","definition":"the separation of a body of water or air into layers that mix little because of temperature or salinity differences","definitionCN":"水体或大气因温度或盐度差异分成几乎不混合的层","example":"Thermal stratification keeps the cold deep water cut off from the surface in summer.","exampleCN":"夏季的温度分层使深层冷水与表层水隔开。","why":"physics uses the same noun because the water genuinely forms sheets that resist mixing, like beds of sediment.","whyCN":"物理学沿用同一名词，因为水体真的形成抗拒混合的水片，像沉积层一样。"},{"no":"05","title":"Cold treatment of seeds","titleCN":"种子层积处理（低温层积）","definition":"the practice of keeping moist seed at low temperature so that dormancy is broken and germination can start","definitionCN":"把湿润种子置于低温以打破休眠、促成发芽的处理","example":"The growers use stratification to bring apple seed out of dormancy.","exampleCN":"种植者用层积处理打破苹果种子的休眠。","why":"the older horticultural technique really did stack seed between layers of sand, so the name is literal before it is technical.","whyCN":"较早的园艺做法确实把种子夹在沙层之间，因此这个名称先是字面义，后成技术术语。"},{"no":"06","title":"Layering of vegetation","titleCN":"植被的成层现象","definition":"the vertical division of a plant community into canopy, shrub, herb and ground layers","definitionCN":"植物群落按冠层、灌木层、草本层与地被层在垂直方向分层","example":"Stratification in the rainforest decides which seedlings get any light at all.","exampleCN":"雨林中的成层结构决定了哪些幼苗能见到光。","why":"ecology extended the noun from rock to living cover, where each layer intercepts light before it reaches the next.","whyCN":"生态学把这个名词从岩石扩展到活植被：每层都在下一层之前截住光。"},{"no":"07","title":"Stratified sampling","titleCN":"分层抽样","definition":"the statistical practice of dividing a population into subgroups before sampling, so that each group is fairly represented","definitionCN":"抽样前先把总体分成若干子群，使各组都得到公平代表","example":"Stratification by district made the survey's margins of error much smaller.","exampleCN":"按地区分层使这项调查的误差范围小了很多。","why":"statistics took the noun for a designed layering, where the strata are chosen by the researcher rather than deposited by nature.","whyCN":"统计学借这个名词指人为设计的层，其层由研究者选定，而非自然沉积。"},{"no":"08","title":"Archaeological layering","titleCN":"考古地层堆积","definition":"the sequence of occupation layers at a site, in which the lowest deposits are normally the oldest","definitionCN":"遗址中居住层的叠压序列，通常最下的堆积最早","example":"Stratification at the site was undisturbed, so the pottery sequence could be read plainly.","exampleCN":"遗址的地层未被扰动，陶器序列因此可以清楚读出。","why":"archaeology depends on the geological rule that layers stack in order, which makes depth a clock.","whyCN":"考古学依赖地质学那条规则：层按顺序叠压，于是深度成了钟表。"}],"etymology":{"intro":{"en":"Stratification joins Latin stratum 'a layer, something spread out' to -fication, from facere 'to make'. It was formed in modern scientific Latin and passed into English in the eighteenth century. Dates are approximate.","cn":"stratification 由拉丁 stratum「层、铺开之物」加 -fication（源自 facere「做」）构成，形成于近代科学拉丁语，十八世纪进入英语。年代均为约数。"},"items":[{"era":"LATIN STERNERE","en":"Stratum is the neuter past participle of sternere 'to spread out, stretch, lay flat', so a stratum is literally something spread down.","cn":"stratum 是 sternere「铺开、伸展、平放」的中性过去分词，因此 stratum 字面上就是「被铺下的东西」。"},{"era":"LATIN STRATUM","en":"Roman writers used stratum for a bed, a couch or a paved surface; the geological sense of a rock bed is a later scientific narrowing.","cn":"罗马作家用 stratum 指床、卧榻或铺过的地面；指岩层的地质义是后来的科学收窄。"},{"era":"MODERN LATIN COINAGE","en":"Scientists of the eighteenth century joined stratum to -fication, modelled on other technical nouns in -ficatio, to name the making of layers.","cn":"十八世纪学者仿照其它以 -ficatio 结尾的技术名词，把 stratum 与 -fication 结合，命名「成层」这一过程。"},{"era":"GEOLOGY","en":"The noun became standard for sedimentary bedding, and stratigraphy grew up around the rule that layers are stacked in time order.","cn":"这个名词成为沉积层理的标准术语，地层学围绕「层按时间顺序叠压」这一规则发展起来。"},{"era":"SOCIOLOGY AND STATISTICS","en":"From the nineteenth century the word was applied to ranked social groups, and later to deliberately divided sampling groups.","cn":"从十九世纪起，这个词被用于有高低之别的社会群体，后来又用于有意划分的抽样组。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the Latin elements are secure, but the earliest English use of the scientific noun is dated only approximately.","cn":"来源不确定（仅首见年代）：拉丁成分是确定的，但这个科学名词在英语中的最早使用只能约略定年。"}]},"similar":{"note":{"en":"Group one sets stratification against look-alikes built on other roots; group two sets it against words for layers and ranking.","cn":"第一组把 stratification 与其它词根构成的形近词分开；第二组区分它与「层」「等级」的其它说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stratum","ipa":"/ˈstreɪtəm/","tag":"same family, singular","definition":"The single layer itself; stratification is the arrangement or the process that produces many strata.","definitionCN":"指单个层本身；stratification 指多层排列或其形成过程。"},{"word":"strata","ipa":"/ˈstreɪtə/","tag":"same family, plural","definition":"The Latin plural of stratum, used in English for several layers; it names the objects, not the process.","definitionCN":"stratum 的拉丁复数，英语中指若干层；它命名对象，不命名过程。"},{"word":"stratify","ipa":"/ˈstrætɪfaɪ/","tag":"same family, verb","definition":"The verb 'to make or become layered'; the noun is its action and result.","definitionCN":"动词「使成层、分层」；名词是其动作与结果。"},{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"different root","definition":"From Greek stratēgos 'general', built on stratos 'army' and agein 'to lead'; the strat- overlap is accidental.","definitionCN":"来自希腊 stratēgos「将军」，由 stratos「军队」与 agein「引导」构成；strat- 的重合只是偶然。"}]},{"heading":"NEAR MEANING","entries":[{"word":"layering","ipa":"/ˈleɪərɪŋ/","tag":"plain English","definition":"The everyday word for putting things in layers; stratification is its technical and geological counterpart.","definitionCN":"指把东西分成层的日常词；stratification 是其技术与地质上的对应词。"},{"word":"banding","ipa":"/ˈbændɪŋ/","tag":"visible stripes","definition":"The appearance of distinct stripes of colour or texture, which may result from stratification but need not.","definitionCN":"指颜色或质地呈明显条带的外观，可由分层造成，但不必然。"},{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"ranked order","definition":"A system of ranked levels, especially in organizations; it stresses order and authority rather than layers of material.","definitionCN":"指按等级排列的体系，尤用于组织；强调次序与权力，而非物质的层。"},{"word":"division","ipa":"/dɪˈvɪʒn/","tag":"general splitting","definition":"Any splitting into parts; it says nothing about whether the parts lie one above another.","definitionCN":"泛指分成若干部分，不说明这些部分是否上下叠压。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"stratum 'layer' + -fication 'making': the making of layers.","cn":"stratum「层」+ -fication「使形成」：使成层。"},{"en":"The same stratum stock gives stratum, strata, stratify, stratified, stratigraphy.","cn":"同一 stratum 词干衍生 stratum、strata、stratify、stratified、stratigraphy。"},{"en":"Geology reads layers; sociology reads ranks; statistics reads subgroups; horticulture reads cold sand.","cn":"地质读层，社会学读等级，统计学读子群，园艺读冷沙。"},{"en":"Fixed phrases: social stratification, thermal stratification, seed stratification.","cn":"固定搭配：社会分层、温度分层、种子层积处理。"},{"en":"Keep it apart from strategy, whose strat- comes from Greek stratos 'army'.","cn":"与 strategy 分开，后者的 strat- 来自希腊 stratos「军队」。"}],"abstract":[{"en":"Picture a cake cut cleanly so that every sponge line shows.","cn":"想象蛋糕被切开，每一道蛋糕坯的层次都露出来。"},{"en":"Picture a lake in summer with a warm lid that will not mix with the cold below.","cn":"想象夏日的湖，上面一层温水盖着，不肯与下面的冷水混合。"},{"en":"Picture a library where every shelf is a social class and the ladder is missing.","cn":"想象一座图书馆，每层书架是一个社会阶层，而梯子不见了。"}]},"examples":[{"en":"The stratification of the delta records centuries of floods.","cn":"三角洲的层理记录了数百年的洪水。"},{"en":"Educational stratification widened even as enrolments rose.","cn":"入学人数上升的同时，教育分层反而加剧。"},{"en":"Without stratification, the lake bottom would lose its oxygen each summer.","cn":"若没有温度分层，湖底每年夏天都会缺氧。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「strata（层）+ fication（做成）」——把东西做成一层层 → 分层","word":"stratification"},"root":"拉丁 stratum「层、铺开之物」（sternere 的过去分词）+ -fication（facere「做」），近代科学拉丁语构词。","sensesIntro":{"en":"Eight senses all turn on stacked layers: first rock, then society, then the act, then water, seed, forest and data, until depth itself becomes a clock.","cn":"八个义项都围绕「层层叠压」：先是岩石，再是社会，再是动作本身，然后是水、种子、森林与数据，最后深度本身成了钟表。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cut bank showing band after band, each band a year.","cn":"核心意象：被切开的土坡露出一条条色带，每一带是一年。"},"chain":["SPREAD DOWN","STACK IN BEDS","NAME THE ORDER","RANK PEOPLE","SEPARATE BY DENSITY","SORT FOR STUDY"],"branches":[{"senses":"S1 · S3","en":"ROCK AND ITS MAKING: the same noun covers the beds and the process that lays them.","cn":"岩石与其形成：同一名词兼指层与被层铺出的过程。"},{"senses":"S2","en":"SOCIAL LAYERS: geology supplies the image of ranks that are hard to climb.","cn":"社会层：地质提供了难以攀爬的等级意象。"},{"senses":"S4","en":"WATER LAYERS: density builds real sheets that refuse to mix.","cn":"水层：密度造出真的、拒绝混合的水片。"},{"senses":"S5 · S6","en":"SEED AND FOREST: cold sand and canopy light both create usable layers.","cn":"种子与森林：冷沙与冠层的光都在造可用之层。"},{"senses":"S7 · S8","en":"DESIGNED STRATA: sampling groups and occupation layers both read the past from below.","cn":"有意划分的层：抽样组与居住层都从下面读取过去。"}]},"affixes":{"intro":{"en":"Stratification is a modern Latin compound whose two parts still work separately in English, so the whole word can be read as layer plus making.","cn":"stratification 是近代拉丁复合词，两个部分在英语中仍独立运作，因此整词可读作「层」加「做成」。"},"latinIntro":{"en":"Latin stratum 'layer' and the suffix -fication from facere 'to make' supply the meaning; stratum itself comes from sternere 'to spread out'.","cn":"拉丁 stratum「层」与源自 facere「做」的后缀 -fication 提供词义；stratum 本身来自 sternere「铺开」。"},"items":[{"word":"stratum","structure":"stratum (Latin neuter noun 'layer, spread surface')","meaning":"layer; bed","meaningCN":"层；铺开的面","example":"Each stratum lies flat on the one below.","exampleCN":"每一层平压在下一层之上。"},{"word":"-fication","structure":"-ficatio (Latin suffix 'a making')","meaning":"the act of making","meaningCN":"使……形成的过程","example":"The suffix turns a state into a process.","exampleCN":"这个后缀把状态变成过程。"},{"word":"stratification","structure":"stratum + -fication","meaning":"the making of layers","meaningCN":"使成层；分层","example":"Stratification built the delta outward.","exampleCN":"分层使三角洲向外生长。"},{"word":"stratify","structure":"stratum + -fy (to make)","meaning":"to arrange in layers","meaningCN":"使分层","example":"Winds stratify the ash by grain size.","exampleCN":"风按粒径把火山灰分层。"},{"word":"stratified","structure":"stratify + -ed (past participle)","meaning":"arranged in layers","meaningCN":"已分层的","example":"A stratified sample follows the districts.","exampleCN":"分层样本依地区划分。"},{"word":"stratigraphy","structure":"stratum + -graphy (description)","meaning":"the study of layered sequences","meaningCN":"地层学","example":"Stratigraphy dates the beds by their order.","exampleCN":"地层学按层序定年。"},{"word":"substratum","structure":"sub- (under) + stratum","meaning":"a layer beneath another","meaningCN":"下层；底层","example":"A gravel substratum holds the water.","exampleCN":"砾石底层蓄着水。"},{"word":"destratification","structure":"de- (reversal) + stratification","meaning":"the undoing of layers","meaningCN":"去分层","example":"Autumn winds bring destratification.","exampleCN":"秋风带来湖水的去分层。"},{"word":"stratocumulus","structure":"stratum + cumulus (Latin 'heap')","meaning":"a low layered cloud","meaningCN":"层积云","example":"Stratocumulus covered the whole sky.","exampleCN":"层积云铺满天空。"}],"latinEntries":[{"word":"stratum","structure":"stratum, strati (n., second declension)","meaning":"a layer, bed, paved surface","meaningCN":"层；床；铺面"},{"word":"stratus","structure":"stratus, strati (m., second declension)","meaning":"spread out, covered","meaningCN":"铺开的；覆盖的"},{"word":"sternere","structure":"sternere, stravi, stratum (verb, third conjugation)","meaning":"to spread out, lay flat","meaningCN":"铺开；平放"},{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to make, do","meaningCN":"做；造"}]}},{"word":"stratum","ipa_uk":"/ˈstreɪtəm/","ipa_us":"/ˈstreɪtəm/","definition_zh":"地层；岩层；社会阶层；层（解剖、考古、统计等单位）","definition_en":"a single layer of rock or other material, or one level within a society or system","core_image":"崖壁上一条灰白色薄层夹在两层红砂岩之间，断面里露出贝壳","scene":"崖壁上一条灰白色薄岩层夹在两层红砂岩之间，学生用小锤敲下一块，断面里露出贝壳。 A thin white stratum runs between the two red beds and holds the oldest shells.","sceneCN":"这里 stratum 指「一层可辨认的岩层」（第 1 个义项：地质上单层的地层）；句意为一条薄薄的白色岩层夹在两层红色岩层之间，其中保存着最古老的贝壳。图中可辨识物件：灰白薄层、红砂岩、小锤、贝壳断面。","pos":[{"tag":"n.","zh":"层；地层；岩层；社会阶层；解剖层；统计分层中的一层"}],"collocations":[{"phrase":"rock stratum","zh":"岩层"},{"phrase":"a stratum of society","zh":"社会的一个阶层"},{"phrase":"upper stratum","zh":"上层"},{"phrase":"lower stratum","zh":"下层"},{"phrase":"stratum corneum","zh":"角质层"},{"phrase":"cultural stratum","zh":"文化层"}],"forms":[{"label":"名词单数","form":"stratum"},{"label":"名词复数（拉丁复数）","form":"strata"},{"label":"派生形容词","form":"stratal"},{"label":"相关动词","form":"stratify"},{"label":"过去分词（形容词）","form":"stratified"}],"derivatives":[{"word":"strata","pos":"n.","zh":"层（复数）；地层群；社会各阶层"},{"word":"stratal","pos":"adj.","zh":"层的；成层的"},{"word":"stratify","pos":"v.","zh":"使分层；层积"},{"word":"stratification","pos":"n.","zh":"分层；层理"},{"word":"substratum","pos":"n.","zh":"下层；底层；基质"}],"senses":[{"no":"01","title":"A single rock layer","titleCN":"单层岩层","definition":"one recognizable bed of rock, distinct in colour or texture from the beds above and below it","definitionCN":"颜色或质地可与上下层区分的一层可辨认岩层","example":"The limestone stratum is barely a metre thick here.","exampleCN":"这里的石灰岩层还不到一米厚。","why":"the Latin word means something spread out, so a stratum is one sheet laid over another rather than a mass.","whyCN":"拉丁词义是「铺开之物」，因此 stratum 是铺在另一层上的一层薄片，而非一大块体。"},{"no":"02","title":"A social class layer","titleCN":"社会的一个阶层","definition":"one of the ranked groups into which a society is divided by wealth, occupation or status","definitionCN":"社会按财富、职业或地位划分出的有高低之别的群体之一","example":"Families from every stratum of the town came to the funeral.","exampleCN":"镇上各个阶层的家庭都来参加葬礼。","why":"sociology keeps the geological metaphor singular: one stratum among many, each resting on the one below.","whyCN":"社会学保留地质比喻的单数形式：众多层中的一层，各自压在下一层之上。"},{"no":"03","title":"Any thin sheet of material","titleCN":"任何薄薄的一层材料","definition":"a thin continuous sheet of one substance lying over another, as of paint, dust or tissue","definitionCN":"一种物质覆盖在另一种之上的连续薄层，如漆、尘或组织","example":"A stratum of ash from the eruption still lies over the fields.","exampleCN":"火山喷发留下的火山灰层仍覆盖着田野。","why":"the word is general enough to leave geology: any flat sheet counts, provided it lies on something else.","whyCN":"这个词足够一般，可以离开地质：只要铺在别物之上，任何平层都算。"},{"no":"04","title":"An anatomical layer","titleCN":"解剖学上的一层","definition":"one of the distinct layers of a tissue or organ, such as the outer horny layer of skin","definitionCN":"组织或器官中可区分的一层，如皮肤最外的角质层","example":"The outermost stratum of the skin consists of dead flattened cells.","exampleCN":"皮肤最外层由扁平的死细胞构成。","why":"anatomy borrowed the noun because skin and gut really are built of sheets that peel apart.","whyCN":"解剖学借这个名词，因为皮肤与肠壁确实由可分离的片层构成。"},{"no":"05","title":"An occupation layer on a site","titleCN":"遗址中的居住层","definition":"a distinct band of debris and structures left by one period of human use at an archaeological site","definitionCN":"考古遗址中某一时期人类活动留下的、含遗物与结构的独立堆积带","example":"The earliest stratum yielded only flint flakes and no pottery.","exampleCN":"最早的居住层只出燧石片，没有陶器。","why":"archaeology treats each stratum as a sealed episode, so mixing between strata destroys the chronology.","whyCN":"考古学把每一层视为封闭的一段，因此层间混扰会毁掉年代序列。"},{"no":"06","title":"A layer of the atmosphere or sea","titleCN":"大气或海洋中的一层","definition":"a horizontal band of air or water distinguished by temperature, salt content or composition","definitionCN":"按温度、盐度或成分区分出的空气或水的水平带","example":"Ozone forms in a high stratum of the atmosphere and drifts downward.","exampleCN":"臭氧在对流层之上的高空中形成，并向下飘移。","why":"meteorology uses stratum for bands that behave as units, just as sedimentary beds do.","whyCN":"气象学用 stratum 指作为整体运动的气带，正如沉积层那样。"},{"no":"07","title":"One level of a system","titleCN":"体系中的一个层级","definition":"one level of an organized system, such as a language, a legal code or an administrative structure","definitionCN":"有组织体系中的一层，如语言、法典或行政结构中的层级","example":"Archaic spellings survived in the lowest stratum of the written language.","exampleCN":"古旧拼写残留在书面语言的最底层。","why":"the abstract use generalizes the image: levels rest on levels, and the deepest ones are the oldest and least visible.","whyCN":"抽象义把意象一般化：层层叠压，最深者最古老、最不易见。"},{"no":"08","title":"A sampling subgroup","titleCN":"分层抽样中的一层","definition":"one of the subgroups into which a population is divided before a sample is drawn","definitionCN":"抽样之前把总体划分成的子群之一","example":"Each stratum was sampled separately so that small districts were not lost.","exampleCN":"每一层都单独抽样，以免小区被淹没。","why":"statistics makes the layer a deliberate construction, chosen so that variation inside it stays small.","whyCN":"统计学把层变成有意的构造，选择的依据是层内差异要小。"}],"etymology":{"intro":{"en":"Stratum is Latin for 'something spread out', the neuter past participle of sternere 'to spread, lay flat'. English adopted it in the sixteenth century, first for beds of rock. Dates are approximate.","cn":"stratum 是拉丁语「铺开之物」，为 sternere「铺开、平放」的中性过去分词。英语于十六世纪引入，最初指岩层。年代均为约数。"},"items":[{"era":"LATIN STERNERE","en":"Sternere meant 'to spread out, stretch, lay flat'; its participle stratus gave Latin stratum, a thing spread down.","cn":"一般认为 sternere 意为「铺开、伸展、平放」；其分词 stratus 产生拉丁 stratum，即被铺下之物。"},{"era":"ROMAN USES","en":"In Latin, stratum covered a bed, a couch, a paved floor and a horse's saddle cloth, all surfaces laid over something.","cn":"在拉丁语中，stratum 指床、卧榻、铺过的地面与马鞍垫，都是铺在别物之上的面。"},{"era":"ENGLISH ENTRY","en":"English naturalists of the sixteenth century took stratum for a bed of rock, and the plural strata followed with it.","cn":"十六世纪的英国博物学者用 stratum 指岩层，复数 strata 也随之进入英语。"},{"era":"SOCIAL SENSE","en":"Nineteenth-century social writers extended the noun to ranked classes, borrowing the image of layers stacked in order.","cn":"十九世纪的社会写作者把这个名词扩展到有等级的阶级，借用了层层叠压的意象。"},{"era":"PLURAL CAUTION","en":"Strata is the Latin plural and is often mistaken for a singular; the true singular remains stratum.","cn":"strata 是拉丁复数，常被误当单数；真正的单数仍是 stratum。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the Latin etymon is secure, but the earliest English geological citation is dated only approximately.","cn":"来源不确定（仅首见年代）：拉丁词源是确定的，但英语中最早的地质学书证只能约略定年。"}]},"similar":{"note":{"en":"Group one marks the plural and derivative forms that are constantly mixed up with the singular; group two marks words for layers and levels that are not this noun.","cn":"第一组标出常与单数混淆的复数与派生形式；第二组标出并非本词却表「层」「级」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"strata","ipa":"/ˈstreɪtə/","tag":"same family, plural","definition":"The Latin plural: several layers at once. Writing 'a strata' is a common error, since the singular is stratum.","definitionCN":"拉丁复数：一次指数层。写成 a strata 是常见错误，单数应为 stratum。"},{"word":"stratification","ipa":"/ˌstrætɪfɪˈkeɪʃn/","tag":"same family, process","definition":"The arranging or forming of layers; it names the process, while stratum names one result.","definitionCN":"分层的过程；它命名过程，stratum 命名其中一个结果。"},{"word":"stratify","ipa":"/ˈstrætɪfaɪ/","tag":"same family, verb","definition":"To make or become layered; the noun does not itself carry an action.","definitionCN":"使成层或成层；名词本身不含动作。"},{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"different root","definition":"Greek stratēgos 'general' from stratos 'army'; it looks similar but has no connection with layers.","definitionCN":"希腊 stratēgos「将军」，源自 stratos「军队」；形似但与层无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"layer","ipa":"/ˈleɪə/","tag":"everyday word","definition":"The plain term for one sheet over another, used of paint, dust, cake and rock alike.","definitionCN":"指一层压一层的日常词，漆、尘、蛋糕与岩石都用它。"},{"word":"bed","ipa":"/bed/","tag":"geology, thicker","definition":"A geological layer thick enough to be mapped as a unit; a stratum may be thinner and less formal.","definitionCN":"厚到可作为填图单位的地质层；stratum 可以更薄、更不正式。"},{"word":"level","ipa":"/ˈlevl/","tag":"rank, not material","definition":"A position in a scale or hierarchy, with no suggestion of physical sheeting.","definitionCN":"指尺度或等级中的位置，不含实体薄片之意。"},{"word":"seam","ipa":"/siːm/","tag":"a workable band","definition":"A thin band of coal or ore that can be mined; it implies economic use, which stratum does not.","definitionCN":"可开采的薄煤层或矿带；含经济利用之意，stratum 则不含。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin stratum is a thing spread out; the plural strata is often mistaken for a singular.","cn":"拉丁 stratum 是铺开之物；复数 strata 常被误当单数。"},{"en":"The family runs stratum, strata, stratal, stratify, stratification, substratum.","cn":"同族词包括 stratum、strata、stratal、stratify、stratification、substratum。"},{"en":"Geology says a bed, sociology says a class, anatomy says a sheet of skin.","cn":"地质说岩层，社会学说阶层，解剖学说一层皮。"},{"en":"Fixed phrases: rock stratum, upper stratum, stratum corneum.","cn":"固定搭配：岩层、上层、角质层。"},{"en":"Remember that -um is singular and -a is plural, as in datum and data.","cn":"记住 -um 为单数、-a 为复数，如同 datum 与 data。"}],"abstract":[{"en":"Picture one white ribbon pressed between two red ones.","cn":"想象一条白带被压在两条红带之间。"},{"en":"Picture a building where each floor is a class and the stairs are guarded.","cn":"想象一栋楼，每层是一个阶层，楼梯有人把守。"},{"en":"Picture a page of sediment laid down in a single season and sealed by the next.","cn":"想象一页沉积在一个季节铺成，又被下一个季节封住。"}]},"examples":[{"en":"A thin stratum of clay separates the two aquifers.","cn":"一层薄黏土隔开了两个含水层。"},{"en":"The reform mainly benefited the wealthiest stratum of the city.","cn":"这项改革主要惠及城市中最富的阶层。"},{"en":"The stratum was sealed by lava and therefore undisturbed.","cn":"该层被熔岩封住，因而未被扰动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「strat（铺开）+ um（东西）」——铺开的一层东西 → 地层、阶层","word":"stratum"},"root":"拉丁 stratum「铺开之物」，为 sternere「铺开、平放」的中性过去分词；复数 strata。","sensesIntro":{"en":"Eight senses all describe one sheet lying on another: rock first, then class, tissue, occupation debris, air, system level and sampling group.","cn":"八个义项都描述「铺在另一层上的一层」：先是岩石，再是阶层、组织、居住堆积、空气、体系层级与抽样组。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single sheet pressed into place between two others.","cn":"核心意象：一层薄片被压在另外两层之间。"},"chain":["SPREAD OUT","ONE SHEET","ROCK BED","SOCIAL RANK","BODY LAYER","SYSTEM LEVEL"],"branches":[{"senses":"S1 · S3","en":"PHYSICAL SHEET: rock or ash, the point is that it is one continuous spread.","cn":"实体薄层：岩石或火山灰，要点是它为一整片铺开之物。"},{"senses":"S2 · S7","en":"RANK AND LEVEL: layers of people and layers of systems obey the same up-down image.","cn":"等级与层级：人的层与体系的层同守一个上下意象。"},{"senses":"S4","en":"BODY LAYER: skin and gut really do peel in sheets.","cn":"身体层：皮肤与肠壁确实成片可剥。"},{"senses":"S5 · S6","en":"SEALED BANDS: occupation debris and atmospheric belts both behave as units.","cn":"封闭的带：居住堆积与大气带都作为整体运作。"},{"senses":"S8","en":"CHOSEN LAYER: statistics builds its strata on purpose.","cn":"选定的层：统计学的层是刻意划分的。"}]},"affixes":{"intro":{"en":"Stratum is a bare Latin noun in English, but the same root builds a whole family through English and Latin affixes.","cn":"stratum 在英语中就是拉丁名词原形，但同一词根通过英语与拉丁词缀构成了整个词族。"},"latinIntro":{"en":"Latin sternere 'to spread out' gives stratum and stratus; English adds -al, -ify, -ification and sub- to extend the family.","cn":"拉丁 sternere「铺开」产生 stratum 与 stratus；英语用 -al、-ify、-ification 与 sub- 扩展词族。"},"items":[{"word":"stratum","structure":"stratum (Latin neuter noun 'layer')","meaning":"a layer","meaningCN":"层；地层","example":"One stratum pinches out to the east.","exampleCN":"有一层向东尖灭。"},{"word":"strata","structure":"stratum + -a (Latin neuter plural)","meaning":"layers","meaningCN":"多层；各层","example":"The strata dip gently north.","exampleCN":"各层缓缓向北倾斜。"},{"word":"stratal","structure":"stratum + -al (relating to)","meaning":"of a layer","meaningCN":"层的；成层的","example":"Stratal thickness varies across the basin.","exampleCN":"盆地内各层厚度不一。"},{"word":"stratify","structure":"stratum + -ify (make)","meaning":"to make layered","meaningCN":"使分层","example":"Gravity stratifies the cooling melt.","exampleCN":"重力使冷却的熔体分层。"},{"word":"stratification","structure":"stratify + -ication (process)","meaning":"the forming of layers","meaningCN":"分层；层理","example":"Stratification records each flood.","exampleCN":"分层记录每一场洪水。"},{"word":"substratum","structure":"sub- (under) + stratum","meaning":"the layer beneath","meaningCN":"下层；基质","example":"Roots reach the gravel substratum.","exampleCN":"根系伸到砾石下层。"},{"word":"superstratum","structure":"super- (above) + stratum","meaning":"the layer above","meaningCN":"上层","example":"A superstratum of loess buries the old soil.","exampleCN":"一层黄土埋住了老土壤。"},{"word":"stratigraphy","structure":"stratum + -graphy (writing)","meaning":"description of layers","meaningCN":"地层学","example":"Stratigraphy fixes the order of events.","exampleCN":"地层学确定事件顺序。"},{"word":"stratocumulus","structure":"stratum + cumulus (heap)","meaning":"layered heap cloud","meaningCN":"层积云","example":"Stratocumulus dulled the afternoon.","exampleCN":"层积云使午后阴沉。"}],"latinEntries":[{"word":"stratum","structure":"stratum, strati (n., second declension)","meaning":"a layer, bed, couch","meaningCN":"层；床；卧榻"},{"word":"stratus","structure":"stratus, strati (m., second declension)","meaning":"spread out, flat","meaningCN":"铺开的；平的"},{"word":"sternere","structure":"sternere, stravi, stratum (verb, third conjugation)","meaning":"to spread, lay flat","meaningCN":"铺开；平放"},{"word":"stratura","structure":"stratura, straturae (f., first declension)","meaning":"a spreading, paving","meaningCN":"铺砌；铺层"}]}},{"word":"strata","ipa_uk":"/ˈstreɪtə/","ipa_us":"/ˈstreɪtə/","definition_zh":"地层（stratum 的复数）；社会各阶层；层层叠置的结构","definition_en":"the plural of stratum: layers of rock, ranked social groups, or any set of stacked levels","core_image":"被道路切开的坡面上，五颜六色的沉积层斜斜地压在一起","scene":"道路切开的坡面上，五颜六色的沉积层像被斜着切开的蛋糕，学生沿坡面测倾角。 The road cut exposes tilted strata that dip toward the valley.","sceneCN":"这里 strata 指「若干层倾斜的岩层」（第 1 个义项：stratum 的复数，指多层地层）；句意为道路切开的剖面露出向谷地方向倾斜的岩层。图中可辨识物件：切开的坡面、彩色层带、倾角仪、记录板。","pos":[{"tag":"n.","zh":"stratum 的复数：地层群；社会各阶层；多层结构"}],"collocations":[{"phrase":"rock strata","zh":"岩层群"},{"phrase":"social strata","zh":"社会各阶层"},{"phrase":"tilted strata","zh":"倾斜的地层"},{"phrase":"upper strata","zh":"上层；上部地层"},{"phrase":"strata of society","zh":"社会的各层"},{"phrase":"sampling strata","zh":"抽样层组"}],"forms":[{"label":"单数（拉丁原形）","form":"stratum"},{"label":"复数（拉丁复数）","form":"strata"},{"label":"误用复数（罕见于口语）","form":"stratas"},{"label":"派生形容词","form":"stratal"},{"label":"相关动词","form":"stratify"},{"label":"相关名词","form":"stratification"}],"derivatives":[{"word":"stratal","pos":"adj.","zh":"层的；成层的"},{"word":"stratify","pos":"v.","zh":"使分层；层积"},{"word":"stratification","pos":"n.","zh":"分层；层理"},{"word":"substrata","pos":"n.","zh":"下层；各底层"},{"word":"stratigraphy","pos":"n.","zh":"地层学"}],"senses":[{"no":"01","title":"Several rock layers","titleCN":"若干岩层、地层群","definition":"more than one bed of rock, considered together as a stacked sequence","definitionCN":"把不止一层岩石作为一个叠压序列来看","example":"The tilted strata on the coast record a basin that once sank steadily.","exampleCN":"海岸上倾斜的岩层记录了一个曾持续下沉的盆地。","why":"the Latin plural keeps its -a ending, so the word names a set of layers rather than one sheet.","whyCN":"拉丁复数保留了 -a 词尾，因此这个词指一组层，而不是一张薄片。"},{"no":"02","title":"Social classes taken together","titleCN":"社会各阶层（总称）","definition":"the ranked groups of a society, spoken of collectively rather than one at a time","definitionCN":"一个社会中按等级划分的群体，作为整体而非逐个来谈","example":"Opportunity is still unevenly spread across the social strata.","exampleCN":"机会在社会各阶层之间仍然分布不均。","why":"the plural suits the sociological use because inequality is described as a system of layers, not a single rank.","whyCN":"复数适合社会学用法，因为不平等被描述为一整套层，而不是一个等级。"},{"no":"03","title":"Several stacked sheets of material","titleCN":"多层物质叠置","definition":"two or more thin sheets of a material lying one over another, as of paint, dust or tissue","definitionCN":"两种或更多薄层物质彼此叠压，如漆、尘或组织","example":"The strata of paint on the door show four different decades of repainting.","exampleCN":"门上层层相叠的漆显示出四个不同年代的重新涂刷。","why":"any physical stack of sheets qualifies, so the plural freely leaves geology for restoration and craft.","whyCN":"任何实体薄层叠压都算，因此这个复数可以自由离开地质，用于修复与手艺。"},{"no":"04","title":"A sequence of occupation layers","titleCN":"考古遗址中连续的居住层","definition":"the ordered set of layers left by successive periods of human use at a site","definitionCN":"遗址中由连续若干时期人类活动留下的有序层组","example":"The strata at the cave mouth run from flint tools up to glazed pottery.","exampleCN":"洞口的地层从燧石工具一直排到釉陶。","why":"archaeology needs the plural because the argument rests on the order between layers, not on any one layer.","whyCN":"考古学需要复数，因为论证依赖层与层之间的顺序，而非某一层本身。"},{"no":"05","title":"Bands of air or water","titleCN":"大气或水体中的层带","definition":"several horizontal bands of air or water that differ in temperature, salt or composition","definitionCN":"若干因温度、盐度或成分不同而分出的空气或水带","example":"Warm and cold strata met at the strait and refused to mix.","exampleCN":"暖层与冷层在海峡相遇，彼此不肯混合。","why":"the plural marks the fact that adjacent bands can behave as separate bodies for weeks.","whyCN":"复数标出这样一个事实：相邻层带可以数周各自作为独立水体运动。"},{"no":"06","title":"Sampling groups","titleCN":"抽样中的各层组","definition":"the subgroups of a population that a statistician samples separately","definitionCN":"统计者分别抽样的总体子群","example":"The survey compared strata by age and by district.","exampleCN":"这项调查按年龄与地区比较各层组。","why":"statistics uses the plural for a designed set, where each group is sampled on its own terms.","whyCN":"统计学用复数指有意设计的一组层，每组按自己的规则抽样。"},{"no":"07","title":"Layers of vegetation","titleCN":"植被的各个层","definition":"the vertical layers of a plant community, from canopy to ground cover","definitionCN":"植物群落从冠层到地被的垂直各层","example":"Light reaching the lower strata decides which herbs survive.","exampleCN":"到达下层的阳光决定哪些草本能够存活。","why":"ecology speaks of strata in the plural because each layer filters light for the one beneath it.","whyCN":"生态学用复数谈论各层，因为每层都为下层滤去一部分光。"},{"no":"08","title":"Stacked levels of meaning","titleCN":"抽象义：层层叠加的意涵或体系","definition":"several levels of meaning or structure that rest on one another within one thing","definitionCN":"同一事物内部彼此叠压的若干意义层或结构层","example":"A myth can carry strata of meaning that no single reading exhausts.","exampleCN":"一个神话可以承载层层意涵，任何单一解读都无法穷尽。","why":"the metaphor turns the plural into a tool for analysis: to read a text is to separate its layers.","whyCN":"这个比喻把复数变成分析工具：读一个文本就是分离它的各层。"}],"etymology":{"intro":{"en":"Strata is the Latin plural of stratum 'something spread out'. English borrowed both forms, and the plural has often been mistaken for a singular. Dates are approximate.","cn":"strata 是拉丁 stratum「铺开之物」的复数。英语把单复数两个形式一并借入，而复数常被误当单数。年代均为约数。"},"items":[{"era":"LATIN STRATUM","en":"Stratum is the neuter past participle of sternere 'to spread out, lay flat', so a stratum is a thing spread down.","cn":"stratum 是 sternere「铺开、平放」的中性过去分词，因此指被铺下之物。"},{"era":"NEUTER PLURAL -A","en":"Latin neuter nouns of the second declension take -a in the plural, which is why the plural is strata and not stratums.","cn":"拉丁第二变格法的中性名词复数取 -a，因此复数是 strata 而非 stratums。"},{"era":"ENGLISH BORROWING","en":"Sixteenth-century naturalists took both stratum and strata from Latin, using the plural for a sequence of beds.","cn":"十六世纪的博物学者把 stratum 与 strata 一并从拉丁借入，用复数指一系列岩层。"},{"era":"MISTAKEN SINGULAR","en":"Because strata ends in -a, English speakers often treat it as a singular and then back-form the plural stratas.","cn":"由于 strata 以 -a 结尾，英语使用者常把它当单数，并反推出复数 stratas。"},{"era":"SOCIOLOGICAL PLURAL","en":"Nineteenth-century social writing used the plural for classes as a system, and the usage has remained plural.","cn":"十九世纪的社会写作把这个复数用于作为体系的各个阶级，这一用法一直保持复数。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (only the first dating is in doubt): the Latin forms are certain, but the earliest English citation for the geological plural is approximate.","cn":"来源不确定（仅首见年代）：拉丁形式确定，但地质复数在英语中的最早书证只能约略定年。"}]},"similar":{"note":{"en":"Group one separates the plural from its singular and from the forms built on it; group two separates it from other words for layers and ranks.","cn":"第一组把复数形式与单数及其派生形式分开；第二组区分它与其它表「层」「等级」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stratum","ipa":"/ˈstreɪtəm/","tag":"same family, singular","definition":"One layer. Writing 'a strata' is a common error; the singular has no -a.","definitionCN":"一层。写成 a strata 是常见错误，单数不带 -a。"},{"word":"stratas","ipa":"/ˈstreɪtəz/","tag":"back-formed plural","definition":"An English plural built on the mistaken belief that strata is singular; careful writing avoids it.","definitionCN":"因误以为 strata 是单数而反推出来的英语复数；严谨写作应避免。"},{"word":"stratal","ipa":"/ˈstreɪtəl/","tag":"same family, adjective","definition":"Built on stratum plus -al: relating to layers, as in stratal thickness.","definitionCN":"由 stratum 加 -al 构成：与层有关，如层的厚度。"},{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"different root","definition":"From Greek stratos 'army' plus agein 'to lead'; the shared letters hide a completely different origin.","definitionCN":"来自希腊 stratos「军队」加 agein「引导」；相同的字母掩盖了完全不同的来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"layers","ipa":"/ˈleɪəz/","tag":"everyday plural","definition":"The plain English plural for stacked sheets; it carries no technical or Latin flavour.","definitionCN":"指叠压薄层的普通英语复数，不带技术或拉丁色彩。"},{"word":"beds","ipa":"/bedz/","tag":"geology, mappable","definition":"Geological layers thick enough to be shown on a map or section, often coarser than strata.","definitionCN":"厚到能画在图上或剖面上的地质层，通常比 strata 更粗放。"},{"word":"classes","ipa":"/ˈklɑːsɪz/","tag":"social, not physical","definition":"Ranked social groups; unlike strata, the word carries no image of physical stacking.","definitionCN":"有等级的社会群体；与 strata 不同，它不含实体叠压的意象。"},{"word":"levels","ipa":"/ˈlevlz/","tag":"abstract ranks","definition":"Positions on a scale; they need not lie physically above or below one another.","definitionCN":"尺度上的位置；不必在实体上分上下。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin neuter plurals end in -a, so stratum becomes strata, as datum becomes data.","cn":"拉丁中性复数以 -a 结尾，故 stratum 变 strata，如 datum 变 data。"},{"en":"The family runs stratum, strata, stratal, stratify, stratification, substrata.","cn":"同族词包括 stratum、strata、stratal、stratify、stratification、substrata。"},{"en":"Geology reads a sequence, sociology reads a system of classes, statistics reads designed groups.","cn":"地质读序列，社会学读阶级体系，统计学读设计好的组。"},{"en":"Fixed phrases: rock strata, social strata, tilted strata.","cn":"固定搭配：岩层群、社会各阶层、倾斜地层。"},{"en":"Never write 'a strata'; if you need a singular, use stratum.","cn":"不要写 a strata；需要单数就用 stratum。"}],"abstract":[{"en":"Picture a stack of coloured papers sliced at an angle so every edge shows.","cn":"想象一叠彩纸被斜切，每条边都露出来。"},{"en":"Picture a theatre where the cheap seats are also the lowest and the darkest.","cn":"想象一座剧场，便宜座位既最低也最暗。"},{"en":"Picture a sentence that can be read as a joke, a confession and a threat at once.","cn":"想象一句话同时可读作玩笑、自白与威胁。"}]},"examples":[{"en":"The lower strata contain no fossils at all.","cn":"下部各层完全不含化石。"},{"en":"Reform opened schooling to strata that had been excluded.","cn":"改革把教育向此前被排除的各个阶层开放。"},{"en":"The paint strata show that the door was stripped twice.","cn":"层层漆面说明这扇门被剥过两次漆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「strata」＝ stratum 的复数——记住 -a 是复数尾巴，别当成单数","word":"strata"},"root":"拉丁 stratum「铺开之物」的中性复数，-a 为第二变格法中性复数词尾；与 sternere「铺开」同源。","sensesIntro":{"en":"Eight senses all use the plural deliberately: one layer would not make a sequence, a class system, a stack of paint, a set of samples or a set of readings.","cn":"八个义项都刻意使用复数：单独一层构不成序列、阶级体系、层层漆面、一组样本或一叠解读。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cut slope showing many tilted layers at once.","cn":"核心意象：切开的坡面一次露出许多倾斜的层。"},"chain":["MANY LAYERS","STACKED ORDER","READ AS A SET","RANK PEOPLE","FILTER LIGHT","DESIGNED GROUPS"],"branches":[{"senses":"S1 · S3","en":"PHYSICAL STACK: rock and paint alike are read as sequences, not single sheets.","cn":"实体叠层：岩石与漆面都被读作序列，而非单张薄片。"},{"senses":"S2","en":"SOCIAL SET: inequality is described as a system of layers.","cn":"社会层组：不平等被描述为一整套层。"},{"senses":"S4","en":"ARCHAEOLOGICAL ORDER: the argument rests on the relation between layers.","cn":"考古次序：论证依赖层与层之间的关系。"},{"senses":"S5 · S7","en":"BANDS THAT ACT ALONE: water belts and canopy layers each work as a unit.","cn":"各自运作的带：水带与冠层都各自作为整体起作用。"},{"senses":"S6 · S8","en":"CONSTRUCTED SETS: sampling groups and levels of meaning are both built for analysis.","cn":"构造的集合：抽样组与意义层都为分析而建。"}]},"affixes":{"intro":{"en":"Strata is an inflected Latin form rather than a derived English word, so its only affix is the Latin plural ending.","cn":"strata 是拉丁语屈折形式，而非英语派生词，因此它唯一的词缀是拉丁复数词尾。"},"latinIntro":{"en":"Latin stratum comes from sternere 'to spread out'; the plural ending -a is the regular neuter marker of the second declension.","cn":"拉丁 stratum 来自 sternere「铺开」；复数词尾 -a 是第二变格法中性名词的常规标记。"},"items":[{"word":"stratum","structure":"stratum (Latin neuter noun 'layer')","meaning":"layer","meaningCN":"层","example":"Each stratum is sealed by the next.","exampleCN":"每层都被下一层封住。"},{"word":"-a","structure":"-a (Latin neuter plural ending)","meaning":"more than one","meaningCN":"复数标记","example":"The ending marks the plural, not a new word.","exampleCN":"这个词尾标出复数，并不构成新词。"},{"word":"strata","structure":"stratum + -a","meaning":"layers","meaningCN":"多层；各层","example":"The strata dip to the north.","exampleCN":"各层向北倾斜。"},{"word":"stratal","structure":"stratum + -al (relating to)","meaning":"of layers","meaningCN":"层的","example":"Stratal boundaries are sharp here.","exampleCN":"这里的层界很清晰。"},{"word":"stratify","structure":"stratum + -ify (make)","meaning":"to make layered","meaningCN":"使分层","example":"The current stratifies the sand.","exampleCN":"水流使沙子分层。"},{"word":"stratification","structure":"stratify + -ication (process)","meaning":"the forming of layers","meaningCN":"分层","example":"Stratification took millennia.","exampleCN":"分层历经数千年。"},{"word":"substrata","structure":"sub- (under) + strata","meaning":"the layers below","meaningCN":"下层；各底层","example":"Roots reach the substrata.","exampleCN":"根系伸入下层。"},{"word":"stratigraphy","structure":"stratum + -graphy (description)","meaning":"study of layered order","meaningCN":"地层学","example":"Stratigraphy orders the beds.","exampleCN":"地层学给各层排序。"},{"word":"stratocumulus","structure":"stratum + cumulus (heap)","meaning":"layered heap cloud","meaningCN":"层积云","example":"Stratocumulus hid the sun.","exampleCN":"层积云遮住了太阳。"}],"latinEntries":[{"word":"stratum","structure":"stratum, strati (n., second declension)","meaning":"a layer, bed","meaningCN":"层；床"},{"word":"strata","structure":"strata, stratorum (n. pl., second declension)","meaning":"layers","meaningCN":"多层"},{"word":"sternere","structure":"sternere, stravi, stratum (verb, third conjugation)","meaning":"to spread out, lay flat","meaningCN":"铺开；平放"},{"word":"stratura","structure":"stratura, straturae (f., first declension)","meaning":"a spreading, a paving","meaningCN":"铺层；铺砌"}]}},{"word":"layering","ipa_uk":"/ˈleɪərɪŋ/","ipa_us":"/ˈleɪərɪŋ/","definition_zh":"分层；层叠；层理；层层叠加的手法或效果","definition_en":"the act or result of arranging something in layers, or the effect of several layers seen together","core_image":"陶罐剖面露出三道不同颜色的泥条，像被压在一起的三张薄纸","scene":"陶罐剖面显示三道不同颜色的泥条，制陶人说明那是分次盘筑留下的痕迹。 Careful layering of clay gave the jar walls their even thickness.","sceneCN":"这里 layering 指「把材料一层层叠加的做法」（第 1 个义项：把材料分成层来堆叠的动作）；句意为细心的泥料分层使罐壁厚度均匀。图中可辨识物件：陶罐剖面、三道泥条、制陶人的手、刮刀。","pos":[{"tag":"n.","zh":"分层；层叠；层理；（艺术、设计中的）层次叠加"},{"tag":"v.","zh":"layer 的现在分词：把……分层放置；层层叠加"}],"collocations":[{"phrase":"layering of clay","zh":"泥料的分层"},{"phrase":"thermal layering","zh":"温度分层"},{"phrase":"sound layering","zh":"声音的层层叠加"},{"phrase":"layering effect","zh":"层次叠加效果"},{"phrase":"social layering","zh":"社会层化"},{"phrase":"layering technique","zh":"分层技法"}],"forms":[{"label":"名词（本义，通常不可数）","form":"layering"},{"label":"动词原形（layer）","form":"layer"},{"label":"三单（he/she/it）","form":"layers"},{"label":"过去式","form":"layered"},{"label":"过去分词","form":"layered"},{"label":"现在分词","form":"layering"}],"derivatives":[{"word":"layer","pos":"n./v.","zh":"层；把……分层放置"},{"word":"layered","pos":"adj.","zh":"分层的；有层次的"},{"word":"layerage","pos":"n.","zh":"压条法（园艺）"},{"word":"interlayer","pos":"n./v.","zh":"夹层；把……夹在层间"},{"word":"multilayer","pos":"adj./n.","zh":"多层的；多层结构"}],"senses":[{"no":"01","title":"Putting material down in layers","titleCN":"把材料一层层叠加的做法","definition":"the act of building something up by adding one layer of material after another","definitionCN":"通过一次次添加一层材料把某物堆叠起来","example":"Careful layering of clay gave the jar walls their even thickness.","exampleCN":"细心的泥料分层使罐壁厚度均匀。","why":"layer plus -ing names the activity, so the emphasis is on the sequence of additions rather than on the finished stack.","whyCN":"layer 加 -ing 命名这一活动，重点在一次次添加的次序，而非完成的叠层。"},{"no":"02","title":"Bedding in rock or sediment","titleCN":"岩石或沉积物的层理","definition":"the formation of distinct beds as sediment settles out in successive episodes","definitionCN":"沉积物在一次次事件中落下而形成独立层的过程","example":"Fine layering in the silt marks each quiet season of the lake.","exampleCN":"粉砂中细密的层理标出湖的每一个平静季节。","why":"geology uses the word for the process behind bedding, which is why it often appears beside stratification.","whyCN":"地质学用这个词指层理背后的过程，因此它常与 stratification 一同出现。"},{"no":"03","title":"Depth built by overlapping shapes","titleCN":"绘画与设计中用重叠形制造纵深","definition":"the technique of overlapping shapes, colours or transparencies so that the eye reads depth","definitionCN":"通过重叠形状、颜色或透明层，使眼睛读出纵深的手法","example":"The illustrator built depth by layering translucent washes.","exampleCN":"插画师用层层透明淡彩造出纵深。","why":"art borrowed the physical verb: each wash lies over the last, so depth is literally an accumulation of sheets.","whyCN":"艺术借用了这个实义动词：每层淡彩压在前一层上，纵深就是薄片的实际累积。"},{"no":"04","title":"Wearing clothes in layers","titleCN":"多层穿衣","definition":"the practice of wearing several garments one over another for warmth or style","definitionCN":"为保暖或造型而把数件衣物套穿在一起","example":"Layering is the only way to stay warm on a wet ridge.","exampleCN":"在湿冷山脊上，多层穿衣是唯一保暖的办法。","why":"outdoor writing treats the noun as a technique, and the layers can be added or removed as conditions change.","whyCN":"户外写作把这个名词当作一种方法，各层可随环境增减。"},{"no":"05","title":"Stacking sounds in a mix","titleCN":"音乐制作中叠加音轨","definition":"the technique of combining several recordings or parts so that they sound as one richer texture","definitionCN":"把多条录音或声部合成一个更厚实整体的技术","example":"The producer got that warmth from layering three takes of the same chord.","exampleCN":"制作人把同一和弦的三次录音叠加，得到那种温暖感。","why":"studio usage extends the verb to sound, which also stacks: each take is a sheet laid over the mix.","whyCN":"录音室用法把这个动词扩展到声音，声音同样叠压：每条录音都是铺在混音上的一层。"},{"no":"06","title":"Levels in a system design","titleCN":"系统设计中的分层","definition":"the arrangement of a system into levels, each with its own job and a narrow interface to the next","definitionCN":"把系统分成若干层，每层职责独立并与相邻层以窄接口相连","example":"Layering lets you replace the storage level without touching the display code.","exampleCN":"分层使你可以更换存储层而不碰显示代码。","why":"software borrowed the noun because layered designs can be changed one sheet at a time.","whyCN":"软件借用这个名词，因为分层设计可以一次只改一层。"},{"no":"07","title":"Ranked levels in an organization","titleCN":"组织中的等级层","definition":"the division of an organization or society into levels of authority or status","definitionCN":"组织或社会按权力或地位分成层级","example":"Too much layering slowed every decision to a crawl.","exampleCN":"层级过多使每个决定都慢得像爬。","why":"the metaphor is critical here: layering is often named as the problem rather than the solution.","whyCN":"这里的比喻带批评意味：分层常被指为问题而非解法。"},{"no":"08","title":"Levels of meaning or memory","titleCN":"抽象义：意义或记忆的层层叠加","definition":"the presence of several levels of meaning, memory or interpretation within one thing","definitionCN":"同一事物内部存在若干层意义、记忆或解读","example":"The novel rewards layering: each rereading adds a stratum the first reading missed.","exampleCN":"这部小说值得层层读：每次重读都添上初读错过的一层。","why":"abstract usage makes the noun analytical, naming what a reader or listener must peel apart.","whyCN":"抽象用法使这个名词具分析性，指读者或听者必须逐层剥开的东西。"}],"etymology":{"intro":{"en":"Layering is lay plus -er plus -ing. Lay descends from Old English lecgan 'to place', the causative of lie, and layer was first 'one who lays' before it meant a sheet. Dates are approximate.","cn":"layering 由 lay 加 -er 再加 -ing 构成。lay 源自古英语 lecgan「放置」，是 lie 的使役形式；layer 最初指「放置者」，后才指一层。年代均为约数。"},"items":[{"era":"OLD ENGLISH LECGAN","en":"Lecgan meant 'to place, put down', and it was the causative partner of licgan 'to lie'; the pair survives as lay and lie.","cn":"lecgan 意为「放置、放下」，是 licgan「躺」的使役配对；这一对至今保留为 lay 与 lie。"},{"era":"LAYER AS PERSON","en":"The agent suffix -er first made layer mean 'one who lays', as in a layer of bricks, a bricklayer.","cn":"-er 这个施事后缀最初使 layer 指「放置者」，如砌砖的人。"},{"era":"LAYER AS SHEET","en":"In the seventeenth century layer shifted from the person to the thing laid, and so came to mean a stratum or coating.","cn":"十七世纪 layer 从人转指被放置之物，于是意为层或涂层。"},{"era":"LAYERING AS PROCESS","en":"The nineteenth and twentieth centuries added -ing to name the activity, first in craft and geology, then in art and technology.","cn":"十九与二十世纪加 -ing 命名这一活动，先用于手艺与地质，后用于艺术与技术。"},{"era":"MODERN TRANSFER","en":"Sound mixing, software design and social criticism each took the word for their own stacked levels.","cn":"声音混制、软件设计与社会批评各自借这个词指自己的叠层。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the Old English verb is well attested, but its pre-Germanic ancestry is reconstructed rather than recorded.","cn":"来源不确定（更深词源）：古英语动词有充分书证，但其日耳曼语之前的谱系属重构而非有记录。"}]},"similar":{"note":{"en":"Group one sorts layering from words that look close but are built differently; group two sorts it from near words for layers and levels.","cn":"第一组把 layering 与形近但构词不同的词分开；第二组区分它与「层」「级」的近似说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"layer","ipa":"/ˈleɪə/","tag":"same family, base","definition":"The layer itself or the verb; layering names the activity or the combined effect of several layers.","definitionCN":"指层本身或动词；layering 指这一活动或若干层的合成效果。"},{"word":"laying","ipa":"/ˈleɪɪŋ/","tag":"same verb, no -er","definition":"The gerund of lay alone: placing something down once, without the sense of repeated sheets.","definitionCN":"只是 lay 的动名词：放下一次，不含反复叠层之意。"},{"word":"lair","ipa":"/leə/","tag":"different root","definition":"From Old English leger 'a place to lie', related to lie but not to lay; it means an animal's den.","definitionCN":"源自古英语 leger「躺卧之处」，与 lie 相关而与 lay 无关；指兽穴。"},{"word":"lawyer","ipa":"/ˈlɔːjə/","tag":"suffix look-alike","definition":"Ends in -yer, a different spelling of the agent suffix, and has nothing to do with placing.","definitionCN":"以 -yer 结尾，是施事后缀的另一种拼法，与放置无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stratification","ipa":"/ˌstrætɪfɪˈkeɪʃn/","tag":"technical peer","definition":"The geological and sociological term for layer formation; layering is its plainer counterpart.","definitionCN":"地质与社会学中表示成层的术语；layering 是其更朴素的对应词。"},{"word":"stacking","ipa":"/ˈstækɪŋ/","tag":"vertical piles","definition":"Putting whole objects one on another, as boxes; layering usually means thin sheets of material.","definitionCN":"把整件物体一个个叠起，如箱子；layering 通常指材料的薄层。"},{"word":"coating","ipa":"/ˈkəʊtɪŋ/","tag":"one covering","definition":"A single covering applied to a surface; layering implies several such coverings in sequence.","definitionCN":"施加在表面上的一层覆盖物；layering 意味着若干层依次叠加。"},{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"ranked structure","definition":"A system of ranks with authority; layering describes the physical or conceptual act of stacking levels.","definitionCN":"带权力的等级体系；layering 描述把层级叠起的实体或概念动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"lay + -er + -ing: the act of putting sheet after sheet in place.","cn":"lay + -er + -ing：把一层层薄片放上去的动作。"},{"en":"The family runs layer, layered, layering, multilayer, delayer.","cn":"同族词包括 layer、layered、layering、multilayer、delayer。"},{"en":"Craft, geology, art, sound and software all use the same image of stacked sheets.","cn":"手艺、地质、艺术、声音与软件都用同一张叠层意象。"},{"en":"Fixed phrases: layering of clay, sound layering, layering effect.","cn":"固定搭配：泥料分层、声音叠加、层次效果。"},{"en":"Compare lay and lie: you lay a sheet down, but the sheet lies on the table.","cn":"比较 lay 与 lie：你把薄片放下，薄片躺在桌上。"}],"abstract":[{"en":"Picture three translucent sheets of coloured paper held up to a window.","cn":"想象三张半透明彩纸对着窗举起。"},{"en":"Picture an onion cut in half, every ring a season.","cn":"想象洋葱被切成两半，每一圈是一季。"},{"en":"Picture a joke that also works as an accusation if you hear the lower layer.","cn":"想象一个笑话，若听出下面那层，同时是一句指责。"}]},"examples":[{"en":"The potter's layering produced a wall that dried without cracking.","cn":"陶工的分层做法使罐壁干燥而不开裂。"},{"en":"Layering three instruments gave the theme an unexpected weight.","cn":"叠加三件乐器使主题有了意外的分量。"},{"en":"Good layering in a drawing keeps the eye moving between depths.","cn":"绘画中良好的层次让目光在纵深间移动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「layer（层）+ ing（动作）」——一层层往上放 → 分层、叠层","word":"layering"},"root":"古英语 lecgan「放置」（lie 的使役形式）+ 施事后缀 -er + 动名词后缀 -ing；layer 十七世纪由「放置者」转指「层」。","sensesIntro":{"en":"Eight senses share one action, the placing of a sheet over a sheet, then spread from clay to rock, paint, clothes, sound, software, ranks and meaning.","cn":"八个义项共享一个动作：把一层盖在另一层上，随后从泥料扩展到岩石、绘画、衣着、声音、软件、等级与意义。"},"semanticMap":{"core":{"en":"CORE IMAGE: one sheet laid over another until depth appears.","cn":"核心意象：一层压一层，直到纵深出现。"},"chain":["PLACE A SHEET","ADD ANOTHER","BECOME BEDS","BUILD DEPTH","STACK PARTS","STACK LEVELS"],"branches":[{"senses":"S1 · S4","en":"PHYSICAL ADDING: clay and clothing are both built one sheet at a time.","cn":"实体添加：泥料与衣着都是一层一层加出来的。"},{"senses":"S2","en":"BEDDING: sediment repeats the gesture until rock is banded.","cn":"层理：沉积重复同一动作，直到岩石成带。"},{"senses":"S3 · S5","en":"DEPTH OF SENSATION: paint washes and sound takes overlap to build a fuller surface.","cn":"感官纵深：淡彩与录音叠加，造出更厚的面。"},{"senses":"S6 · S7","en":"SYSTEM LEVELS: software and organizations stack parts that can be changed one at a time.","cn":"系统层级：软件与组织叠起可逐层更换的部分。"},{"senses":"S8","en":"LAYERS OF MEANING: reading means peeling the stack apart.","cn":"意义之层：阅读就是把这叠层剥开。"}]},"affixes":{"intro":{"en":"Layering is an English formation from a native verb and two native suffixes, so its morphology is transparent.","cn":"layering 由本族动词加两个本族后缀构成，形态完全透明。"},"latinIntro":{"en":"Lay has no Latin cognate, so latinEntries is left empty rather than given a guessed root.","cn":"lay 没有拉丁同族词，因此 latinEntries 留空，不填猜测的词根。"},"items":[{"word":"lay","structure":"lecgan (Old English verb 'to place')","meaning":"to put down","meaningCN":"放下；放置","example":"She laid the sheet flat.","exampleCN":"她把薄片放平。"},{"word":"-er","structure":"-er (Old English agent suffix)","meaning":"one who does","meaningCN":"做……的人或物","example":"A bricklayer lays bricks.","exampleCN":"砌砖匠砌砖。"},{"word":"-ing","structure":"-ing (gerund and noun suffix)","meaning":"the act or result","meaningCN":"动作或结果","example":"The laying took all morning.","exampleCN":"放置花了一上午。"},{"word":"layer","structure":"lay + -er","meaning":"a sheet laid over another","meaningCN":"层；涂层","example":"A layer of dust covered the shelf.","exampleCN":"架上落了一层灰。"},{"word":"layering","structure":"layer + -ing","meaning":"the act of adding layers","meaningCN":"分层；叠层","example":"Layering kept the wall even.","exampleCN":"分层使墙面均匀。"},{"word":"layered","structure":"layer + -ed","meaning":"arranged in layers","meaningCN":"分层的；有层次的","example":"The cake has a layered filling.","exampleCN":"这蛋糕有分层的夹心。"},{"word":"multilayer","structure":"multi- (many) + layer","meaning":"having many layers","meaningCN":"多层的","example":"A multilayer board is stiffer.","exampleCN":"多层板更硬。"},{"word":"interlayer","structure":"inter- (between) + layer","meaning":"a layer between two others","meaningCN":"夹在两层之间的层","example":"A clay interlayer seals the joint.","exampleCN":"一层黏土夹层封住接缝。"},{"word":"layerage","structure":"layer + -age (process)","meaning":"propagation by layering stems","meaningCN":"压条法","example":"Layerage rooted the rose in a season.","exampleCN":"压条法使这株玫瑰一季生根。"}],"latinEntries":[]}},{"word":"bedrock","ipa_uk":"/ˈbedrɒk/","ipa_us":"/ˈbedrɑːk/","definition_zh":"基岩；底岩；基础、根基；基本原则或核心信念","definition_en":"the solid rock beneath loose soil and gravel, or the firm base on which something rests","core_image":"推土机铲掉表层土，露出灰白色的坚硬岩面，铲齿在上面打滑","scene":"推土机铲掉表层土后，司机下去敲了敲那层坚硬的灰岩，说下面再也挖不动了。 The drill stopped dead when it reached bedrock under the loose gravel.","sceneCN":"这里 bedrock 指「松散堆积物之下的坚硬基岩」（第 1 个义项：地表覆盖层之下的连续坚岩）；句意为钻头碰到砾石下面的基岩就再也钻不动了。图中可辨识物件：剥离的表土、灰白岩面、钻头、打滑的铲齿。","pos":[{"tag":"n.","zh":"基岩；底岩；（比喻）基础、根基、基本原则"}],"collocations":[{"phrase":"reach bedrock","zh":"钻到基岩；触及根本"},{"phrase":"bedrock geology","zh":"基岩地质"},{"phrase":"bedrock of the economy","zh":"经济的基础"},{"phrase":"bedrock principle","zh":"根本原则"},{"phrase":"solid bedrock","zh":"坚固的基岩"},{"phrase":"bedrock belief","zh":"核心信念"}],"forms":[{"label":"名词（本义）","form":"bedrock"},{"label":"名词复数（少见）","form":"bedrocks"},{"label":"相关词（表土）","form":"overburden"},{"label":"相关词（风化层）","form":"regolith"},{"label":"相关形容词","form":"bedrock"}],"derivatives":[{"word":"bedding","pos":"n.","zh":"层理；铺层"},{"word":"bed","pos":"n.","zh":"床；层；河床"},{"word":"rock","pos":"n.","zh":"岩石"},{"word":"bedrock geology","pos":"n.","zh":"基岩地质学"}],"senses":[{"no":"01","title":"Solid rock under the soil","titleCN":"松散覆盖层之下的连续坚岩","definition":"the continuous mass of solid rock that lies beneath soil, gravel and other loose material","definitionCN":"位于土壤、砾石等松散物质之下的连续坚固体","example":"The well had to be drilled through nine metres of clay before it hit bedrock.","exampleCN":"这口井穿过九米黏土才打到基岩。","why":"the compound is literal: the bed on which loose material rests, so hard that it is the reference surface for drilling.","whyCN":"这个复合词是字面义：松散物质所躺的「床」，坚硬到成为钻探的参照面。"},{"no":"02","title":"The geological basement","titleCN":"地质学上的基底岩系","definition":"the older, usually crystalline rock that underlies a sedimentary basin and its cover","definitionCN":"位于沉积盆地及其盖层之下的较老、通常为结晶质的岩石","example":"The basin's bedrock is Archean gneiss, exposed only at the rim.","exampleCN":"该盆地的基底是太古代片麻岩，只在边缘出露。","why":"geology uses the word for the floor of a basin, which may lie kilometres below the surface beds.","whyCN":"地质学用这个词指盆地的底，它可能位于地表层之下数公里。"},{"no":"03","title":"The firm base of anything","titleCN":"任何事物的坚实基础","definition":"the underlying support on which a structure, system or argument depends","definitionCN":"结构、体系或论证所依赖的底层支撑","example":"Years of routine maintenance are the bedrock of a safe railway.","exampleCN":"多年例行维护是安全铁路的基础。","why":"the metaphor keeps the engineering sense: remove the base and everything above it settles or cracks.","whyCN":"这个比喻保留工程义：抽掉底座，上面的一切就会沉降或开裂。"},{"no":"04","title":"Core principles","titleCN":"核心原则、根本信条","definition":"the basic rules or values that a group treats as non-negotiable","definitionCN":"一个群体视为不可让步的基本规则或价值","example":"Free inquiry is bedrock in any research university.","exampleCN":"自由探究是任何研究型大学的根本原则。","why":"the word signals that these rules are not policies to be traded but the surface everything else is built on.","whyCN":"这个词标示这些规则不是可交易的策略，而是其余一切所建的岩面。"},{"no":"05","title":"A reliable factual core","titleCN":"可靠的事实核心","definition":"the verified facts that a case or claim can safely rest on","definitionCN":"一项主张可以安全依托的、已被核实的事实","example":"The prosecution's case had bedrock: two witnesses and a signed ledger.","exampleCN":"控方的案子有坚实基础：两名证人与一本签名的账簿。","why":"legal writing uses the image to separate what is proven from what is merely argued.","whyCN":"法律写作借这个意象把已证之事与仅属论辩之事分开。"},{"no":"06","title":"A political stronghold","titleCN":"政治上的稳固票仓","definition":"a region or group that reliably supports a party and is unlikely to swing","definitionCN":"稳定支持某党、不易转向的地区或群体","example":"The northern valleys remain the party's bedrock.","exampleCN":"北部各谷地仍是该党的票仓。","why":"politics borrows the word because such support is treated as terrain that cannot be moved.","whyCN":"政治借用这个词，因为这种支持被视为搬不动的地形。"},{"no":"07","title":"The floor of a mine","titleCN":"矿井或采场的底板","definition":"the rock floor on which a seam or working rests, or the lowest level of a mine","definitionCN":"煤层或工作面所坐的岩底，或矿井的最下层","example":"The seam was worked down to bedrock and then abandoned.","exampleCN":"煤层一直采到基岩底板，随后弃置。","why":"mining needs a precise word for the bottom, since everything above is measured from it.","whyCN":"采矿需要一个精确的词指底，因为上面一切都以它为基准测量。"},{"no":"08","title":"The lowest social layer","titleCN":"抽象义：社会的最底层","definition":"the poorest or most excluded layer of a society, thought of as the floor beneath all others","definitionCN":"社会中最贫困或最被排斥的一层，被视为其余各层之下的底","example":"Policy that ignores the bedrock of the housing market helps nobody.","exampleCN":"忽视住房市场最底层的政策帮不到任何人。","why":"the image turns social stratification on its side: the lowest layer is also the one everything else presses down on.","whyCN":"这个意象把社会分层横过来看：最下层也是其余一切向下压的那一层。"}],"etymology":{"intro":{"en":"Bedrock is an English compound of bed and rock, coined in the nineteenth century for the solid rock under loose deposits. Rock itself comes through Old Northern French from Medieval Latin rocca, a word of uncertain origin. Dates are approximate.","cn":"bedrock 是 bed 与 rock 的英语复合词，十九世纪为指松散沉积之下的坚岩而造。rock 经古北法语来自中世纪拉丁 rocca，该词来源不确定。年代均为约数。"},"items":[{"era":"OLD ENGLISH BEDD","en":"Bedd meant a sleeping place and, by extension, a flat layer on which something rests, as a river bed or a rock bed.","cn":"bedd 指睡卧之处，引申为某物所躺的平面，如河床或岩层。"},{"era":"ROCK IN ENGLISH","en":"Rock entered Middle English from Old Northern French roque, which goes back to Medieval Latin rocca; the earlier history of that word is not settled.","cn":"rock 经古北法语 roque 进入中古英语，上溯中世纪拉丁 rocca；该词更早的历史没有定论。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"Geologists formed bedrock to name the solid mass below soil and alluvium, and the compound spread with drilling and mining.","cn":"地质学家造出 bedrock 以指土壤与冲积层之下的固体岩体，这个词随钻探与采矿传播开来。"},{"era":"ENGINEERING USE","en":"Builders adopted it for the bearing surface a foundation must reach, which fixed the modern technical sense.","cn":"营造者采用它指基础必须达到的持力面，由此固定了现代技术义。"},{"era":"METAPHOR","en":"From the nineteenth century the word was applied to the firm base of institutions, beliefs and arguments.","cn":"从十九世纪起，这个词被用于制度、信念与论证的坚实根基。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin ancestry of rocca is unknown, and every form proposed for it is a reconstruction.","cn":"来源不确定（更深词源）：rocca 在拉丁语之前的谱系不明，凡为其提出的形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates bedrock from look-alikes that share one element but not the compound; group two separates it from words for bases and foundations.","cn":"第一组把 bedrock 与共享一个成分、却非同一复合词的形近词分开；第二组区分它与「基础」「根基」的近似说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bed","ipa":"/bed/","tag":"one element only","definition":"By itself it means a sleeping place or a layer; bedrock adds the hardness and continuity of solid rock.","definitionCN":"单独使用时指睡卧处或一层；bedrock 增添坚岩的硬度与连续性。"},{"word":"rock","ipa":"/rɒk/","tag":"one element only","definition":"Any solid mineral matter, including loose boulders; bedrock specifically means the rock in place beneath cover.","definitionCN":"泛指固体矿物，包括散落巨石；bedrock 特指覆盖层之下原地的岩体。"},{"word":"bedsore","ipa":"/ˈbedsɔː/","tag":"compound look-alike","definition":"Bed plus sore, a skin injury from lying still; the shared first element is all they have in common.","definitionCN":"bed 加 sore，指久卧造成的皮肤损伤；共同点只在第一个成分。"},{"word":"bedrocked","ipa":"/ˈbedrɒkt/","tag":"same family, rare","definition":"A technical adjective for a foundation set directly on bedrock; it is a derived form, not a synonym.","definitionCN":"指基础直接置于基岩上的技术形容词，是派生形式而非同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regolith","ipa":"/ˈreɡəlɪθ/","tag":"loose cover","definition":"The loose blanket of broken rock and soil above bedrock; the two words name the cover and the floor.","definitionCN":"基岩之上破碎岩石与土壤的松散覆盖层；两词一名盖、一名底。"},{"word":"foundation","ipa":"/faʊnˈdeɪʃn/","tag":"built support","definition":"The constructed base of a building, which may or may not reach bedrock; it is man-made, bedrock is not.","definitionCN":"建筑的人造底座，未必达到基岩；foundation 是人造的，bedrock 不是。"},{"word":"cornerstone","ipa":"/ˈkɔːnəstəʊn/","tag":"symbolic first stone","definition":"A ceremonial stone or a figurative essential part; it stresses origin and symbolism, not geological depth.","definitionCN":"奠基仪式用的石块，或比喻最要紧的部分；强调起源与象征，而非地质深度。"},{"word":"base","ipa":"/beɪs/","tag":"general support","definition":"The broadest word for what something stands on, physical or abstract, without the hardness of rock.","definitionCN":"指某物所立之处的最宽泛词，实体或抽象皆可，不含岩石的坚硬。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bed 'resting surface' + rock: the rock that everything else lies on.","cn":"bed「所躺之面」+ rock：其余一切所躺的那块岩。"},{"en":"Drillers treat bedrock as the reference surface, which is why 'reach bedrock' also means 'reach the bottom of the matter'.","cn":"钻探者把基岩当作参照面，因此「钻到基岩」也引申为「触及根本」。"},{"en":"The word pairs naturally with overburden and regolith, its loose cover.","cn":"这个词天然与 overburden 和 regolith（松散覆盖层）配对。"},{"en":"Fixed phrases: bedrock geology, bedrock principle, bedrock belief.","cn":"固定搭配：基岩地质、根本原则、核心信念。"},{"en":"The metaphor keeps the engineering sense: no base, no building.","cn":"这个比喻保留工程义：没有底座，就没有建筑。"}],"abstract":[{"en":"Picture a drill bit screaming to a stop on grey stone.","cn":"想象钻头在灰岩上尖叫着停住。"},{"en":"Picture a house whose lowest course of stone sits directly on clean rock.","cn":"想象一栋房，最下一层石料直接坐在净岩上。"},{"en":"Picture an argument that collapses the moment one plain fact is removed.","cn":"想象一个论证，抽掉一条朴素事实就整个垮掉。"}]},"examples":[{"en":"The bridge piers are founded on bedrock, not on the river gravel.","cn":"桥墩立在基岩上，而非河砾之上。"},{"en":"Trust between doctors and patients is the bedrock of the clinic.","cn":"医患之间的信任是这家诊所的根基。"},{"en":"Weathering has eaten the bedrock into a rough pavement.","cn":"风化把基岩啃成一片粗糙的石面。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bed（床）+ rock（岩）」——岩做的床，压在最下面 → 基岩、根基","word":"bedrock"},"root":"英语 bed（古英语 bedd「躺卧之处、底」）+ rock（经古北法语 roque，上溯中世纪拉丁 rocca，来源不确定）；十九世纪地质复合词。","sensesIntro":{"en":"Eight senses all rest on one image, the rock at the bottom: first the geological floor, then any firm base, then the rules, facts, voters and people that everything else presses down on.","cn":"八个义项都依托同一个意象——最下面那块岩：先是地质底，再是任何坚实基础，然后是规则、事实、票源以及其余一切向下压的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hard grey floor under everything loose, unmistakable when the drill reaches it.","cn":"核心意象：松散之物下面一层坚硬的灰岩面，钻头碰到时不会认错。"},"chain":["ROCK BELOW","HARD FLOOR","BASE OF A BUILDING","BASE OF A CLAIM","BASE OF A PARTY","LOWEST LAYER"],"branches":[{"senses":"S1 · S2","en":"GEOLOGICAL FLOOR: the surface under cover and the basement under a basin are the same rock seen at two scales.","cn":"地质底：覆盖层之下的面与盆地之下的基底，是同一块岩的两种尺度。"},{"senses":"S3 · S5","en":"FIRM SUPPORT: a structure and a case both fail if the base is removed.","cn":"坚实支撑：结构与案子一旦抽掉底座都会垮。"},{"senses":"S4","en":"CORE RULES: principles are treated as terrain, not as tradable policy.","cn":"核心规则：原则被当作地形，而非可交易的策略。"},{"senses":"S6 · S7","en":"TERRAIN AND FLOOR: safe seats and mine floors are both places nothing above can move.","cn":"地形与底板：稳固票仓与矿井底板都是上面之物搬不动的地方。"},{"senses":"S8","en":"SOCIAL BOTTOM: the lowest layer bears the weight of all the others.","cn":"社会底层：最下一层承着其余各层的重量。"}]},"affixes":{"intro":{"en":"Bedrock is a native English compound, so its parts are read as ordinary nouns rather than as Latin morphemes.","cn":"bedrock 是本族英语复合词，其成分应按普通名词而非拉丁语素来读。"},"latinIntro":{"en":"Bed is native Old English; rock reaches English through French and Medieval Latin rocca, whose own origin is uncertain, so no confident Latin root is offered.","cn":"bed 为本族古英语词；rock 经法语与中世纪拉丁 rocca 进入英语，而 rocca 自身来源不确定，因此不给出有把握的拉丁词根。"},"items":[{"word":"bed","structure":"bedd (Old English noun 'sleeping place, resting surface')","meaning":"a resting surface","meaningCN":"所躺之面；底","example":"The river bed was dry.","exampleCN":"河床干了。"},{"word":"rock","structure":"roque (Old Northern French) from rocca (Medieval Latin, origin uncertain)","meaning":"solid stone","meaningCN":"坚石","example":"The rock split along a joint.","exampleCN":"岩石沿节理裂开。"},{"word":"bedrock","structure":"bed + rock (compound)","meaning":"the rock under loose cover","meaningCN":"基岩","example":"The core sample reached bedrock.","exampleCN":"岩芯样品打到了基岩。"},{"word":"bedrock geology","structure":"bedrock + geology (compound term)","meaning":"study of the basement rock","meaningCN":"基岩地质学","example":"Bedrock geology is mapped separately.","exampleCN":"基岩地质单独填图。"},{"word":"bedrocked","structure":"bedrock + -ed (having)","meaning":"founded on bedrock","meaningCN":"置于基岩上的","example":"The pier is bedrocked at low tide.","exampleCN":"低潮时可见桥墩坐在基岩上。"},{"word":"bed","structure":"bedd (Old English)","meaning":"layer; channel floor","meaningCN":"层；河底","example":"A thin bed of sand lies over clay.","exampleCN":"一层薄沙覆在黏土上。"},{"word":"riverbed","structure":"river + bed","meaning":"the floor of a channel","meaningCN":"河床","example":"Gravel covers the riverbed.","exampleCN":"砾石覆盖河床。"},{"word":"seedbed","structure":"seed + bed","meaning":"prepared ground for sowing","meaningCN":"苗床","example":"The seedbed was raked fine.","exampleCN":"苗床被耙得很细。"},{"word":"bedding","structure":"bed + -ing","meaning":"the arrangement of layers","meaningCN":"层理；铺层","example":"Bedding planes dip east.","exampleCN":"层理面向东倾。"}],"latinEntries":[{"word":"rocca","structure":"rocca, roccae (f., Medieval Latin; origin uncertain)","meaning":"a rock, a cliff","meaningCN":"岩石；崖壁"}]}},{"word":"fossil","ipa_uk":"/ˈfɒsl/","ipa_us":"/ˈfɑːsl/","definition_zh":"化石；化石标本；化石燃料（作定语）；老顽固；过时的制度或观念","definition_en":"the preserved remains or trace of an animal or plant from a past geological age, or something outdated","core_image":"页岩被劈开，一片鱼形的黑色印痕露出来，鳞片排列仍看得清","scene":"页岩劈开时，一片鱼形的黑色印痕露出来，鳞片排列还看得清。 The split shale revealed a fish fossil with scales still legible.","sceneCN":"这里 fossil 指「保存在岩层中的古生物遗体」（第 1 个义项：地质时期生物的保存遗体或印痕）；句意为劈开的页岩中露出一具鱼化石，鳞片仍清晰可辨。图中可辨识物件：劈开的页岩、鱼形印痕、鳞片纹理、地质锤。","pos":[{"tag":"n.","zh":"化石；化石标本；（口语）老顽固、过时的人或物"},{"tag":"adj.","zh":"化石的；从化石中得来的（如 fossil fuel）"}],"collocations":[{"phrase":"fossil record","zh":"化石记录"},{"phrase":"fossil fuel","zh":"化石燃料"},{"phrase":"trace fossil","zh":"遗迹化石"},{"phrase":"living fossil","zh":"活化石"},{"phrase":"fossil evidence","zh":"化石证据"},{"phrase":"fossil bed","zh":"化石层"}],"forms":[{"label":"名词单数","form":"fossil"},{"label":"名词复数","form":"fossils"},{"label":"形容词用法","form":"fossil"},{"label":"相关动词","form":"fossilize"},{"label":"相关名词","form":"fossilization"}],"derivatives":[{"word":"fossilize","pos":"v.","zh":"使成为化石；使僵化"},{"word":"fossilization","pos":"n.","zh":"化石化；僵化"},{"word":"fossiliferous","pos":"adj.","zh":"含化石的"},{"word":"fossilized","pos":"adj.","zh":"已成化石的；僵化的"},{"word":"subfossil","pos":"n.","zh":"亚化石"}],"senses":[{"no":"01","title":"Preserved remains in rock","titleCN":"保存在岩层中的古生物遗体","definition":"the remains, impression or cast of an organism preserved in rock from an earlier geological period","definitionCN":"保存在较早地质时期岩层中的生物遗体、印痕或铸型","example":"The museum's oldest fossil is a fern print from the Carboniferous.","exampleCN":"馆藏最古老的化石是一件石炭纪的蕨类印痕。","why":"the Latin word meant 'dug up', so any organic trace hard enough to survive in stone qualifies.","whyCN":"拉丁词义为「挖出来的」，因此任何硬到能在石中留存的生物痕迹都算。"},{"no":"02","title":"A specimen in a collection","titleCN":"馆藏的一件化石标本","definition":"one catalogued piece held in a museum or study collection, with a number and a locality","definitionCN":"博物馆或研究收藏中编了号、记了产地的一件标本","example":"Each fossil in the drawer carries a label with its grid reference.","exampleCN":"抽屉里每件化石都带着写有网格坐标的标签。","why":"collecting practice turns the mass noun into a countable object, so a fossil can be borrowed, cast and photographed.","whyCN":"收藏实践把不可数的总称变成可数物件，于是化石可以出借、翻模与拍摄。"},{"no":"03","title":"A species that has barely changed","titleCN":"存活至今而形态几乎未变的物种","definition":"a living species that closely resembles its ancient relatives and has changed very little","definitionCN":"与远古亲属极为相似、变化极小的现存物种","example":"The ginkgo is often called a living fossil, though its genes have moved on.","exampleCN":"银杏常被称为活化石，尽管其基因已经变化。","why":"the phrase is a deliberate paradox: the organism is alive, yet read as if it were stone.","whyCN":"这个短语是刻意的悖论：生物还活着，却像石头一样被解读。"},{"no":"04","title":"Fuel from ancient organic matter","titleCN":"源自远古有机质的燃料","definition":"coal, oil or gas formed from buried organisms and burned as fuel, used attributively","definitionCN":"由埋藏的远古生物形成、被燃烧作燃料的煤、石油或天然气，作定语使用","example":"The city pledged to cut fossil fuel use by a third.","exampleCN":"该市承诺把化石燃料用量削减三分之一。","why":"the attributive use compresses a long history: the fuel is ancient sunlight stored in rock.","whyCN":"定语用法压缩了一段长历史：这种燃料是储在岩石里的远古阳光。"},{"no":"05","title":"A person stuck in the past","titleCN":"口语：思想陈旧的老顽固","definition":"a person with fixed, old-fashioned views who resists any change","definitionCN":"观念固定、守旧、抗拒任何改变的人","example":"The committee's chairman is an old fossil who still uses a typewriter.","exampleCN":"委员会主席是个还在用打字机的老顽固。","why":"the insult works because a fossil is something that stopped changing long ago and now merely persists.","whyCN":"这个贬称之所以有效，是因为化石早已停止变化，只是仍留在那里。"},{"no":"06","title":"An outdated institution or idea","titleCN":"过时的制度或观念","definition":"a rule, practice or idea that survives long after its conditions have gone","definitionCN":"在原有条件消失后仍存留很久的规则、做法或观念","example":"The licensing rule is a fossil of the cartage era.","exampleCN":"这项许可规定是马车运输时代留下的化石。","why":"institutions leave traces the way organisms do, so the metaphor transfers without much strain.","whyCN":"制度像生物一样留下痕迹，因此这个比喻转移过来并不费力。"},{"no":"07","title":"A trace fossil","titleCN":"遗迹化石（活动留下的痕迹）","definition":"a preserved record of an organism's activity, such as a track, burrow or feeding mark, rather than its body","definitionCN":"生物活动而非遗体留下的保存记录，如足迹、潜穴或觅食痕","example":"The sandstone holds trace fossils but no bones at all.","exampleCN":"这层砂岩只有遗迹化石，完全没有骨骼。","why":"palaeontology separates the body from the behaviour, and the compound keeps that distinction visible.","whyCN":"古生物学把遗体与行为分开，这个复合词让这一区分保持可见。"},{"no":"08","title":"A fossil used for dating","titleCN":"用于定年的化石","definition":"a species whose known time range lets a rock layer be assigned an age","definitionCN":"已知生存时限可用于给岩层定年的物种","example":"A single ammonite fossil fixed the bed to the Jurassic.","exampleCN":"一件菊石化石把这层定为侏罗纪。","why":"biostratigraphy treats certain fossils as index markers, valued for their date rather than their beauty.","whyCN":"生物地层学把某些化石当作标志物，看重的是年代而非美观。"},{"no":"09","title":"Anything preserved in stone","titleCN":"形容词义：被保存在石头里的","definition":"preserved in rock, or made of the mineral matter that replaced an organism","definitionCN":"保存在岩石中的，或由替换生物体的矿物质构成的","example":"The fossil wood still shows annual growth rings.","exampleCN":"这块化石木仍能看到年轮。","why":"the adjective keeps the oldest literal sense, describing the state of preservation rather than a category of object.","whyCN":"形容词保留最古老的字面义，描写保存状态，而非物类。"}],"etymology":{"intro":{"en":"Fossil comes from Latin fossilis 'dug up', from fodere 'to dig'. English adopted it in the seventeenth century for anything dug from the earth, before it narrowed to organic remains. Dates are approximate.","cn":"fossil 来自拉丁 fossilis「挖出来的」，源于 fodere「挖掘」。英语于十七世纪引入，最初泛指从地下挖出之物，后来收窄为生物遗体。年代均为约数。"},"items":[{"era":"LATIN FODERE","en":"Fodere meant 'to dig', and its participle fossus produced fossilis 'dug up, dug out'.","cn":"fodere 意为「挖掘」，其分词 fossus 产生 fossilis「被挖出的」。"},{"era":"WIDE EARLY SENSE","en":"In sixteenth- and seventeenth-century Latin, fossilis covered minerals, gems and anything else dug from the ground, not only living things.","cn":"在十六、十七世纪的拉丁语中，fossilis 涵盖矿物、宝石以及一切从地下挖出之物，并不限于生物。"},{"era":"ENGLISH NARROWING","en":"English naturalists gradually restricted fossil to the remains and traces of once-living things found in rock.","cn":"英国博物学者逐渐把 fossil 收窄为岩石中发现的、曾属生物的那些遗体与痕迹。"},{"era":"FUEL AND FIGURE","en":"The nineteenth century added fossil fuel, and the same period produced the joking use for an out-of-date person.","cn":"十九世纪增添了 fossil fuel 一义，同一时期也产生了戏指过时之人的用法。"},{"era":"LIVING FOSSIL","en":"The phrase living fossil was applied to species that seem unchanged since deep time, an image rather than a taxonomic category.","cn":"living fossil 一语用于自远古以来似无变化的物种，是意象而非分类学范畴。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (only the first dating is in doubt): the Latin derivation is secure, but the exact decade of the English narrowing varies by author.","cn":"来源不确定（仅首见年代）：拉丁派生是确定的，但英语收窄的确切年代因作者而异。"}]},"similar":{"note":{"en":"Group one separates fossil from words built on the same Latin dig-family and from look-alikes; group two separates it from other remains and from the figurative senses.","cn":"第一组把 fossil 与同出拉丁「挖」族的词及形近词分开；第二组区分它与其它遗体说法及比喻义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fossilize","ipa":"/ˈfɒsəlaɪz/","tag":"same family, verb","definition":"To make or become a fossil; the noun names the object, the verb the process.","definitionCN":"使成为化石或变成化石；名词指对象，动词指过程。"},{"word":"fossiliferous","ipa":"/ˌfɒsɪˈlɪfərəs/","tag":"same family, adjective","definition":"Fossil plus -ferous 'bearing': rock that contains fossils, said of a layer.","definitionCN":"fossil 加 -ferous「承载」：含化石的，用于形容岩层。"},{"word":"fosse","ipa":"/fɒs/","tag":"same Latin root, other word","definition":"From Latin fossa 'a ditch', also from fodere; it means a trench, not a remain.","definitionCN":"来自拉丁 fossa「沟」，亦出 fodere；意为壕沟，而非遗体。"},{"word":"fossick","ipa":"/ˈfɒsɪk/","tag":"different origin","definition":"An Australian English verb for prospecting among old workings; its origin is uncertain and not the Latin fossilis line.","definitionCN":"澳大利亚英语动词，指在旧矿渣中搜寻；来源不确定，不属拉丁 fossilis 一线。"}]},{"heading":"NEAR MEANING","entries":[{"word":"relic","ipa":"/ˈrelɪk/","tag":"any surviving trace","definition":"Something that survives from an earlier time, including objects and customs; it need not be mineralised.","definitionCN":"从较早时期留存之物，包括器物与习俗；不必矿化。"},{"word":"remains","ipa":"/rɪˈmeɪnz/","tag":"body parts","definition":"What is left of a body, recent or ancient; fossil adds deep time and preservation in rock.","definitionCN":"遗体残留，不论新旧；fossil 增添深时间与岩中保存之意。"},{"word":"cast","ipa":"/kɑːst/","tag":"a preservation mode","definition":"A replica formed when minerals fill a mould left by a dissolved organism; one kind of fossil.","definitionCN":"矿物填充生物溶解后留下的模腔所形成的复制体，是化石的一种。"},{"word":"mummy","ipa":"/ˈmʌmi/","tag":"soft-tissue preservation","definition":"A body preserved by drying or cold rather than mineralisation; it is not usually called a fossil.","definitionCN":"靠干燥或寒冷而非矿化保存的尸体，通常不称化石。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin fossilis 'dug up' from fodere 'to dig': what the hammer brings out of the rock.","cn":"拉丁 fossilis「挖出的」，源于 fodere「挖」：锤子从岩中取出的东西。"},{"en":"The family runs fossil, fossils, fossilize, fossilization, fossiliferous, subfossil.","cn":"同族词包括 fossil、fossils、fossilize、fossilization、fossiliferous、subfossil。"},{"en":"Fixed phrases: fossil record, fossil fuel, trace fossil, living fossil.","cn":"固定搭配：化石记录、化石燃料、遗迹化石、活化石。"},{"en":"The same Latin dig-root gives fosse 'ditch', a hole rather than a remain.","cn":"同一拉丁「挖」根还给出 fosse「壕沟」，是洞而非遗体。"},{"en":"The insult is geological: something that stopped changing long ago and merely persists.","cn":"这个贬称是地质式的：早已停止变化，只是仍留在那里。"}],"abstract":[{"en":"Picture a leaf pressed into mud and read a million years later.","cn":"想象一片叶子压进泥里，百万年后被读出。"},{"en":"Picture a clock that stopped at noon and was never wound again.","cn":"想象一只停在正午、再没上过发条的钟。"},{"en":"Picture a rulebook still in force for a machine nobody owns.","cn":"想象一本仍有效的规程，而其机器已无人拥有。"}]},"examples":[{"en":"The fossil was prepared with needles over three months.","cn":"这件化石用针修整了三个月。"},{"en":"Burning fossil fuel returns stored carbon to the air.","cn":"燃烧化石燃料把储藏的碳送回大气。"},{"en":"His views on office work are frankly fossil.","cn":"他对办公室工作的看法坦白说过时了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「foss（挖）+ il」——从地下挖出来的东西 → 化石、老古董","word":"fossil"},"root":"拉丁 fossilis「挖出的」，源于 fodere「挖掘」；英语十七世纪借入，原泛指地下挖出之物，后收窄为生物遗体。","sensesIntro":{"en":"Nine senses begin with something dug from rock, then split into specimen, living paradox, fuel, insult, institution, trace, dating tool and adjective.","cn":"九个义项从「从岩中挖出之物」开始，随后分出标本、活着的悖论、燃料、贬称、制度、遗迹、定年工具与形容词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shape in stone that once was alive and will not change again.","cn":"核心意象：石中一个曾经活着的形状，再也不会改变。"},"chain":["DUG UP","STONE SHAPE","COLLECTED OBJECT","ANCIENT FUEL","FROZEN PERSON","DATING MARKER"],"branches":[{"senses":"S1 · S9","en":"PRESERVED FORM: the noun and the adjective describe the same mineral state.","cn":"保存的形态：名词与形容词描写同一种矿物状态。"},{"senses":"S2 · S8","en":"OBJECT AND TOOL: one fossil is a specimen, another is a date.","cn":"对象与工具：一件是标本，另一件是年代。"},{"senses":"S3 · S7","en":"TRACES OF LIFE: a living species and a burrow both count as traces of the ancient.","cn":"生命的痕迹：现存物种与潜穴都算远古痕迹。"},{"senses":"S4","en":"STORED SUNLIGHT: fuel is the same burial read as energy.","cn":"储存的阳光：燃料是同一种埋藏被读作能量。"},{"senses":"S5 · S6","en":"FROZEN THINGS: a person and a rule both stopped changing and merely persist.","cn":"冻住之物：人与规则都停止变化，只是仍留在那里。"}]},"affixes":{"intro":{"en":"Fossil is a Latin adjective turned noun, and its root recurs in English words about digging and ditches.","cn":"fossil 是拉丁形容词转成的名词，其词根在英语中反复出现于与挖掘、沟渠有关的词。"},"latinIntro":{"en":"Latin fodere 'to dig' gives fossilis 'dug up', fossa 'ditch' and fossor 'digger'; English adds -ize, -ization and -ferous to extend the family.","cn":"拉丁 fodere「挖」产生 fossilis「挖出的」、fossa「沟」与 fossor「挖掘者」；英语用 -ize、-ization、-ferous 扩展词族。"},"items":[{"word":"foss-","structure":"fodere / fossus (Latin verb and participle 'dig, dug')","meaning":"to dig","meaningCN":"挖掘","example":"The root names the act of digging out.","exampleCN":"这个词根命名挖出的动作。"},{"word":"fossil","structure":"fossilis (Latin adjective 'dug up')","meaning":"something dug up","meaningCN":"挖出之物；化石","example":"The fossil came out in three pieces.","exampleCN":"这块化石裂成三块取出。"},{"word":"fossilize","structure":"fossil + -ize (make, become)","meaning":"to turn into stone","meaningCN":"使成为化石","example":"Mineral water can fossilize bone.","exampleCN":"矿物水能使骨骼化石化。"},{"word":"fossilization","structure":"fossilize + -ation (process)","meaning":"the process of becoming a fossil","meaningCN":"化石化过程","example":"Fossilization needs rapid burial.","exampleCN":"化石化需要迅速埋藏。"},{"word":"fossiliferous","structure":"fossil + -ferous (bearing)","meaning":"carrying fossils","meaningCN":"含化石的","example":"A fossiliferous limestone forms the ledge.","exampleCN":"一层含化石的石灰岩构成这级岩台。"},{"word":"fossilized","structure":"fossilize + -ed (past participle)","meaning":"turned to stone","meaningCN":"已成化石的","example":"Fossilized wood polishes like agate.","exampleCN":"化石木能磨得像玛瑙。"},{"word":"subfossil","structure":"sub- (below, partly) + fossil","meaning":"a partly fossilised remain","meaningCN":"亚化石","example":"Subfossil bones come from recent caves.","exampleCN":"亚化石骨骼出自较近的洞穴。"},{"word":"fosse","structure":"fossa (Latin 'ditch')","meaning":"a trench","meaningCN":"壕沟","example":"The fosse lies outside the wall.","exampleCN":"壕沟在墙外。"},{"word":"fossick","structure":"origin uncertain (Australian English)","meaning":"to search old workings","meaningCN":"翻找旧矿渣","example":"They fossick for opals on the ridge.","exampleCN":"他们在山脊翻找蛋白石。"}],"latinEntries":[{"word":"fodere","structure":"fodere, fodi, fossum (verb, third conjugation)","meaning":"to dig","meaningCN":"挖掘"},{"word":"fossilis","structure":"fossilis, fossile (adj., third declension)","meaning":"dug up","meaningCN":"被挖出的"},{"word":"fossa","structure":"fossa, fossae (f., first declension)","meaning":"a ditch, trench","meaningCN":"沟；壕"},{"word":"fossor","structure":"fossor, fossoris (m., third declension)","meaning":"a digger","meaningCN":"挖掘者"}]}},{"word":"fossilization","ipa_uk":"/ˌfɒsəlaɪˈzeɪʃn/","ipa_us":"/ˌfɑːsələˈzeɪʃn/","definition_zh":"化石化（作用）；成为化石的状态；语言僵化；制度或观念的僵化","definition_en":"the process by which an organism's remains become preserved in rock, or the state of becoming fixed and unchanging","core_image":"实验室里，一块兽骨浸在矿物溶液里，杯壁已结出白色晶粒","scene":"实验室里，技术员把一块兽骨浸入矿物溶液，说明自然状态下这一过程要几万年。 Fossilization begins when mineral-rich water replaces the bone's original tissue.","sceneCN":"这里 fossilization 指「生物遗体被矿物质替换而保存为化石的过程」（第 1 个义项：化石化的自然过程）；句意为富含矿物的水替换骨骼原有组织时，化石化就开始了。图中可辨识物件：浸泡的兽骨、矿物溶液、杯壁晶粒、标签牌。","pos":[{"tag":"n.","zh":"化石化（作用）；成为化石的状态；（语言、制度等的）僵化"}],"collocations":[{"phrase":"fossilization process","zh":"化石化过程"},{"phrase":"rapid fossilization","zh":"快速化石化"},{"phrase":"language fossilization","zh":"语言僵化"},{"phrase":"fossilization of ideas","zh":"观念的僵化"},{"phrase":"complete fossilization","zh":"完全化石化"},{"phrase":"fossilization rate","zh":"化石化速率"}],"forms":[{"label":"名词（过程）","form":"fossilization"},{"label":"名词复数（少见）","form":"fossilizations"},{"label":"相关动词","form":"fossilize"},{"label":"动词三单","form":"fossilizes"},{"label":"过去分词（形容词）","form":"fossilized"},{"label":"现在分词","form":"fossilizing"}],"derivatives":[{"word":"fossilize","pos":"v.","zh":"使成为化石；使僵化"},{"word":"fossilized","pos":"adj.","zh":"已成化石的；僵化的"},{"word":"fossil","pos":"n.","zh":"化石"},{"word":"fossiliferous","pos":"adj.","zh":"含化石的"},{"word":"petrified","pos":"adj.","zh":"石化的；僵住的"}],"senses":[{"no":"01","title":"The natural process of becoming stone","titleCN":"自然状态下成为化石的过程","definition":"the set of processes by which the remains of an organism are preserved in rock instead of decaying","definitionCN":"生物遗体未被分解、而被保存在岩石中的一系列过程","example":"Fossilization began when the carcass was buried before scavengers found it.","exampleCN":"化石化在食腐者找到之前尸体被埋住时就开始了。","why":"the -ization suffix marks a process, and palaeontology reserves it for the whole chain from burial to mineral replacement.","whyCN":"-ization 后缀标示过程，古生物学用它专指从埋藏到矿物替换的整条链。"},{"no":"02","title":"The state of being fossil","titleCN":"已成为化石的状态","definition":"the condition of a remain that has completed the change into stone","definitionCN":"遗体已完成向石头转变后的状态","example":"Complete fossilization leaves almost no original organic matter.","exampleCN":"完全化石化几乎不留下任何原有有机质。","why":"the noun can name a state as well as an activity, so samples are graded by how far fossilization has gone.","whyCN":"这个名词也能指状态而非活动，因此样品按化石化的程度分级。"},{"no":"03","title":"Mineral replacement","titleCN":"矿物替换作用","definition":"the specific step in which groundwater minerals replace the original tissue molecule by molecule","definitionCN":"地下水中的矿物逐分子替换原有组织的具体步骤","example":"Fossilization of this kind preserves the cell walls but not the colour.","exampleCN":"这一类化石化保留了细胞壁，却保不住颜色。","why":"chemists use the word for replacement rather than moulding, because the shape survives while the substance does not.","whyCN":"化学家用这个词指替换而非铸模，因为形体留存而物质不存。"},{"no":"04","title":"Preservation in the rock record","titleCN":"在岩石记录中的保存","definition":"the entry of a dead organism into the sedimentary record, where it becomes available to future discovery","definitionCN":"死亡生物进入沉积记录、可供日后发现的过程","example":"Only rapid burial allows fossilization in a river channel.","exampleCN":"在河道中，只有迅速埋藏才可能形成化石保存。","why":"taphonomy asks why so few organisms reach this stage, and treats fossilization as an exceptional outcome.","whyCN":"埋藏学追问为何极少数生物能走到这一步，并把化石化视为例外结果。"},{"no":"05","title":"Frozen interlanguage forms","titleCN":"语言学习中的僵化","definition":"the point in second-language learning where a learner's errors stop changing and become permanent","definitionCN":"第二语言学习中学习者的错误不再改变、固定下来的状态","example":"Fossilization set in once she stopped getting corrective feedback.","exampleCN":"她一旦不再得到纠正反馈，语言僵化就出现了。","why":"applied linguistics borrowed the geological image for habits that harden and will not be remodelled.","whyCN":"应用语言学借这个地质意象指硬化、不再重塑的习惯。"},{"no":"06","title":"A fixed phrase","titleCN":"固定下来的表达","definition":"an expression that has lost its productive pattern and survives as an unanalysed whole","definitionCN":"已失去能产模式、作为不可分析的整块存留的表达","example":"The greeting survives through fossilization; nobody builds new phrases on its model.","exampleCN":"这个问候语靠固定化存留，没人再按它的模式造新短语。","why":"linguistics calls an expression fossilized when speakers can no longer take it apart and rebuild it.","whyCN":"语言学把说话者已无法拆开重建的表达称为固定化的。"},{"no":"07","title":"Institutional rigidity","titleCN":"制度僵化","definition":"the hardening of an organization's rules until reform becomes almost impossible","definitionCN":"组织规则硬化到改革几乎无法进行的程度","example":"The board's fossilization was complete long before the merger.","exampleCN":"董事会的僵化在合并之前早就完成了。","why":"the metaphor attacks the loss of adaptiveness, not the age of the institution.","whyCN":"这个比喻批评的是适应力的丧失，而非机构的老迈。"},{"no":"08","title":"A hardened habit or attitude","titleCN":"习惯或态度的凝固","definition":"the fixing of a personal habit or attitude so that new evidence no longer alters it","definitionCN":"个人习惯或态度固定下来，新证据再也无法改变它","example":"Decades of praise had produced a gentle fossilization of his taste.","exampleCN":"数十年的赞誉使他的品味温和地凝固了。","why":"at the personal scale the word is almost neutral: comfort hardens into habit without any decision being made.","whyCN":"在个人尺度上这个词近乎中性：安逸在无人决定的情况下硬化成习惯。"}],"etymology":{"intro":{"en":"Fossilization is fossil plus -ization, from Latin fossilis 'dug up' and the suffix -izare of Greek origin. The geological sense is nineteenth-century, the linguistic one twentieth-century. Dates are approximate.","cn":"fossilization 由 fossil 加 -ization 构成，前者来自拉丁 fossilis「挖出的」，后者为源自希腊语的 -izare。地质义为十九世纪，语言学义为二十世纪。年代均为约数。"},"items":[{"era":"LATIN FOSSILIS","en":"Fossilis 'dug up' comes from fodere 'to dig'; early use covered anything taken from the ground, including minerals.","cn":"一般认为 fossilis「挖出的」来自 fodere「挖掘」；早期用法涵盖一切取自地下之物，包括矿物。"},{"era":"SUFFIX -IZATION","en":"The suffix enters English through French -isation and Latin -izare, itself borrowed from Greek verbs in -izein, and it names processes.","cn":"这个后缀经法语 -isation 与拉丁 -izare 进入英语，后者又借自希腊语 -izein 动词，用于命名过程。"},{"era":"GEOLOGICAL COINING","en":"Nineteenth-century geology needed a process noun, so fossilization was formed for the change of remains into stone.","cn":"十九世纪地质学需要一个过程名词，于是造出 fossilization 指遗体变为石头的变化。"},{"era":"TAPHONOMY","en":"Twentieth-century taphonomy made fossilization an outcome to be explained, and asked which conditions favour it.","cn":"二十世纪的埋藏学把化石化变成需要解释的结果，并追问哪些条件有利于它。"},{"era":"LINGUISTIC TRANSFER","en":"Applied linguistics of the later twentieth century borrowed the word for errors and phrases that harden into permanence.","cn":"二十世纪后期的应用语言学借这个词指硬化成永久状态的错误与短语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the morphology is certain, but the earliest English use of the geological noun is dated approximately.","cn":"来源不确定（仅首见年代）：词形是确定的，但这个地质名词在英语中的最早使用只能约略定年。"}]},"similar":{"note":{"en":"Group one separates fossilization from the words in its own family; group two separates it from other words for preservation and for fixedness.","cn":"第一组把 fossilization 与同族各词分开；第二组区分它与「保存」「固定」的其它说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fossil","ipa":"/ˈfɒsl/","tag":"same family, noun","definition":"The preserved object; fossilization is the process that produced it.","definitionCN":"指被保存的物件；fossilization 是造成它的过程。"},{"word":"fossilize","ipa":"/ˈfɒsəlaɪz/","tag":"same family, verb","definition":"The verb 'to become or make a fossil'; the noun is its action and result.","definitionCN":"动词「变成化石、使成化石」；名词是其动作与结果。"},{"word":"fossilized","ipa":"/ˈfɒsəlaɪzd/","tag":"same family, participle","definition":"The adjective describing what has already been turned to stone.","definitionCN":"形容已变成石头的状态。"},{"word":"petrification","ipa":"/ˌpetrɪfɪˈkeɪʃn/","tag":"different root","definition":"From Greek petra 'rock' plus facere; it stresses turning wholly to stone, one route within fossilization.","definitionCN":"来自希腊 petra「岩石」加 facere；强调完全变成石头，是化石化中的一条路径。"}]},{"heading":"NEAR MEANING","entries":[{"word":"preservation","ipa":"/ˌprezəˈveɪʃn/","tag":"kept from decay","definition":"Keeping remains from decaying by any means, including freezing or drying; fossilization is the rock route.","definitionCN":"以任何方式使遗体不腐，包括冷冻与干燥；化石化是其中的岩石路径。"},{"word":"embedding","ipa":"/ɪmˈbedɪŋ/","tag":"burial only","definition":"The act of burying something in sediment; it is the necessary first step, not the whole process.","definitionCN":"把某物埋入沉积物的动作，是必要的第一步，而非全过程。"},{"word":"fixation","ipa":"/fɪkˈseɪʃn/","tag":"making fixed","definition":"The general act of making something fixed, in chemistry, psychology or language; it lacks the stone image.","definitionCN":"化学、心理学或语言中使某物固定的通称，缺少岩石意象。"},{"word":"rigidity","ipa":"/rɪˈdʒɪdəti/","tag":"state, not process","definition":"The state of being unable to bend or change; fossilization names the process that reaches it.","definitionCN":"无法弯曲或改变的状态；fossilization 指达到它的过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"fossil + -ization: the making of a fossil, a process noun built on a process suffix.","cn":"fossil + -ization：造出化石，是过程后缀构成的过程名词。"},{"en":"The family runs fossil, fossilize, fossilized, fossiliferous, subfossilization.","cn":"同族词包括 fossil、fossilize、fossilized、fossiliferous、subfossilization。"},{"en":"Two fields share it: palaeontology for bone, applied linguistics for errors.","cn":"两个领域共用它：古生物学指骨骼，应用语言学指错误。"},{"en":"Fixed phrases: rapid fossilization, language fossilization, fossilization rate.","cn":"固定搭配：快速化石化、语言僵化、化石化速率。"},{"en":"Compare petrification, which names one mineral route rather than the whole chain.","cn":"比较 petrification，它指一条矿物路径，而非整条链。"}],"abstract":[{"en":"Picture a bone slowly swapped for stone while keeping its shape.","cn":"想象一块骨慢慢被石头换掉，形状却保留。"},{"en":"Picture a sentence a learner repeats so often that it stops being editable.","cn":"想象学习者反复说一句话，说到它再也改不动。"},{"en":"Picture a committee whose minutes have read the same for twenty years.","cn":"想象一个委员会的会议记录二十年一字未变。"}]},"examples":[{"en":"Fossilization is rare because most carcasses are scavenged or oxidized.","cn":"化石化罕见，因为多数尸体被食腐或氧化。"},{"en":"Her pronunciation showed fossilization after the first year abroad.","cn":"在国外第一年之后，她的发音就出现了僵化。"},{"en":"The treaty's fossilization became clear when no clause could be reopened.","cn":"当任何条款都无法重开时，条约的僵化就显而易见了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fossil（化石）+ ization（过程）」——变成化石的过程 → 化石化；引申为僵化","word":"fossilization"},"root":"拉丁 fossilis「挖出的」（fodere「挖」）+ 后缀 -ization（源自拉丁 -izare，再上溯希腊 -izein）。","sensesIntro":{"en":"Eight senses run from burial to stone, then borrow the same hardening for grammar, institutions and personal habits: what cannot be remodelled is, in this metaphor, already stone.","cn":"八个义项从埋藏走到成石，随后把同一种「变硬」借给语法、制度与个人习惯：在这套比喻里，无法重塑的东西都已是石头。"},"semanticMap":{"core":{"en":"CORE IMAGE: soft tissue replaced grain by grain until the shape is stone.","cn":"核心意象：软组织被一粒粒替换，直到形体成为石头。"},"chain":["BURIED FAST","OUT OF DECAY","MINERALS SWAP IN","ENTER THE ROCK","FREEZE IN PLACE","NO REMODELLING"],"branches":[{"senses":"S1 · S2","en":"PROCESS AND STATE: the same noun names the becoming and the finished condition.","cn":"过程与状态：同一名词兼指「成为」与「已成」。"},{"senses":"S3 · S4","en":"CHEMISTRY AND RECORD: replacement is the mechanism, the rock record the outcome.","cn":"化学与记录：替换是机制，岩石记录是结果。"},{"senses":"S5 · S6","en":"HARDENED LANGUAGE: errors and phrases both stop being remodelled.","cn":"硬化的语言：错误与短语都不再被重塑。"},{"senses":"S7","en":"INSTITUTIONAL RIGIDITY: rules harden until reform is impossible.","cn":"制度僵化：规则硬到改革无从下手。"},{"senses":"S8","en":"PERSONAL HABIT: comfort quietly becomes unchangeable.","cn":"个人习惯：安逸悄悄变得不可更改。"}]},"affixes":{"intro":{"en":"Fossilization is a Latin root plus a process suffix that English borrowed through French, so each part can be glossed separately.","cn":"fossilization 是拉丁词根加过程后缀，经法语进入英语，因此各部分可分别注释。"},"latinIntro":{"en":"Latin fossilis 'dug up' and the suffix -izatio, ultimately from Greek -izein, combine; the same suffix builds organization, civilization and standardization.","cn":"拉丁 fossilis「挖出的」与最终源自希腊 -izein 的后缀 -izatio 组合；同一后缀还构成 organization、civilization 与 standardization。"},"items":[{"word":"fossil","structure":"fossilis (Latin 'dug up')","meaning":"a preserved remain","meaningCN":"化石","example":"The fossil lay in soft shale.","exampleCN":"化石躺在软页岩中。"},{"word":"-ization","structure":"-izatio (Latin suffix of process, from Greek -izein)","meaning":"the making or becoming","meaningCN":"使……化；……的过程","example":"The suffix turns an adjective into a process noun.","exampleCN":"这个后缀把形容词变成过程名词。"},{"word":"fossilization","structure":"fossil + -ization","meaning":"the process of becoming a fossil","meaningCN":"化石化","example":"Fossilization needs quick burial.","exampleCN":"化石化需要迅速埋藏。"},{"word":"fossilize","structure":"fossil + -ize","meaning":"to turn into stone","meaningCN":"使成为化石","example":"Cold springs can fossilize leaves.","exampleCN":"冷泉能使叶子化石化。"},{"word":"fossilized","structure":"fossilize + -ed","meaning":"already turned to stone","meaningCN":"已成化石的","example":"Fossilized bone is heavy.","exampleCN":"化石化的骨骼很重。"},{"word":"fossiliferous","structure":"fossil + -ferous (bearing)","meaning":"yielding fossils","meaningCN":"含化石的","example":"The fossiliferous band is narrow.","exampleCN":"含化石的层带很窄。"},{"word":"fossil record","structure":"fossil + record (compound)","meaning":"the sum of preserved remains","meaningCN":"化石记录","example":"The fossil record is heavily biased.","exampleCN":"化石记录带有严重偏差。"},{"word":"petrification","structure":"Greek petra 'rock' + -fication","meaning":"turning wholly to stone","meaningCN":"完全石化","example":"Petrification preserved the grain.","exampleCN":"石化保住了木纹。"},{"word":"mineralization","structure":"mineral + -ization","meaning":"replacement by minerals","meaningCN":"矿化","example":"Mineralization precedes full fossilization.","exampleCN":"矿化先于完全化石化。"}],"latinEntries":[{"word":"fossilis","structure":"fossilis, fossile (adj., third declension)","meaning":"dug up","meaningCN":"被挖出的"},{"word":"fodere","structure":"fodere, fodi, fossum (verb, third conjugation)","meaning":"to dig","meaningCN":"挖掘"},{"word":"fossio","structure":"fossio, fossionis (f., third declension)","meaning":"a digging","meaningCN":"挖掘"},{"word":"fossa","structure":"fossa, fossae (f., first declension)","meaning":"a ditch","meaningCN":"沟；壕"}]}},{"word":"fossilize","ipa_uk":"/ˈfɒsəlaɪz/","ipa_us":"/ˈfɑːsəlaɪz/","definition_zh":"使成为化石；变成化石；使僵化、固定不变；使（语言表达）固定化","definition_en":"to turn an organism's remains into a fossil, or to make something fixed and unable to change","core_image":"地下水带着碳酸钙渗进贝壳，一点点把原来的壳换成石头","scene":"沙丘下的贝壳被细沙埋住，地下水带来碳酸钙，一点点把它替换成石头。 Mineral water can fossilize a shell within a few thousand years.","sceneCN":"这里 fossilize 指「使生物遗体经矿物替换而变成化石」（第 1 个义项：使遗体化石化）；句意为富含矿物的水能在数千年内使一枚贝壳变成化石。图中可辨识物件：埋住的贝壳、渗流的水、白色矿物脉、沙层。","pos":[{"tag":"vt.","zh":"使成为化石；使僵化、使固定不变"},{"tag":"vi.","zh":"变成化石；（习惯、制度）僵化定型"}],"collocations":[{"phrase":"fossilize a bone","zh":"使骨骼成为化石"},{"phrase":"fossilized remains","zh":"已化石化的遗骸"},{"phrase":"fossilize into stone","zh":"化石化成石头"},{"phrase":"fossilized expression","zh":"固定化的表达"},{"phrase":"fossilized error","zh":"僵化的错误"},{"phrase":"fossilize a habit","zh":"使习惯固定下来"}],"forms":[{"label":"动词原形","form":"fossilize"},{"label":"三单（he/she/it）","form":"fossilizes"},{"label":"过去式","form":"fossilized"},{"label":"过去分词","form":"fossilized"},{"label":"现在分词","form":"fossilizing"},{"label":"名词（过程）","form":"fossilization"}],"derivatives":[{"word":"fossil","pos":"n.","zh":"化石"},{"word":"fossilization","pos":"n.","zh":"化石化；僵化"},{"word":"fossilized","pos":"adj.","zh":"已成化石的；僵化的"},{"word":"fossiliferous","pos":"adj.","zh":"含化石的"},{"word":"subfossil","pos":"n.","zh":"亚化石"}],"senses":[{"no":"01","title":"Turn remains into a fossil","titleCN":"使遗体变成化石","definition":"to preserve the remains of an organism in rock by burial and mineral replacement","definitionCN":"通过埋藏与矿物替换把生物遗体保存在岩石中","example":"Mineral water can fossilize a shell within a few thousand years.","exampleCN":"富含矿物的水能在数千年内使一枚贝壳变成化石。","why":"the verb is the causative of the process: an agent, here mineral-charged water, makes the remain become stone.","whyCN":"这个动词是过程的使役式：某个营力（此处为含矿的水）使遗体变成石头。"},{"no":"02","title":"Become a fossil","titleCN":"变成化石","definition":"to pass into the fossil state without an external agent being named","definitionCN":"在未指明外力的情况下进入化石状态","example":"Only the hard parts fossilize under ordinary conditions.","exampleCN":"在普通条件下只有坚硬部分会变成化石。","why":"used intransitively, the verb shifts attention from the cause to the material that survives.","whyCN":"作不及物用时，动词把注意力从原因转到得以留存的材料上。"},{"no":"03","title":"Make rigid and unchangeable","titleCN":"使僵化、固定不变","definition":"to fix an attitude, rule or practice so firmly that it can no longer be revised","definitionCN":"把态度、规则或做法固定到无法再修改的程度","example":"Fear of change had fossilized the department's procedures.","exampleCN":"对改变的恐惧使该部门的程序僵化了。","why":"the metaphor is blunt: what has fossilized keeps its shape precisely because it has stopped living.","whyCN":"这个比喻很直白：已化石化的东西之所以保持形状，正因为它已停止生长。"},{"no":"04","title":"Fix an expression","titleCN":"使语言表达固定化","definition":"to make a phrase permanent and unanalysable, so that speakers repeat it whole","definitionCN":"使一个短语永久化、不可分析，说话者只能整块重复","example":"Repeated in court for centuries, the formula fossilized.","exampleCN":"这套套语在法庭上重复了数百年，终于固定下来。","why":"linguistics uses the verb for the loss of productivity: the phrase survives, but its pattern no longer builds new forms.","whyCN":"语言学用这个动词指能产性的丧失：短语存活，但其模式不再造新形式。"},{"no":"05","title":"Harden a learner's error","titleCN":"使学习者的错误僵化定型","definition":"to make a second-language error permanent because it is never corrected or noticed","definitionCN":"因错误从未被纠正或注意而使其永久化","example":"Praise without correction fossilized his word order.","exampleCN":"只表扬不纠正，使他的语序错误固化下来。","why":"applied linguistics borrowed the geological verb to describe habits that set like stone.","whyCN":"应用语言学借这个地质动词来描述像石头一样定型的习惯。"},{"no":"06","title":"Freeze at a stage","titleCN":"使停留在某一阶段","definition":"to stop a process of development at an early stage and keep it there","definitionCN":"使发展过程停在较早阶段并不再前进","example":"The project fossilized at the planning stage.","exampleCN":"这个项目停在规划阶段，再未前进。","why":"the word names the arrest itself, not the reason, which makes it useful in management writing.","whyCN":"这个词命名的是停滞本身，而非原因，因此在管理写作中很有用。"},{"no":"07","title":"Turn into an outdated relic","titleCN":"使成为过时的遗存","definition":"to reduce something to a relic that survives after its function has gone","definitionCN":"使某物沦为功能消失后仍在的遗存","example":"Paper tickets have been fossilized by the app.","exampleCN":"手机应用使纸质车票成了遗存。","why":"this sense is close to sense three but adds a verdict: the thing survives, and that survival is the problem.","whyCN":"这一义与第三义接近，但增添了评判：东西还在，而它的留存本身就是问题。"},{"no":"08","title":"Make feelings rigid","titleCN":"使情感或态度凝固","definition":"to harden an emotion or pose until it looks like part of the personality","definitionCN":"使某种情绪或姿态硬化，看上去成了性格的一部分","example":"Years of ceremony had fossilized his grief into a pose.","exampleCN":"多年的仪式把他的悲伤凝固成一种姿态。","why":"the most abstract use treats inner life as sediment: feeling settles, compacts and stops moving.","whyCN":"最抽象的用法把内心生活当作沉积物：情感沉降、压实、不再移动。"}],"etymology":{"intro":{"en":"Fossilize joins fossil, from Latin fossilis 'dug up', to the verb suffix -ize, from Greek -izein through Latin -izare. The geological verb is nineteenth-century; the figurative uses followed. Dates are approximate.","cn":"fossilize 由 fossil（来自拉丁 fossilis「挖出的」）加动词后缀 -ize（经拉丁 -izare 上溯希腊 -izein）构成。地质动词义为十九世纪，比喻义随后出现。年代均为约数。"},"items":[{"era":"LATIN FOSSILIS","en":"Fossilis 'dug up' derives from fodere 'to dig'; early scientific Latin used it for anything taken from the ground.","cn":"fossilis「挖出的」源自 fodere「挖掘」；早期科学拉丁语用它指一切取自地下之物。"},{"era":"SUFFIX -IZE","en":"The suffix comes from Greek -izein through Latin -izare and French -iser, and typically makes verbs of causing or becoming.","cn":"这个后缀经拉丁 -izare 与法语 -iser 来自希腊 -izein，通常构成「使……」或「成为……」的动词。"},{"era":"GEOLOGICAL COINING","en":"Nineteenth-century geology formed fossilize for the change of organic remains into stone, alongside the noun fossilization.","cn":"十九世纪地质学造出 fossilize 指有机遗体变为石头，并与名词 fossilization 并行。"},{"era":"FIGURATIVE EXTENSION","en":"The same century applied the verb to ideas and institutions that had stopped developing.","cn":"同一世纪把这个动词用于停止发展的观念与制度。"},{"era":"APPLIED LINGUISTICS","en":"Twentieth-century language teaching took the verb for errors and phrases that become permanent.","cn":"二十世纪的语言教学用这个动词指变得永久的错误与短语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the derivation is clear, but the earliest recorded figurative use is dated only approximately.","cn":"来源不确定（仅首见年代）：派生关系清楚，但最早的比喻用法书证只能约略定年。"}]},"similar":{"note":{"en":"Group one separates fossilize from its own family and from look-alikes; group two separates it from other verbs of hardening and preserving.","cn":"第一组把 fossilize 与同族及形近词分开；第二组区分它与其它表「变硬」「保存」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fossil","ipa":"/ˈfɒsl/","tag":"same family, noun","definition":"The resulting object; fossilize names the change that produces it.","definitionCN":"指结果物；fossilize 指产生它的变化。"},{"word":"fossilization","ipa":"/ˌfɒsəlaɪˈzeɪʃn/","tag":"same family, noun","definition":"The process noun; the verb and the noun differ only in grammatical role.","definitionCN":"过程名词；动词与名词只差语法角色。"},{"word":"fossilized","ipa":"/ˈfɒsəlaɪzd/","tag":"same family, participle","definition":"The participle used as an adjective for what has already set.","definitionCN":"分词作形容词，指已经定型的。"},{"word":"fertilize","ipa":"/ˈfɜːtəlaɪz/","tag":"different root","definition":"From Latin fertilis 'fruitful', built on ferre 'to bear'; the -ilize ending is the only resemblance.","definitionCN":"来自拉丁 fertilis「多产的」，源于 ferre「承载」；只有 -ilize 词尾相似。"}]},{"heading":"NEAR MEANING","entries":[{"word":"petrify","ipa":"/ˈpetrɪfaɪ/","tag":"turn to stone","definition":"From Greek petra 'rock': to make literally stone, or to paralyse with fear; it stresses the material change.","definitionCN":"来自希腊 petra「岩石」：使真的变成石头，或吓得呆住；强调材质变化。"},{"word":"harden","ipa":"/ˈhɑːdn/","tag":"general stiffening","definition":"To make firm or unyielding, of clay, attitudes or arteries; it carries no image of deep time.","definitionCN":"使变硬或不让步，可用于黏土、态度或血管；不含深时间意象。"},{"word":"ossify","ipa":"/ˈɒsɪfaɪ/","tag":"bone, then habit","definition":"From Latin os 'bone': to turn into bone, and by extension to become rigid in habit or organization.","definitionCN":"来自拉丁 os「骨」：变成骨，引申为习惯或组织僵化。"},{"word":"preserve","ipa":"/prɪˈzɜːv/","tag":"keep from harm","definition":"To keep something safe from decay; it does not imply replacement by stone.","definitionCN":"使某物免于腐坏；不含被石头替换之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"fossil + -ize 'to make or become': to make into a fossil.","cn":"fossil + -ize「使……、成为……」：使成为化石。"},{"en":"The family runs fossil, fossilize, fossilization, fossilized, fossiliferous.","cn":"同族词包括 fossil、fossilize、fossilization、fossilized、fossiliferous。"},{"en":"Two directions of meaning: stone by minerals, or rigidity by habit.","cn":"两条意义方向：靠矿物成石，或靠习惯变硬。"},{"en":"Fixed phrases: fossilized remains, fossilized expression, fossilized error.","cn":"固定搭配：化石化的遗骸、固定化的表达、僵化的错误。"},{"en":"Compare petrify and ossify: both also move from stone or bone to rigid habit.","cn":"比较 petrify 与 ossify：两者也都从石或骨转到僵化的习惯。"}],"abstract":[{"en":"Picture a shell being refilled with white mineral, cell by cell.","cn":"想象一枚贝壳被白色矿物一格一格填满。"},{"en":"Picture a phrase worn smooth by repetition until no one can take it apart.","cn":"想象一句话被重复磨滑，谁也拆不开它。"},{"en":"Picture a face that keeps one expression so long that it becomes the face.","cn":"想象一张脸长期保持一种表情，最后成了那张脸本身。"}]},"examples":[{"en":"Rapid burial is what allows soft tissue to fossilize at all.","cn":"正因迅速埋藏，软组织才有可能化石化。"},{"en":"The cliché has fossilized into a greeting nobody analyses.","cn":"这句套话已固定成一个无人分析的问候语。"},{"en":"Aging institutions fossilize when criticism stops reaching them.","cn":"当批评无法再传进去时，老机构就僵化了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fossil（化石）+ ize（使……）」——使变成化石 → 化石化；引申为使僵化","word":"fossilize"},"root":"拉丁 fossilis「挖出的」（fodere「挖掘」）+ 动词后缀 -ize（经拉丁 -izare，上溯希腊 -izein）。","sensesIntro":{"en":"Eight senses split into two directions from one verb: the geological one turns remains to stone, the figurative one turns living things, phrases and feelings into something that can no longer change.","cn":"八个义项从同一个动词分出两条方向：地质方向把遗体变成石头，比喻方向把活物、短语与情感变成再也不能改变的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: something once soft refilled with mineral until the shape alone remains.","cn":"核心意象：曾经柔软的东西被矿物填满，只剩形状留在那里。"},"chain":["REMAINS BURIED","MINERALS FILL","TISSUE TO STONE","SHAPE WITHOUT CHANGE","PHRASE FROZEN","FEELING SET"],"branches":[{"senses":"S1 · S2","en":"TWO GRAMMAR SIDES: the same change seen as caused and as undergone.","cn":"两个语法侧面：同一变化，一为致使，一为自身发生。"},{"senses":"S3 · S7","en":"RIGIDITY AS VERDICT: what cannot be revised is first inert, then obsolete.","cn":"僵化即评判：改不动的东西先是惰性，随后变成过时。"},{"senses":"S4 · S5","en":"HARDENED LANGUAGE: fixed phrases and uncorrected errors set the same way.","cn":"硬化的语言：固定短语与未被纠正的错误以同样方式定型。"},{"senses":"S6","en":"ARRESTED DEVELOPMENT: a process stops and keeps its early shape.","cn":"停滞的发展：一个过程停住，保留早期的形状。"},{"senses":"S8","en":"INNER LIFE SET: feeling compacts into a pose.","cn":"内心定形：情感压实成一种姿态。"}]},"affixes":{"intro":{"en":"Fossilize is a Latin-derived noun plus a borrowed verb suffix, and both parts recur in hundreds of English words.","cn":"fossilize 是拉丁来源的名词加借入的动词后缀，两部分在英语中反复出现。"},"latinIntro":{"en":"Latin fossilis 'dug up' and Greek-derived -izein, through Latin -izare and French -iser, supply the meaning; latinEntries records the Latin source words only.","cn":"拉丁 fossilis「挖出的」与源自希腊 -izein（经拉丁 -izare、法语 -iser）的后缀提供词义；latinEntries 只记录拉丁来源词。"},"items":[{"word":"fossil","structure":"fossilis (Latin adjective 'dug up')","meaning":"a preserved remain","meaningCN":"化石","example":"The fossil split cleanly.","exampleCN":"这块化石裂得很整齐。"},{"word":"-ize","structure":"-izein (Greek verb suffix) via -izare/-iser","meaning":"to make or become","meaningCN":"使……；成为……","example":"The suffix turns nouns into verbs of change.","exampleCN":"这个后缀把名词变成表变化的动词。"},{"word":"fossilize","structure":"fossil + -ize","meaning":"to make or become a fossil","meaningCN":"使成为化石；变成化石","example":"Cold water can fossilize bone.","exampleCN":"冷水能使骨骼化石化。"},{"word":"fossilized","structure":"fossilize + -ed (past participle)","meaning":"already turned to stone","meaningCN":"已成化石的","example":"Fossilized wood keeps its rings.","exampleCN":"化石木保留年轮。"},{"word":"fossilization","structure":"fossilize + -ation (process noun)","meaning":"the process of becoming stone","meaningCN":"化石化过程","example":"Fossilization needs burial.","exampleCN":"化石化需要埋藏。"},{"word":"fossiliferous","structure":"fossil + -ferous (bearing)","meaning":"yielding fossils","meaningCN":"含化石的","example":"The fossiliferous bed is thin.","exampleCN":"含化石的层很薄。"},{"word":"fossil record","structure":"fossil + record (compound)","meaning":"the total of preserved remains","meaningCN":"化石记录","example":"The fossil record is patchy.","exampleCN":"化石记录并不连续。"},{"word":"subfossil","structure":"sub- (partly) + fossil","meaning":"a partly fossilised remain","meaningCN":"亚化石","example":"Subfossil shells are common in caves.","exampleCN":"亚化石贝壳在洞穴中常见。"},{"word":"fossil fuel","structure":"fossil + fuel (compound)","meaning":"fuel from ancient organic matter","meaningCN":"化石燃料","example":"Fossil fuel burning adds carbon.","exampleCN":"燃烧化石燃料增加碳。"}],"latinEntries":[{"word":"fossilis","structure":"fossilis, fossile (adj., third declension)","meaning":"dug up","meaningCN":"被挖出的"},{"word":"fodere","structure":"fodere, fodi, fossum (verb, third conjugation)","meaning":"to dig","meaningCN":"挖掘"},{"word":"fossa","structure":"fossa, fossae (f., first declension)","meaning":"a ditch","meaningCN":"沟；壕"},{"word":"fossor","structure":"fossor, fossoris (m., third declension)","meaning":"a digger","meaningCN":"挖掘者"}]}},{"word":"paleontology","ipa_uk":"/ˌpeɪliənˈtɒlədʒi/","ipa_us":"/ˌpeɪliənˈtɑːlədʒi/","definition_zh":"古生物学；古生物研究；以化石研究远古生命的学科实践","definition_en":"the scientific study of ancient life through fossils, or the work and institutions devoted to it","core_image":"库房里，软刷清掉化石周围的砂岩，骨骼的轮廓一点点露出来","scene":"博物馆库房里，研究员用软刷清掉化石周围的砂岩，再量出骨骼的长度。 Paleontology often begins with a soft brush and a ruler rather than a hammer.","sceneCN":"这里 paleontology 指「古生物学这一学科及其研究实践」（第 1 个义项：以化石研究远古生命的学科）；句意为古生物学常常是从一把软刷和一把尺子开始，而不是从锤子开始。图中可辨识物件：软刷、砂岩、骨骼轮廓、卷尺、标本盒。","pos":[{"tag":"n.","zh":"古生物学；古生物研究（不可数）"}],"collocations":[{"phrase":"vertebrate paleontology","zh":"脊椎动物古生物学"},{"phrase":"invertebrate paleontology","zh":"无脊椎动物古生物学"},{"phrase":"paleontology collection","zh":"古生物藏品"},{"phrase":"museum of paleontology","zh":"古生物博物馆"},{"phrase":"field paleontology","zh":"野外古生物学"},{"phrase":"paleontology department","zh":"古生物系"}],"forms":[{"label":"名词（学科名，不可数）","form":"paleontology"},{"label":"英式拼写变体","form":"palaeontology"},{"label":"形容词","form":"paleontological"},{"label":"从业者名词","form":"paleontologist"},{"label":"相关学科","form":"paleobiology"}],"derivatives":[{"word":"paleontologist","pos":"n.","zh":"古生物学家"},{"word":"paleontological","pos":"adj.","zh":"古生物学的"},{"word":"paleobiology","pos":"n.","zh":"古生物学（偏生物学取向）"},{"word":"paleoanthropology","pos":"n.","zh":"古人类学"},{"word":"paleobotany","pos":"n.","zh":"古植物学"}],"senses":[{"no":"01","title":"The discipline itself","titleCN":"学科名：古生物学","definition":"the branch of science that studies ancient organisms through their fossil remains","definitionCN":"通过化石遗存研究远古生物的科学分支","example":"Paleontology sits between biology and geology and belongs fully to neither.","exampleCN":"古生物学处在生物学与地质学之间，并不完全属于任何一方。","why":"the name is built from Greek 'old' plus 'beings' plus 'study', so it names a field defined by its object rather than its method.","whyCN":"这个名称由希腊语「古老」「存在者」「研究」构成，因此它命名的是以对象而非方法界定的领域。"},{"no":"02","title":"The practice of studying fossils","titleCN":"研究化石的实际工作","definition":"the day-to-day work of excavating, preparing, measuring and interpreting fossil material","definitionCN":"发掘、修整、测量与解释化石材料的日常工作","example":"Paleontology in the field means long hours of sieving and labelling.","exampleCN":"野外的古生物学意味着长时间筛洗与贴标签。","why":"the same noun names the activity as well as the discipline, so a museum can say that paleontology is underway in its basement.","whyCN":"同一名词既指学科也指活动，因此博物馆可以说地下室正在进行古生物研究。"},{"no":"03","title":"A university subject","titleCN":"大学专业与课程","definition":"a course of study or degree programme that trains students in fossil analysis","definitionCN":"训练学生分析化石的课程或学位项目","example":"She took paleontology as her major after a summer of fieldwork.","exampleCN":"一个夏天的野外工作之后，她把古生物学选为专业。","why":"institutional usage treats the field as a teachable curriculum with its own prerequisites.","whyCN":"机构用法把这个领域当作有自身先修要求的可教课程。"},{"no":"04","title":"A museum department","titleCN":"博物馆的古生物部门","definition":"the unit of a museum or institute that holds, prepares and researches fossil collections","definitionCN":"博物馆或研究所中收藏、修整与研究化石的部门","example":"The paleontology department lent the skull for the exhibition.","exampleCN":"古生物部门把这具头骨借给了展览。","why":"the word shifts from knowledge to the building and staff that produce it, a common institutional metonymy.","whyCN":"这个词从知识转到生产知识的建筑与人员，是常见的机构转喻。"},{"no":"05","title":"Inference from fossil evidence","titleCN":"依据化石推断的方法","definition":"the method of reconstructing ancient life and environments from fossil evidence alone","definitionCN":"仅凭化石证据重建远古生命与环境的方法","example":"Paleontology must infer behaviour from bones that cannot move.","exampleCN":"古生物学只能从不能动的骨骼推断行为。","why":"the sense stresses the inference, because the objects of study no longer exist as living things.","whyCN":"这一义强调推断，因为研究对象已不再作为活物存在。"},{"no":"06","title":"Fossils as dating tools","titleCN":"用化石定年的应用","definition":"the use of fossil species to establish the relative age of rock layers","definitionCN":"利用化石物种确定岩层相对年代的做法","example":"Paleontology supplies the index fossils that stratigraphers rely on.","exampleCN":"古生物学提供地层学家所依赖的标志化石。","why":"biostratigraphy is where the field most directly serves geology, turning fossils into clocks.","whyCN":"生物地层学是这个领域最直接服务地质学之处，把化石变成钟表。"},{"no":"07","title":"Public and amateur study","titleCN":"科普与业余研究","definition":"the study of fossils by interested non-specialists, in clubs, museums and online communities","definitionCN":"有兴趣的非专业者在社团、博物馆与网络社群中研究化石","example":"Amateur paleontology has found some of the best specimens in the collection.","exampleCN":"业余古生物研究为馆藏贡献了若干最好的标本。","why":"the noun does not require a degree, so collecting clubs legitimately practise paleontology at a small scale.","whyCN":"这个名词并不要求学位，因此收藏社团在小规模上也在从事古生物学。"},{"no":"08","title":"A named subfield","titleCN":"命名的分支学科","definition":"one of the specialized branches, such as vertebrate or invertebrate paleontology","definitionCN":"专门化分支之一，如脊椎动物或无脊椎动物古生物学","example":"Vertebrate paleontology grew around the first complete skeletons.","exampleCN":"脊椎动物古生物学围绕最早的一批完整骨架发展起来。","why":"branches are named by adding the group studied, so paleontology functions as a head word in compounds.","whyCN":"分支通过加上所研究的类群来命名，因此 paleontology 在复合词中充当中心词。"}],"etymology":{"intro":{"en":"Paleontology was coined in the early nineteenth century from Greek palaios 'old', onta 'beings' and -logia 'study'. The British spelling palaeontology keeps the digraph. Dates are approximate.","cn":"paleontology 于十九世纪初由希腊 palaios「古老」、onta「存在者」与 -logia「研究」构成。英式拼写 palaeontology 保留二合元音。年代均为约数。"},"items":[{"era":"GREEK PALAIOS","en":"Palaios meant 'old, ancient', and it opens a large family of scientific words about the distant past.","cn":"一般认为 palaios 意为「古老的」，它开启了一大批关于远古的科学词。"},{"era":"GREEK ONTA","en":"Onta is the neuter plural of on 'being', so the middle element literally means 'existing things'.","cn":"onta 是 on「存在者」的中性复数，因此中间成分字面意为「存在的事物」。"},{"era":"GREEK -LOGIA","en":"-logia 'the study of' comes from logos 'word, account, reason' and names disciplines from biology to geology.","cn":"-logia「对……的研究」来自 logos「言说、道理」，用于命名从生物学到地质学的学科。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"French zoologists of the early nineteenth century assembled the three elements to name the study of extinct organisms.","cn":"十九世纪初的法国动物学家把这三个成分组合起来，命名对已灭绝生物的研究。"},{"era":"SPELLING SPLIT","en":"British usage keeps palaeo-, American usage prefers paleo-, and both refer to the same field.","cn":"英式用法保留 palaeo-，美式用法多用 paleo-，两者指同一领域。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the Greek elements are certain, but the exact year and author of the coinage are disputed.","cn":"来源不确定（仅首见年代）：希腊成分确定，但造词的确切年份与作者尚有争议。"}]},"similar":{"note":{"en":"Group one separates paleontology from its spelling variants and derived names; group two separates it from neighbouring disciplines.","cn":"第一组把 paleontology 与拼写变体及派生名称分开；第二组区分它与相邻学科。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"palaeontology","ipa":"/ˌpæliənˈtɒlədʒi/","tag":"same word, British spelling","definition":"The same discipline written with the digraph ae, standard in British and Commonwealth usage.","definitionCN":"同一学科，用二合元音 ae 拼写，通行于英国与英联邦。"},{"word":"paleontologist","ipa":"/ˌpeɪlaɪˈnɒlədʒɪst/","tag":"same family, person","definition":"The practitioner; the discipline and its worker differ only by the agent suffix.","definitionCN":"从业者；学科与其从业者只差一个施事后缀。"},{"word":"paleoanthropology","ipa":"/ˌpeɪliəʊænˈθrɒpələdʒi/","tag":"same prefix, other object","definition":"Paleo- plus anthropology: the study of ancient humans specifically, a subfield rather than a synonym.","definitionCN":"paleo- 加 anthropology：专门研究远古人类，是分支而非同义词。"},{"word":"paleogeography","ipa":"/ˌpeɪliəʊdʒiˈɒɡrəfi/","tag":"same prefix, other object","definition":"Paleo- plus geography: the mapping of ancient land and sea, which uses fossils but is not the study of life.","definitionCN":"paleo- 加 geography：重建古代陆海分布，会用到化石，但不研究生命本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"study of the earth","definition":"The study of rocks, structures and earth history; paleontology borrows its methods but asks about organisms.","definitionCN":"研究岩石、构造与地球历史；古生物学借其方法，但追问的是生物。"},{"word":"archaeology","ipa":"/ɑːˈkiːələdʒi/","tag":"study of human remains","definition":"The study of past human societies through their material traces; it deals with people, not deep time.","definitionCN":"通过物质遗存研究过去人类社会；对象是人，而非深时间。"},{"word":"biology","ipa":"/baɪˈɒlədʒi/","tag":"study of living things","definition":"The study of living organisms and their processes; paleontology applies biological questions to extinct forms.","definitionCN":"研究活体生物及其过程；古生物学把生物学问题应用于已灭绝的形态。"},{"word":"stratigraphy","ipa":"/strəˈtɪɡrəfi/","tag":"study of layers","definition":"The study of rock sequences and their order; it supplies the time frame in which fossils are placed.","definitionCN":"研究岩层序列与次序；它为化石提供时间框架。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek palaios 'old' + onta 'beings' + -logia 'study': the study of ancient beings.","cn":"希腊 palaios「古老」+ onta「存在者」+ -logia「研究」：对远古存在者的研究。"},{"en":"The family runs paleontology, paleontologist, paleontological, paleobiology, paleoanthropology.","cn":"同族词包括 paleontology、paleontologist、paleontological、paleobiology、paleoanthropology。"},{"en":"Spelling: British palaeo-, American paleo-, same field.","cn":"拼写：英式 palaeo-，美式 paleo-，同一领域。"},{"en":"Fixed phrases: vertebrate paleontology, paleontology collection, paleontology department.","cn":"固定搭配：脊椎动物古生物学、古生物藏品、古生物系。"},{"en":"Keep it apart from archaeology, which studies people rather than extinct life.","cn":"与 archaeology 分开，后者研究人，而非已灭绝的生命。"}],"abstract":[{"en":"Picture a brush moving sand grain by grain off a rib.","cn":"想象刷子一粒一粒把沙从肋骨上拨开。"},{"en":"Picture a bone that can no longer move but still tells how it moved.","cn":"想象一块再也不能动的骨头，却仍能说明它曾如何运动。"},{"en":"Picture a library where every book is a stone page written by a dead animal.","cn":"想象一座图书馆，每本书都是一页由死去的动物写成的石头。"}]},"examples":[{"en":"Paleontology depends on comparative anatomy more than on chemistry.","cn":"古生物学更依赖比较解剖学，而非化学。"},{"en":"The paleontology collection holds over forty thousand specimens.","cn":"该古生物藏品超过四万件标本。"},{"en":"Field paleontology begins with recording where every fragment came from.","cn":"野外古生物学从记录每一块碎片的出处开始。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「paleo（古老）+ onto（存在者）+ logy（学问）」——研究古老生命的学问 → 古生物学","word":"paleontology"},"root":"希腊 palaios「古老」+ onta「存在者」（on 的中性复数）+ -logia「研究」；十九世纪初法国动物学造词。","sensesIntro":{"en":"Eight senses move from the discipline to its daily work, its teaching, its museum home, its inference, its dating service, its amateur wing and its named branches.","cn":"八个义项从学科本身走到日常工作、教学、博物馆归属、推断方法、定年服务、业余一翼与命名的各分支。"},"semanticMap":{"core":{"en":"CORE IMAGE: a brush, a ruler and a label, applied to a bone that will never move again.","cn":"核心意象：软刷、尺子与标签，用在一块再也不会动的骨头上。"},"chain":["ANCIENT BEINGS","STUDY THEM","DIG AND PREPARE","TEACH AND HOUSE","INFER FROM STONE","DATE THE ROCK"],"branches":[{"senses":"S1 · S02","en":"DISCIPLINE AND WORK: the noun covers both the field and the labour inside it.","cn":"学科与工作：这个名词兼指领域与其内部的劳作。"},{"senses":"S3 · S4","en":"INSTITUTIONS: a major and a museum department are the field made teachable and housed.","cn":"机构：专业与博物馆部门，是学科变得可教、可存放的形态。"},{"senses":"S5 · S6","en":"METHOD AND SERVICE: inference about life, and dating for geology.","cn":"方法与服务：对生命的推断，以及对地质学的定年。"},{"senses":"S7","en":"AMATEUR WING: the field does not require a degree to be practised.","cn":"业余一翼：从事这一领域并不需要学位。"},{"senses":"S8","en":"NAMED BRANCHES: the head word builds subfields by adding the group studied.","cn":"命名的分支：中心词通过加上所研究的类群构成分支。"}]},"affixes":{"intro":{"en":"Paleontology is a three-part Greek compound, and each element still works in dozens of scientific words.","cn":"paleontology 是三段式希腊复合词，每个成分仍在数十个科学词中运作。"},"latinIntro":{"en":"Greek palaios 'old', onta 'beings' and -logia 'study' combine; the same -logia builds geology, biology and archaeology.","cn":"希腊 palaios「古老」、onta「存在者」与 -logia「研究」组合；同一 -logia 还构成 geology、biology 与 archaeology。"},"items":[{"word":"paleo-","structure":"palaios (Greek adjective 'old, ancient')","meaning":"old, ancient","meaningCN":"古老的","example":"The prefix marks distance in time.","exampleCN":"这个前缀标出时间上的遥远。"},{"word":"-ont","structure":"on, ontos (Greek 'being'); onta (neuter plural)","meaning":"being; beings","meaningCN":"存在者；诸存在者","example":"The element names what is studied, not how.","exampleCN":"这个成分命名研究对象，而非方法。"},{"word":"-logy","structure":"-logia (Greek 'study, account')","meaning":"the study of","meaningCN":"对……的研究","example":"Biology and geology share the same suffix.","exampleCN":"生物学与地质学共用同一后缀。"},{"word":"paleontology","structure":"paleo- + -ont- + -logy","meaning":"study of ancient life","meaningCN":"古生物学","example":"Paleontology began with fossil shells.","exampleCN":"古生物学从化石贝壳开始。"},{"word":"paleontologist","structure":"paleontology + -ist (person)","meaning":"one who studies ancient life","meaningCN":"古生物学家","example":"The paleontologist mapped the quarry.","exampleCN":"古生物学家测绘了采坑。"},{"word":"paleontological","structure":"paleontology + -ical (relating to)","meaning":"of the study of ancient life","meaningCN":"古生物学的","example":"Paleontological evidence is indirect.","exampleCN":"古生物学证据是间接的。"},{"word":"paleobiology","structure":"paleo- + biology","meaning":"biology of extinct organisms","meaningCN":"古生物学（生物学取向）","example":"Paleobiology asks how the animal lived.","exampleCN":"古生物学追问这动物如何生活。"},{"word":"paleoanthropology","structure":"paleo- + anthropology","meaning":"study of ancient humans","meaningCN":"古人类学","example":"Paleoanthropology tracks early hominins.","exampleCN":"古人类学追踪早期人科。"},{"word":"paleogeography","structure":"paleo- + geography","meaning":"ancient land and sea","meaningCN":"古地理学","example":"Paleogeography reconstructs old coastlines.","exampleCN":"古地理学重建古海岸线。"}],"latinEntries":[{"word":"palaios","structure":"palaios, palaia, palaion (Greek adj.)","meaning":"old, ancient","meaningCN":"古老的"},{"word":"on","structure":"on, ontos (Greek n., neuter)","meaning":"being, thing","meaningCN":"存在者；物"},{"word":"logia","structure":"logia (Greek n., from logos)","meaning":"study, account","meaningCN":"研究；论述"},{"word":"ontos","structure":"ontos (Greek genitive of on)","meaning":"of a being","meaningCN":"存在者的"}]}},{"word":"paleontologist","ipa_uk":"/ˌpeɪliənˈtɒlədʒɪst/","ipa_us":"/ˌpeɪliənˈtɑːlədʒɪst/","definition_zh":"古生物学家；从事化石发掘与研究者；博物馆古生物部门的研究或策展人员","definition_en":"a person who studies ancient life through fossils, whether in the field, a museum or a laboratory","core_image":"野外营地里，研究者蹲在碎石堆前，用镊子夹起一颗牙齿化石放进编号袋","scene":"野外营地里，一位研究者蹲在碎石堆中，用镊子夹起一颗牙齿化石放进编号袋。 The paleontologist brushed sand from a tooth before it could crack.","sceneCN":"这里 paleontologist 指「从事古生物研究的专业人员」（第 1 个义项：以化石研究远古生命的学者）；句意为这位古生物学家在一颗牙齿开裂之前把沙刷掉。图中可辨识物件：碎石堆、镊子、牙齿化石、编号袋、记录本。","pos":[{"tag":"n.","zh":"古生物学家；古生物研究者；古生物部门的研究或策展人员"}],"collocations":[{"phrase":"field paleontologist","zh":"野外古生物学家"},{"phrase":"vertebrate paleontologist","zh":"脊椎动物古生物学家"},{"phrase":"museum paleontologist","zh":"博物馆古生物学家"},{"phrase":"amateur paleontologist","zh":"业余古生物研究者"},{"phrase":"paleontologist's hammer","zh":"古生物学家用的地质锤"},{"phrase":"team of paleontologists","zh":"古生物学家团队"}],"forms":[{"label":"名词单数","form":"paleontologist"},{"label":"名词复数","form":"paleontologists"},{"label":"英式拼写变体","form":"palaeontologist"},{"label":"学科名","form":"paleontology"},{"label":"形容词","form":"paleontological"}],"derivatives":[{"word":"paleontology","pos":"n.","zh":"古生物学"},{"word":"paleontological","pos":"adj.","zh":"古生物学的"},{"word":"paleoanthropologist","pos":"n.","zh":"古人类学家"},{"word":"paleobotanist","pos":"n.","zh":"古植物学家"},{"word":"paleozoologist","pos":"n.","zh":"古动物学家"}],"senses":[{"no":"01","title":"A specialist in ancient life","titleCN":"研究远古生命的专业学者","definition":"a scientist who studies extinct organisms and their environments through fossil evidence","definitionCN":"通过化石证据研究已灭绝生物及其环境的科学家","example":"The paleontologist compared the jaw with three museum specimens.","exampleCN":"这位古生物学家把这件下颌与三件馆藏标本作了比较。","why":"the agent suffix -ist marks the person, while the discipline noun marks the field, so the pair is strictly complementary.","whyCN":"施事后缀 -ist 标出人，学科名词标出领域，两者严格互补。"},{"no":"02","title":"A field collector","titleCN":"野外采集与发掘者","definition":"a person who finds, excavates and records fossils at outcrops and quarries","definitionCN":"在露头与采石场寻找、发掘并记录化石的人","example":"The paleontologist spent six weeks mapping the quarry before digging.","exampleCN":"这位古生物学家在动土前花了六周测绘采坑。","why":"fieldwork is a distinct role within the profession, and the same title covers the person holding the trowel.","whyCN":"野外工作是这一行中独立的角色，同一个头衔也指拿着小铲的人。"},{"no":"03","title":"A museum curator or researcher","titleCN":"博物馆的古生物研究或策展人员","definition":"a specialist employed by a museum to care for, study and display fossil collections","definitionCN":"受雇于博物馆，负责保管、研究与展示化石藏品的人员","example":"The paleontologist rehoused the type specimens in acid-free trays.","exampleCN":"这位古生物学家把模式标本改放到无酸托盘里。","why":"institutions use the title for curatorial work, which is research plus stewardship rather than excavation.","whyCN":"机构用这个头衔指策展工作，即研究加上保管，而非发掘。"},{"no":"04","title":"A university researcher","titleCN":"大学中的研究者","definition":"an academic who teaches the subject and runs a research programme on fossil material","definitionCN":"教授该学科并就化石材料主持研究项目的学者","example":"The paleontologist supervised two doctoral students on the project.","exampleCN":"这位古生物学家在该项目上指导两名博士生。","why":"the title attaches to a post as much as to a person, so it appears in staffing lists and grant applications.","whyCN":"这个头衔既属于人也属于职位，因此出现在人员名单与经费申请中。"},{"no":"05","title":"A consultant on stratigraphy","titleCN":"为地层工作提供咨询的专家","definition":"a specialist called in to identify fossils so that a rock unit can be dated or correlated","definitionCN":"被请来鉴定化石，以便给岩层定年或对比的专家","example":"The paleontologist identified the graptolites that fixed the stage.","exampleCN":"这位古生物学家鉴定了确定该阶的笔石。","why":"industry and survey work employ the title for a service role, where the fossil is evidence rather than an object of wonder.","whyCN":"工业与地质调查用这个头衔指服务性角色，此时化石是证据而非观赏对象。"},{"no":"06","title":"An amateur specialist","titleCN":"业余的古生物研究者","definition":"an informed non-professional who collects and studies fossils seriously outside paid employment","definitionCN":"在职业之外认真采集与研究化石的非专业者","example":"An amateur paleontologist found the site while walking a new road cut.","exampleCN":"一位业余古生物研究者在查看新开的公路切面时发现了这个地点。","why":"the qualification here is knowledge and practice, not salary, which is why the same noun serves both worlds.","whyCN":"这里的资格是知识与实践，而非薪俸，因此同一名词服务于两个世界。"},{"no":"07","title":"A science communicator","titleCN":"从事科普的古生物学者","definition":"a specialist who explains fossil research to the public through writing, media or museum tours","definitionCN":"通过写作、媒体或博物馆导览向公众解释化石研究的专家","example":"As a paleontologist, she writes as carefully for children as for journals.","exampleCN":"作为古生物学家，她为儿童写作和为期刊写作一样用心。","why":"public-facing work has become part of the role, so the title now covers speaking as well as studying.","whyCN":"面向公众的工作已成为角色的一部分，因此这个头衔也涵盖讲述，而不仅是研究。"},{"no":"08","title":"A named branch specialist","titleCN":"某一分支的古生物学家","definition":"a specialist identified by the group studied, as in vertebrate paleontologist or palynologist","definitionCN":"以所研究类群来限定的专家，如脊椎动物古生物学家或孢粉学家","example":"The vertebrate paleontologist joined the excavation for one season.","exampleCN":"这位脊椎动物古生物学家参加了一季的发掘。","why":"branch names combine with the person noun, so the title scales from the whole field down to a single group.","whyCN":"分支名与人物名词组合，使头衔可以从整个领域细到单一类群。"}],"etymology":{"intro":{"en":"Paleontologist is paleontology plus the agent suffix -ist, from Greek -istēs. The discipline name was coined in the early nineteenth century; the personal noun followed immediately. Dates are approximate.","cn":"paleontologist 是 paleontology 加施事后缀 -ist（源自希腊 -istēs）。学科名于十九世纪初造出，人物名词紧随其后。年代均为约数。"},"items":[{"era":"GREEK ELEMENTS","en":"Paleontology joins palaios 'old', onta 'beings' and -logia 'study'; the discipline name was assembled in the early nineteenth century.","cn":"paleontology 由 palaios「古老」、onta「存在者」与 -logia「研究」组合；学科名于十九世纪初拼成。"},{"era":"AGENT SUFFIX -IST","en":"-ist comes from Greek -istēs, a suffix of persons who practise or adhere to something, as in botanist and geologist.","cn":"-ist 来自希腊 -istēs，指从事或信奉某事的人，如 botanist 与 geologist。"},{"era":"IMMEDIATE DERIVATION","en":"Once the field had a name, its practitioner was formed by adding -ist, and both spellings palaeo- and paleo- carry the pair.","cn":"领域一有名称，从业者便通过加 -ist 构成，palaeo- 与 paleo- 两种拼写都带这一对词。"},{"era":"PROFESSIONALIZATION","en":"As museums and universities created posts in the nineteenth century, the title became an office as well as a description.","cn":"随着博物馆与大学在十九世纪设立岗位，这个头衔既成描述也成职位。"},{"era":"BROADENING","en":"Twentieth-century practice extended the title to amateurs and communicators who publish serious work without a salary.","cn":"二十世纪的实践把这个头衔扩展到无薪却发表严肃工作的业余者与科普者。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the suffix and stems are secure, but the earliest use of the personal noun is dated approximately.","cn":"来源不确定（仅首见年代）：后缀与词干确定，但人物名词的最早使用只能约略定年。"}]},"similar":{"note":{"en":"Group one separates the person noun from the field and from look-alike titles; group two separates it from neighbouring professions.","cn":"第一组把人物名词与学科名及形近头衔分开；第二组区分它与相邻职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"paleontology","ipa":"/ˌpeɪlaɪˈnɒlədʒi/","tag":"same family, field","definition":"The discipline; the person noun differs only by the agent suffix.","definitionCN":"学科；人物名词只差一个施事后缀。"},{"word":"palaeontologist","ipa":"/ˌpæliənˈtɒlədʒɪst/","tag":"same word, British spelling","definition":"The same profession written with ae, standard in British usage.","definitionCN":"同一职业，用 ae 拼写，通行于英国。"},{"word":"paleoanthropologist","ipa":"/ˌpeɪliəʊænˈθrɒpələdʒɪst/","tag":"narrower branch","definition":"A specialist in ancient humans only; the wider title covers all extinct life.","definitionCN":"只研究远古人类的专家；较宽的头衔涵盖一切已灭绝生命。"},{"word":"paleobotanist","ipa":"/ˌpeɪliəʊˈbɒtənɪst/","tag":"narrower branch","definition":"A specialist in fossil plants; the wider title does not require plants.","definitionCN":"研究化石植物的专家；较宽的头衔并不限于植物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"archaeologist","ipa":"/ɑːˈkiːələdʒɪst/","tag":"human past","definition":"A specialist in past human societies through material traces; the two trades overlap at sites but differ in object.","definitionCN":"通过物质遗存研究过去人类社会的专家；两者在遗址上交叉，但对象不同。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"rocks and earth","definition":"A specialist in rocks and earth history; fossils are one kind of evidence among many.","definitionCN":"研究岩石与地球历史的专家；化石只是众多证据之一。"},{"word":"fossil collector","ipa":"/ˈfɒsl kəˈlektə/","tag":"hobby or trade","definition":"Someone who gathers fossils, often without publishing; the title implies study, not just acquisition.","definitionCN":"采集化石的人，常常并不发表；后者含研究之意，不只是收集。"},{"word":"curator","ipa":"/ˈkjʊərətə/","tag":"caretaker role","definition":"A person responsible for a collection; a paleontologist may be one, but curation is the duty, not the discipline.","definitionCN":"负责藏品的人；古生物学家可以担任，但策展是职责，而非学科。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"paleontology + -ist: the person who practises the study of ancient beings.","cn":"paleontology + -ist：从事远古存在者研究的人。"},{"en":"The title pairs with the field noun exactly: paleontology/paleontologist.","cn":"这个头衔与学科名词严格配对：paleontology/paleontologist。"},{"en":"British spelling doubles the vowel: palaeontologist.","cn":"英式拼写多一个元音：palaeontologist。"},{"en":"Fixed phrases: field paleontologist, museum paleontologist, vertebrate paleontologist.","cn":"固定搭配：野外古生物学家、博物馆古生物学家、脊椎动物古生物学家。"},{"en":"Compare archaeologist and geologist: same site, different object.","cn":"比较 archaeologist 与 geologist：同一遗址，不同对象。"}],"abstract":[{"en":"Picture a person kneeling in dust with a brush and a numbered bag.","cn":"想象一个人跪在尘土里，拿着刷子和编号袋。"},{"en":"Picture a jaw on a table with three labels around it and a lamp overhead.","cn":"想象桌上放着一件下颌，周围三个标签，头顶一盏灯。"},{"en":"Picture a child on a museum floor asking a patient expert why the bone is heavy.","cn":"想象一个孩子坐在博物馆地上，问一位耐心的专家骨头为什么这么重。"}]},"examples":[{"en":"The paleontologist published the jaw as a new genus.","cn":"这位古生物学家把这件下颌发表为一个新属。"},{"en":"Two paleontologists spent the winter preparing the slab.","cn":"两位古生物学家花了一个冬天修整这块板岩。"},{"en":"As a paleontologist, he refused to identify the bone from a photograph.","cn":"作为古生物学家，他拒绝仅凭照片鉴定这块骨头。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「paleonto（古生物）+ logist（学者）」——研究古生物的学者 → 古生物学家","word":"paleontologist"},"root":"paleontology（希腊 palaios「古老」+ onta「存在者」+ -logia「研究」）+ 施事后缀 -ist（希腊 -istēs）。","sensesIntro":{"en":"Eight senses describe one person in different hats: specialist, digger, curator, academic, consultant, amateur, explainer and branch expert.","cn":"八个义项描写同一个人戴的不同帽子：专家、发掘者、策展人、学者、顾问、业余者、讲述者与分支专家。"},"semanticMap":{"core":{"en":"CORE IMAGE: someone kneeling in dust with a brush, a bag and a label.","cn":"核心意象：一个人跪在尘土中，身边是刷子、袋子和标签。"},"chain":["STUDY ANCIENT LIFE","PERSON WHO DOES IT","IN THE FIELD","IN A MUSEUM","IN A UNIVERSITY","IN PUBLIC"],"branches":[{"senses":"S1 · S2","en":"THE PERSON AT WORK: the title covers both the specialist and the trowel.","cn":"工作中的这个人：头衔兼指专家与拿小铲的人。"},{"senses":"S3 · S4","en":"INSTITUTIONAL HATS: museum stewardship and academic posts.","cn":"机构中的帽子：博物馆保管与大学教职。"},{"senses":"S5","en":"SERVICE ROLE: identifying fossils so that rock can be dated.","cn":"服务角色：鉴定化石以便给岩层定年。"},{"senses":"S6 · S07","en":"BEYOND SALARY: amateurs and public explainers practise the same trade.","cn":"薪俸之外：业余者与科普者从事同一行当。"},{"senses":"S8","en":"NAMED SPECIALITY: the title narrows to a group, as in vertebrate paleontologist.","cn":"命名的专长：头衔可窄到某一类群，如脊椎动物古生物学家。"}]},"affixes":{"intro":{"en":"Paleontologist is the field noun plus the Greek agent suffix -ist, so the whole word unpacks as the person of the discipline.","cn":"paleontologist 是学科名词加希腊施事后缀 -ist，整词可解作「该学科的人」。"},"latinIntro":{"en":"Greek palaios, onta and -logia supply the field; -istēs, through -ist, supplies the person. Latin has no part in the word.","cn":"希腊 palaios、onta 与 -logia 提供领域义；-istēs 经 -ist 提供人物义。拉丁语不参与此词构成。"},"items":[{"word":"paleo-","structure":"palaios (Greek 'old')","meaning":"ancient","meaningCN":"古老的","example":"The prefix fixes the time depth.","exampleCN":"这个前缀固定了时间深度。"},{"word":"-ont-","structure":"on, ontos (Greek 'being')","meaning":"being","meaningCN":"存在者","example":"The stem fixes the object studied.","exampleCN":"这个词干固定了研究对象。"},{"word":"-logy","structure":"-logia (Greek 'study')","meaning":"the study of","meaningCN":"对……的研究","example":"The suffix fixes the field.","exampleCN":"这个后缀固定了领域。"},{"word":"-ist","structure":"-istēs (Greek agent suffix)","meaning":"one who practises","meaningCN":"从事者","example":"The suffix fixes the person.","exampleCN":"这个后缀固定了人。"},{"word":"paleontology","structure":"paleo- + -ont- + -logy","meaning":"study of ancient life","meaningCN":"古生物学","example":"Paleontology named the field first.","exampleCN":"古生物学先给领域命名。"},{"word":"paleontologist","structure":"paleontology + -ist","meaning":"practitioner of that study","meaningCN":"古生物学家","example":"The specialist cleaned the specimen.","exampleCN":"这位专家清理了标本。"},{"word":"paleontological","structure":"paleontology + -ical","meaning":"relating to the field","meaningCN":"古生物学的","example":"The argument rests on paleontological detail.","exampleCN":"该论证依赖古生物学的细节。"},{"word":"paleoanthropologist","structure":"paleo- + anthropologist","meaning":"specialist in ancient humans","meaningCN":"古人类学家","example":"A paleoanthropologist joined the survey.","exampleCN":"一位古人类学家加入了调查。"},{"word":"paleobotanist","structure":"paleo- + botanist","meaning":"specialist in fossil plants","meaningCN":"古植物学家","example":"The paleobotanist identified the leaf.","exampleCN":"古植物学家鉴定了这片叶子。"}],"latinEntries":[{"word":"palaios","structure":"palaios (Greek adj.)","meaning":"old","meaningCN":"古老的"},{"word":"on","structure":"on, ontos (Greek n.)","meaning":"being","meaningCN":"存在者"},{"word":"logia","structure":"logia (Greek n.)","meaning":"study","meaningCN":"研究"},{"word":"istēs","structure":"istēs (Greek agent noun suffix)","meaning":"one who practises","meaningCN":"从事者"}]}},{"word":"prehistoric","ipa_uk":"/ˌpriːˈhɪstɒrɪk/","ipa_us":"/ˌpriːˈhɪstɔːrɪk/","definition_zh":"史前的；有文字记录之前的；极古老、过时落后的（口语）","definition_en":"belonging to the period before written records, or extremely old and out of date in everyday speech","core_image":"洞穴深处的赭红野牛，被火把的烟熏得发暗，画者没有留下名字","scene":"洞穴深处，手电光扫过岩壁上一群赭红色的野牛，线条被烟熏得发暗。 The cave paintings belong to a prehistoric hunt that no written record describes.","sceneCN":"这里 prehistoric 指「属于有文字记录之前时期的」（第 1 个义项：史前时代的）；句意为这些洞穴壁画属于一场没有任何文字记录的史前狩猎。图中可辨识物件：赭红野牛、烟熏痕迹、手电光、洞穴岩壁。","pos":[{"tag":"adj.","zh":"史前的；有文字记录之前的；（口语）极其古老、过时的"}],"collocations":[{"phrase":"prehistoric times","zh":"史前时期"},{"phrase":"prehistoric animals","zh":"史前动物"},{"phrase":"prehistoric site","zh":"史前遗址"},{"phrase":"prehistoric art","zh":"史前艺术"},{"phrase":"prehistoric archaeology","zh":"史前考古学"},{"phrase":"prehistoric man","zh":"史前人类（旧式说法）"}],"forms":[{"label":"形容词","form":"prehistoric"},{"label":"名词（史前时期）","form":"prehistory"},{"label":"名词（史前研究者）","form":"prehistorian"},{"label":"副词","form":"prehistorically"},{"label":"对比形容词（有史以来的）","form":"historic"}],"derivatives":[{"word":"prehistory","pos":"n.","zh":"史前时期；史前史"},{"word":"prehistorian","pos":"n.","zh":"史前史研究者"},{"word":"prehistorically","pos":"adv.","zh":"在史前；从史前角度看"},{"word":"protohistoric","pos":"adj.","zh":"原史时期的（介于史前与有史之间）"},{"word":"historic","pos":"adj.","zh":"历史上有名的；有重大意义的"}],"senses":[{"no":"01","title":"Before written records","titleCN":"有文字记录之前","definition":"belonging to the period before a society kept written records","definitionCN":"属于某个社会尚未留下文字记录的时期","example":"Prehistoric burial mounds dot the chalk downs.","exampleCN":"史前墓葬土丘散布在白垩丘陵上。","why":"pre- 'before' plus historic marks a boundary, and the boundary is writing, not a fixed date.","whyCN":"pre-「之前」加 historic 标出一条界线，这条界线是文字，而非某个固定年代。"},{"no":"02","title":"Of early human cultures","titleCN":"史前人类文化的","definition":"relating to human societies known only through material traces such as tools, art and burials","definitionCN":"指只能通过工具、艺术与墓葬等物质遗存了解的人类社会","example":"Prehistoric tool-making spread faster than any written account could show.","exampleCN":"史前工具制造的传播速度，是任何文字记载都显示不出的。","why":"archaeology uses the word for cultures without texts, so the emphasis falls on material evidence.","whyCN":"考古学用这个词指没有文本的文化，因此重点落在实物证据上。"},{"no":"03","title":"Of ancient animals and plants","titleCN":"史前动物与植物的","definition":"describing organisms that lived before recorded history, especially the large extinct forms","definitionCN":"指生活在有记录历史之前、尤指已灭绝的大型生物","example":"Prehistoric mammals filled the valley after the ice withdrew.","exampleCN":"冰川退去后，史前哺乳动物遍布这个山谷。","why":"popular writing applies the word to extinct fauna, where it overlaps with prehistoric in the everyday sense.","whyCN":"通俗写作把这个词用于已灭绝的动物群，此处它与日常义重叠。"},{"no":"04","title":"Of ancient sites and art","titleCN":"史前遗址与艺术的","definition":"belonging to the material remains of pre-literate societies, such as caves, monuments and carvings","definitionCN":"属于前文字社会的物质遗存，如洞穴、巨石与雕刻","example":"The prehistoric cave was closed to protect its paintings.","exampleCN":"这座史前洞穴为保护壁画而关闭。","why":"heritage usage fixes the word to objects and places, which is why it appears on signs and in management plans.","whyCN":"遗产管理把这个词固定用于物件与场所，因此它出现在标牌与管理计划中。"},{"no":"05","title":"Extremely old in everyday speech","titleCN":"口语：极其古老","definition":"used exaggeration for something absurdly old-fashioned or long out of use","definitionCN":"夸张地指某物老得离谱或早已不用","example":"His phone is prehistoric; it still has a physical keyboard.","exampleCN":"他的手机老掉牙了，还带实体键盘。","why":"the exaggeration works because prehistory is by definition beyond memory, so 'old' becomes 'unimaginably old'.","whyCN":"夸张之所以有效，是因为史前按定义在记忆之外，于是「旧」变成「旧得不可想象」。"},{"no":"06","title":"Hopelessly out of date technology","titleCN":"口语：技术落后过时","definition":"describing equipment or software so outdated that it is a liability","definitionCN":"指设备或软件过时到成为负担","example":"The lab still runs prehistoric software on one machine.","exampleCN":"实验室还有一台机器跑着极为陈旧的软件。","why":"this sense is the technical version of sense five, and it usually carries a recommendation to replace.","whyCN":"这一义是第五义的技术版，通常暗含「该换掉」的建议。"},{"no":"07","title":"Before a field's own record","titleCN":"某领域尚无记录的阶段","definition":"describing the early, undocumented phase of a discipline or institution","definitionCN":"指某一学科或机构尚无记录的早期阶段","example":"The department's prehistoric years survive only as gossip.","exampleCN":"该系的「史前」岁月只以传闻的形式留存。","why":"the word can be used relatively: prehistory ends wherever a field starts keeping records.","whyCN":"这个词可相对使用：某个领域一开始记事，它的「史前」便告结束。"},{"no":"08","title":"Before humans in geological time","titleCN":"地质时间上人类出现之前的","definition":"belonging to the long span of earth history before humans existed, when read in a geological frame","definitionCN":"在地质框架下指人类出现之前那段漫长的地球历史","example":"The prehistoric rocks of the shield carry no trace of people.","exampleCN":"地盾上的远古岩层没有留下任何人的痕迹。","why":"geology uses the word loosely for 'before people', which is much earlier than 'before writing'.","whyCN":"地质学宽松地用这个词指「在人之前」，那比「在文字之前」早得多。"}],"etymology":{"intro":{"en":"Prehistoric joins Latin prae- 'before' to historic, from Greek historia 'inquiry, account'. The word was coined in the early nineteenth century for the period before written records. Dates are approximate.","cn":"prehistoric 由拉丁 prae-「之前」加 historic（来自希腊 historia「探究、记述」）构成，十九世纪初为指文字记录之前的时期而造。年代均为约数。"},"items":[{"era":"LATIN PRAE-","en":"Prae- meant 'before, in front of' and survives in English pre-, which marks precedence in time or place.","cn":"一般认为 prae- 意为「在前、在……之前」，在英语中留存为 pre-，标出时间或位置上的在先。"},{"era":"GREEK HISTORIA","en":"Historia meant 'inquiry, account, narrative', from histōr 'witness'; English historic and history both descend from it.","cn":"historia 意为「探究、记述、叙述」，来自 histōr「见证者」；英语 historic 与 history 均源于此。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"The compound was formed when writers needed a term for human existence before any written account existed.","cn":"当写作者需要一个词指尚无任何文字记述的人类存在时，这个复合词便被造出。"},{"era":"ARCHAEOLOGICAL FIXING","en":"Archaeology made the word a technical label for cultures known only from material remains.","cn":"考古学把这个词固定为指「只能由实物遗存了解的文化」的技术标签。"},{"era":"EVERYDAY HYPERBOLE","en":"In the twentieth century the word became a joking intensifier for anything absurdly old-fashioned.","cn":"在二十世纪，这个词成了戏谑的加强语，指任何老得离谱的东西。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): the elements are certain, but the first English use is dated approximately and varies by source.","cn":"来源不确定（仅首见年代）：成分确定，但英语中最早的使用只能约略定年，且各家说法不一。"}]},"similar":{"note":{"en":"Group one separates prehistoric from words with the same historic stem; group two separates it from adjectives for 'very old'.","cn":"第一组把 prehistoric 与同出 historic 词干的词分开；第二组区分它与表「很古老」的其它形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prehistory","ipa":"/ˌpriːˈhɪstri/","tag":"same family, noun","definition":"The period itself; the adjective describes what belongs to it.","definitionCN":"指那个时期本身；形容词描写属于该时期的事物。"},{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"shared stem, different sense","definition":"Meaning 'momentous or recorded in history'; pre- adds 'before records', not 'important'.","definitionCN":"意为「有重大意义的、载入史册的」；pre- 增添「在记录之前」，而非「重要」。"},{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"shared stem, different sense","definition":"Meaning 'relating to history as a study'; it is the ordinary adjective for the discipline.","definitionCN":"意为「与历史学有关的」，是该学科的普通形容词。"},{"word":"protohistoric","ipa":"/ˌprəʊtəʊhɪˈstɒrɪk/","tag":"neighbouring stage","definition":"Proto- 'first' plus historic: the period when a society is just beginning to be described by outsiders.","definitionCN":"proto-「最初」加 historic：某社会刚开始被外来者记述的时期。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ancient","ipa":"/ənˈsiːənt/","tag":"long ago, no boundary","definition":"Very old, with no reference to writing; it can describe a recent but venerable custom.","definitionCN":"很古老，但不涉及文字；也可形容新近却受尊崇的习俗。"},{"word":"primitive","ipa":"/ˈprɪmɪtɪv/","tag":"judgemental","definition":"Early in development, often with a tone of inferiority; prehistoric is neutral about development.","definitionCN":"发展早期，常带低劣意味；prehistoric 对发展程度保持中性。"},{"word":"primeval","ipa":"/ˈpraɪmiːvl/","tag":"earliest ages of earth","definition":"Of the earliest ages of the earth, before life of any complexity; it goes much deeper than prehistory.","definitionCN":"指地球最古老的年代，复杂生命尚未出现；比史前深得多。"},{"word":"antediluvian","ipa":"/ˌæntɪdɪˈluːviən/","tag":"biblical hyperbole","definition":"Literally 'before the flood', used jokingly for absurdly old things; it is a stylistic cousin of sense five.","definitionCN":"字面「洪水之前」，戏指老得离谱的东西；是第五义的风格近亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"pre- 'before' + historic 'recorded': before the record begins.","cn":"pre-「之前」+ historic「有记录的」：记录开始之前。"},{"en":"The family runs prehistory, prehistorian, prehistorically, protohistoric.","cn":"同族词包括 prehistory、prehistorian、prehistorically、protohistoric。"},{"en":"The boundary is writing, not a date, so the same adjective covers different centuries in different places.","cn":"界线是文字而非某个年代，因此同一形容词在不同地方覆盖不同世纪。"},{"en":"Fixed phrases: prehistoric site, prehistoric art, prehistoric animals.","cn":"固定搭配：史前遗址、史前艺术、史前动物。"},{"en":"The everyday sense is exaggeration: prehistoric phone, prehistoric software.","cn":"日常义是夸张：老掉牙的手机、极为陈旧的软件。"}],"abstract":[{"en":"Picture a handprint on a cave wall made before anyone could write.","cn":"想象一个印在洞壁上的手印，那时还没有人会书写。"},{"en":"Picture a machine still running after everyone who designed it has died.","cn":"想象一台机器仍在运转，设计它的人已全部离世。"},{"en":"Picture a joke told so often that its first teller is forgotten.","cn":"想象一个笑话被讲得太久，最初讲它的人已被遗忘。"}]},"examples":[{"en":"The site contains prehistoric pottery and no written material.","cn":"该遗址有史前陶器，没有任何文字材料。"},{"en":"Their booking system is prehistoric but functional.","cn":"他们的预订系统极为陈旧，但还能用。"},{"en":"Prehistoric lakes left thick beds of clay across the valley.","cn":"史前湖泊在山谷中留下厚厚的黏土层。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pre（之前）+ historic（有历史的）」——有历史记录之前 → 史前的；引申为老掉牙","word":"prehistoric"},"root":"拉丁 prae-「之前」（英语 pre-）+ historic（希腊 historia「探究、记述」，源自 histōr「见证者」）；十九世纪初造词。","sensesIntro":{"en":"Eight senses share one boundary, the start of records: before writing, then human material cultures, extinct animals, cave art, and finally anything so old that the boundary becomes a joke.","cn":"八个义项共享一条界线——记录的开始：先是有文字之前，再是人类的实物文化、已灭绝动物、洞穴艺术，最后是老到让这条界线变成玩笑的任何东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a painted animal on a wall, made by hands that left no name.","cn":"核心意象：壁上画的动物，由没留下名字的手所画。"},"chain":["BEFORE WRITING","MATERIAL CULTURE","EXTINCT LIFE","CAVE AND MONUMENT","ABSURDLY OLD","BEFORE A RECORD"],"branches":[{"senses":"S1 · S2","en":"THE BOUNDARY AND THE PEOPLE: writing ends prehistory, and material traces are all we have of it.","cn":"界线与人：文字终结史前，而实物痕迹是我们仅有的一切。"},{"senses":"S3 · S4","en":"LIFE AND ART: extinct animals and cave walls are the popular face of the word.","cn":"生命与艺术：已灭绝动物与洞穴岩壁是这个词的大众面孔。"},{"senses":"S5 · S6","en":"HYPERBOLE: old enough to be a joke, and equipment old enough to be a liability.","cn":"夸张：老到成为玩笑，设备旧到成为负担。"},{"senses":"S7","en":"RELATIVE PREHISTORY: every field has a phase before its own records start.","cn":"相对的史前：每个领域都有自己记录开始前的阶段。"},{"senses":"S8","en":"DEEP FRAME: geology uses the word for 'before people', far earlier than 'before writing'.","cn":"深时框架：地质学用这个词指「在人之前」，远早于「在文字之前」。"}]},"affixes":{"intro":{"en":"Prehistoric is a Latin prefix plus a Greek-derived adjective, so it reads as 'before the recorded'.","cn":"prehistoric 是拉丁前缀加希腊来源的形容词，可读作「在有记录之前」。"},"latinIntro":{"en":"Latin prae- gives pre-, and Greek historia gives historic; latinEntries records prae- and historia's Latin transmission.","cn":"拉丁 prae- 给出 pre-，希腊 historia 给出 historic；latinEntries 记录 prae- 与 historia 的拉丁传写。"},"items":[{"word":"pre-","structure":"prae- (Latin prefix 'before, in front')","meaning":"before","meaningCN":"在……之前","example":"The prefix marks precedence in time.","exampleCN":"这个前缀标出时间上的在先。"},{"word":"historic","structure":"historicus (Latin, from Greek historikos)","meaning":"of inquiry, recorded","meaningCN":"有记述的；历史的","example":"Historic implies a written account.","exampleCN":"historic 含文字记述之意。"},{"word":"prehistoric","structure":"pre- + historic","meaning":"before written records","meaningCN":"有文字记录之前的","example":"Prehistoric sites lack texts.","exampleCN":"史前遗址没有文字。"},{"word":"prehistory","structure":"pre- + history","meaning":"the period before records","meaningCN":"史前时期","example":"Prehistory is read from objects.","exampleCN":"史前史由实物读出。"},{"word":"prehistorian","structure":"prehistory + -an (person)","meaning":"one who studies that period","meaningCN":"史前史研究者","example":"The prehistorian dated the mound.","exampleCN":"这位史前史研究者给土丘定年。"},{"word":"prehistorically","structure":"prehistoric + -ally (adverb)","meaning":"in a prehistoric way or time","meaningCN":"在史前；从史前角度","example":"The valley was prehistorically wooded.","exampleCN":"这山谷在史前覆盖森林。"},{"word":"protohistoric","structure":"proto- (first) + historic","meaning":"the earliest recorded stage","meaningCN":"原史时期的","example":"Protohistoric trade left both texts and goods.","exampleCN":"原史时期的贸易留下文字与货物。"},{"word":"historical","structure":"history + -ical (relating to)","meaning":"of history as a study","meaningCN":"历史学的","example":"Historical method reads documents.","exampleCN":"历史学方法阅读文献。"},{"word":"historic","structure":"historicus (Latin)","meaning":"momentous, recorded","meaningCN":"有重大意义的；载入史册的","example":"A historic treaty was signed here.","exampleCN":"一项历史性条约在此签署。"}],"latinEntries":[{"word":"prae-","structure":"prae- (Latin prefix)","meaning":"before, in front","meaningCN":"在前；之前"},{"word":"historicus","structure":"historicus, historica, historicum (adj.)","meaning":"of history, recorded","meaningCN":"历史的；有记述的"},{"word":"historia","structure":"historia, historiae (f., first declension)","meaning":"inquiry, account","meaningCN":"探究；记述"},{"word":"historia","structure":"historia (Latin, from Greek historia)","meaning":"narrative of events","meaningCN":"事件叙述"}]}},{"word":"geological age","ipa_uk":"/dʒiəˈlɒdʒɪkl eɪdʒ/","ipa_us":"/dʒiəˈlɑːdʒɪkl eɪdʒ/","definition_zh":"地质年代；地层或岩石的年龄；地质时代的划分单位","definition_en":"the age of a rock, fossil or event measured in geological time, or a named division of earth history","core_image":"剖面图上一条条界线，把厚厚的地层分成不同的年代","scene":"学生在剖面图上标出各层的界线，老师提醒他们先确定每一层的年代再谈化石。 Each bed was assigned a geological age before any fossil was identified.","sceneCN":"这里 geological age 指「某一地层的年代」（第 3 个义项：地层形成的地质年代）；句意为在鉴定任何化石之前，先给每一层定出地质年代。图中可辨识物件：剖面图、层界线条、铅笔标记、化石符号。","pos":[{"tag":"n.","zh":"地质年代；地质年龄；地质时代的划分（可数复合名词）"}],"collocations":[{"phrase":"geological age of the Earth","zh":"地球的地质年龄"},{"phrase":"determine the geological age","zh":"确定地质年代"},{"phrase":"relative geological age","zh":"相对地质年代"},{"phrase":"absolute geological age","zh":"绝对地质年龄"},{"phrase":"geological age dating","zh":"地质年代测定"},{"phrase":"late geological age","zh":"地质年代晚期"}],"forms":[{"label":"单数","form":"geological age"},{"label":"复数","form":"geological ages"},{"label":"形容词形式","form":"geologic age"},{"label":"相关名词（地质学）","form":"geology"},{"label":"相关名词（年代学）","form":"geochronology"}],"derivatives":[{"word":"geology","pos":"n.","zh":"地质学"},{"word":"geologic","pos":"adj.","zh":"地质的"},{"word":"geologist","pos":"n.","zh":"地质学家"},{"word":"geochronology","pos":"n.","zh":"地质年代学"},{"word":"geological timescale","pos":"n.","zh":"地质年代表"}],"senses":[{"no":"01","title":"A division of earth history","titleCN":"地球历史的一个划分单位","definition":"a named interval of geological time, such as a period or an epoch, used to place events in order","definitionCN":"有名称的地质时间间隔，如纪或世，用于把事件排序","example":"The Cambrian is the geological age in which hard shells first became common.","exampleCN":"寒武纪是硬壳首次普遍出现的地质年代。","why":"the phrase can name an interval rather than a measurement, which is why it appears in tables of periods and epochs.","whyCN":"这个短语可以命名一段时间而非一个测量值，因此出现在纪与世的表格中。"},{"no":"02","title":"The absolute age of a rock","titleCN":"岩石的绝对年龄","definition":"the age of a rock or mineral in years, obtained by radiometric dating","definitionCN":"通过放射性定年得到的岩石或矿物年龄，以年计","example":"The geological age of the granite came out at three hundred million years.","exampleCN":"这块花岗岩的地质年龄测出来是三亿年。","why":"the phrase shifts from a named interval to a number, and the method, not the name, does the work.","whyCN":"这个短语从命名的时段转到数字，起决定作用的是方法而非名称。"},{"no":"03","title":"The age of a bed","titleCN":"某一地层的年代","definition":"the time at which a particular layer was deposited","definitionCN":"某一特定层沉积形成的时期","example":"Each bed was assigned a geological age before any fossil was identified.","exampleCN":"在鉴定任何化石之前，先给每一层定出地质年代。","why":"stratigraphy speaks of the age of a bed rather than of a sample, because the layer is the unit that can be mapped.","whyCN":"地层学说的是层的年代而非样品的年代，因为层才是可填图的单位。"},{"no":"04","title":"A named era or period","titleCN":"命名的纪或代","definition":"one of the formal divisions of the geological timescale, from eon down to stage","definitionCN":"地质年代表中的正式划分之一，从宙到阶","example":"The age of reptiles ended with the extinction at the boundary.","exampleCN":"爬行动物的时代以界线处的那次灭绝告终。","why":"popular writing uses age for the great divisions, while formal stratigraphy prefers period, epoch and stage.","whyCN":"通俗写作把这个词用于大划分，正式地层学则偏好 period、epoch 与 stage。"},{"no":"05","title":"The age indicated by a fossil","titleCN":"化石所指示的年代","definition":"the time range that a fossil species implies for the rock in which it is found","definitionCN":"某一化石物种为其所在岩层指示的时间范围","example":"The ammonite gives the bed a geological age no younger than the Jurassic.","exampleCN":"这件菊石给该层一个不晚于侏罗纪的地质年代。","why":"biostratigraphy converts a fossil into a date, so the phrase often appears where index species are discussed.","whyCN":"生物地层学把化石换算成年代，因此这个短语常出现在讨论标志物种之处。"},{"no":"06","title":"The age of the Earth","titleCN":"地球的年龄","definition":"the elapsed time since the formation of the Earth, now measured at about four and a half billion years","definitionCN":"自地球形成以来经过的时间，现测约四十五亿年","example":"Attempts to fix the geological age of the Earth ended the argument over a young planet.","exampleCN":"测定地球地质年龄的尝试终结了年轻地球之争。","why":"the singular phrase became a famous scientific question, and its answer changed the standing of geology.","whyCN":"这个单数短语成了一个著名的科学问题，其答案改变了地质学的地位。"},{"no":"07","title":"The geological setting of a find","titleCN":"发现物的地质年代背景","definition":"the geological period and conditions in which an archaeological or palaeontological find is set","definitionCN":"考古或古生物发现所处的时期与地质条件","example":"The tools lay in deposits of the same geological age as the cave fill.","exampleCN":"这些工具所在的堆积与洞穴填充物属于同一地质年代。","why":"cross-disciplinary work needs the phrase because a find's date may rest on the enclosing sediment rather than on the object.","whyCN":"跨学科工作需要这个短语，因为发现物的年代可能取决于围岩，而非物件本身。"},{"no":"08","title":"An impossibly long span, in speech","titleCN":"口语：极漫长的年代","definition":"used exaggeration for a wait or a period that feels endless","definitionCN":"夸张地指漫长得仿佛无尽的等待或时期","example":"It took a geological age for the bus to arrive.","exampleCN":"等公交车仿佛等了一个地质年代。","why":"the joke works because geological ages are measured in millions of years, so any delay becomes absurdly small beside them.","whyCN":"这个玩笑之所以成立，是因为地质年代以百万年计，任何等待相比之下都小得可笑。"}],"etymology":{"intro":{"en":"Geological age joins geology, from Greek gē 'earth' and -logia 'study', to age, from Latin aetas through Old French aage. The phrase settled as a technical term in the nineteenth century. Dates are approximate.","cn":"geological age 由 geology（希腊 gē「大地」+ -logia「研究」）与 age（拉丁 aetas 经古法语 aage）组合而成。这个短语在十九世纪固定为技术术语。年代均为约数。"},"items":[{"era":"GREEK GE","en":"Gē meant 'earth, land'; it opens geology, geography and geometry, each with a different second element.","cn":"gē 意为「大地、土地」；它开启 geology、geography 与 geometry，各自第二个成分不同。"},{"era":"GREEK -LOGIA","en":"-logia 'study, account' comes from logos; geology was coined in the eighteenth century for the study of the earth's structure.","cn":"-logia「研究、论述」来自 logos；geology 于十八世纪造出，指对地球构造的研究。"},{"era":"LATIN AETAS","en":"Aetas meant 'lifetime, age, period'; through Old French aage it became English age, covering both a person's years and a historical span.","cn":"aetas 意为「寿命、年龄、时期」；经古法语 aage 成为英语 age，兼指人的年岁与历史时段。"},{"era":"PHRASE FIXED","en":"Nineteenth-century geologists combined the two to speak of the age of a bed, a fossil or the earth, and the phrase became standard.","cn":"十九世纪地质学家把两者组合，用来谈层、化石或地球的年龄，这个短语遂成标准。"},{"era":"TIMESCALE FORMALIZED","en":"As the geological timescale was formalized, age also came to name the great divisions themselves.","cn":"随着地质年代表被正式化，age 也开始指那些大划分本身。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dating only): both elements are secure, but the phrase's earliest fixed use varies by author and by sense.","cn":"来源不确定（仅首见年代）：两个成分都确定，但该短语最早固定使用的年代因作者与义项而异。"}]},"similar":{"note":{"en":"Group one separates the phrase from its near compounds and adjective forms; group two separates it from words for time divisions and measurements.","cn":"第一组把这个短语与近义复合形式及形容词分开；第二组区分它与时间划分、测量的其它说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geologic age","ipa":"/dʒiəˈlɒdʒɪk eɪdʒ/","tag":"adjective variant","definition":"The same sense written with the shorter adjective; both are current, and geologic is commoner in American usage.","definitionCN":"同一意义用较短形容词表达；两者通行，geologic 在美式用法中更常见。"},{"word":"geological timescale","ipa":"/dʒiəˈlɒdʒɪkl ˈtaɪmskeɪl/","tag":"the whole system","definition":"The complete framework of eras, periods and epochs; a single age is one slot within it.","definitionCN":"由代、纪、世构成的完整框架；单个 age 是其中一格。"},{"word":"geochronology","ipa":"/ˌdʒiːəʊkrəˈnɒlədʒi/","tag":"the measuring science","definition":"The branch that measures rock ages by radiometric methods; the phrase names the result, not the method.","definitionCN":"用放射性方法测定岩石年龄的学科；短语指结果，而非方法。"},{"word":"geological era","ipa":"/dʒiəˈlɒdʒɪkl ˈiːrə/","tag":"larger division","definition":"An era is one of the largest divisions, containing several periods; an age may be much shorter.","definitionCN":"代是最大的划分之一，含若干纪；age 可能短得多。"}]},{"heading":"NEAR MEANING","entries":[{"word":"period","ipa":"/ˈperɪəd/","tag":"formal unit","definition":"A formal subdivision of an era in the timescale, such as the Jurassic; it is more precise than the loose word age.","definitionCN":"年代表中代的正式细分，如侏罗纪；比松散的 age 更精确。"},{"word":"epoch","ipa":"/ˈepɒk/","tag":"smaller formal unit","definition":"A subdivision of a period, such as the Pleistocene; it is shorter than most ages in popular use.","definitionCN":"纪的细分，如更新世；比通俗用法中的多数 age 更短。"},{"word":"date","ipa":"/deɪt/","tag":"a point or number","definition":"A specific point in time or a measured number of years; age can mean either a span or a measurement.","definitionCN":"指具体时点或测得的年数；age 可指时段，也可指测量值。"},{"word":"era","ipa":"/ˈiːrə/","tag":"broad span","definition":"A long span with a characteristic character, geological or historical; it is vaguer than a formal period.","definitionCN":"具有代表性特征的漫长时间，地质或历史皆可；比正式纪更宽泛。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"geology 'earth study' + age 'lifetime, span': the span of earth time assigned to a rock.","cn":"geology「大地研究」+ age「寿命、时段」：分配给某块岩石的地球时间跨度。"},{"en":"The family runs geology, geologic, geologist, geochronology, geological timescale.","cn":"同族词包括 geology、geologic、geologist、geochronology、geological timescale。"},{"en":"Two readings: a named division, or a number of years.","cn":"两种读法：一个有名称的划分，或一个年数。"},{"en":"Fixed phrases: relative geological age, absolute geological age, age of the Earth.","cn":"固定搭配：相对地质年代、绝对地质年龄、地球的年龄。"},{"en":"The everyday joke works because the unit is millions of years.","cn":"日常玩笑成立，是因为这个单位以百万年计。"}],"abstract":[{"en":"Picture a ruler laid along a cliff, with each bed given a number.","cn":"想象一把尺子沿崖壁铺开，每层都标上一个数。"},{"en":"Picture a library where each shelf is a million years and the book you want is on one of them.","cn":"想象一座图书馆，每层书架是一百万年，你要的书在其一。"},{"en":"Picture a queue so slow that the wait is measured in stone.","cn":"想象一条慢到用石头计时的队伍。"}]},"examples":[{"en":"The geological age of the lava flow was fixed by radiometric dating.","cn":"这次熔岩流的地质年龄由放射性定年确定。"},{"en":"Fossils of the same geological age occur on three continents.","cn":"同一地质年代的化石出现在三个大洲。"},{"en":"It took a geological age to get a reply from the ministry.","cn":"从部里得到答复仿佛等了一个地质年代。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「geo（大地）+ logical（学问的）+ age（年代）」——研究大地所得出的年代 → 地质年代","word":"geological age"},"root":"geology（希腊 gē「大地」+ -logia「研究」）+ age（拉丁 aetas「寿命、时期」经古法语 aage）；十九世纪固定为技术短语。","sensesIntro":{"en":"Eight senses run from a named division to a measured number, then to a single bed, a fossil, the whole planet, a find's setting and a joke about waiting.","cn":"八个义项从有名称的划分走到测量数值，再到单一层、化石、整个行星、发现物的背景，以及关于等待的玩笑。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler laid along a cliff, each bed given its own number.","cn":"核心意象：一把尺子沿崖壁铺开，每一层都有自己的数字。"},"chain":["EARTH HISTORY","NAMED DIVISIONS","MEASURED YEARS","ONE BED'S DATE","FOSSIL'S RANGE","THE PLANET'S SPAN"],"branches":[{"senses":"S1 · S4","en":"NAMED TIME: formal divisions and popular eras are the same scale read at different precision.","cn":"命名的时间：正式划分与通俗时代，是同一尺度以不同精度读取。"},{"senses":"S2 · S3","en":"MEASUREMENT: a rock's years and a bed's date differ in object, not in method.","cn":"测量：岩石的年数与层的年代，对象不同而方法相同。"},{"senses":"S5","en":"FOSSIL AS CLOCK: an index species converts stone into a date.","cn":"化石作钟：标志物种把石头换算成年代。"},{"senses":"S6 · S7","en":"WHOLE PLANET AND LOCAL SETTING: the same phrase scales from the earth to a find.","cn":"整个行星与局部背景：同一短语从地球缩到一件发现物。"},{"senses":"S8","en":"HYPERBOLE: a unit of millions makes any wait laughably short.","cn":"夸张：以百万年为单位，任何等待都短得可笑。"}]},"affixes":{"intro":{"en":"Geological age is a two-word technical phrase whose parts come from Greek and Latin respectively, and each part still builds families.","cn":"geological age 是两词技术短语，两部分分别来自希腊语与拉丁语，且各自仍在构词。"},"latinIntro":{"en":"Greek gē 'earth' plus -logia 'study' gives geology; Latin aetas 'lifetime' gives age through French. Latin entries record aetas and its relatives.","cn":"希腊 gē「大地」加 -logia「研究」给出 geology；拉丁 aetas「寿命」经法语给出 age。latinEntries 记录 aetas 及其同族。"},"items":[{"word":"geo-","structure":"gē (Greek noun 'earth, land')","meaning":"earth","meaningCN":"大地","example":"The prefix fixes the planet as the object.","exampleCN":"这个前缀把行星固定为对象。"},{"word":"-logy","structure":"-logia (Greek 'study')","meaning":"the study of","meaningCN":"对……的研究","example":"Geology and biology share it.","exampleCN":"地质学与生物学共用它。"},{"word":"geological","structure":"geology + -ical (relating to)","meaning":"of the study of the earth","meaningCN":"地质学的","example":"Geological maps show bedrock.","exampleCN":"地质图显示基岩。"},{"word":"age","structure":"aetas (Latin 'lifetime, period') via Old French aage","meaning":"a span of time","meaningCN":"一段时间；年龄","example":"Age can mean a person's years or an era.","exampleCN":"age 可指人的年岁，也可指一个时代。"},{"word":"geological age","structure":"geological + age (compound term)","meaning":"the date of a rock or a division of time","meaningCN":"地质年代；地质年龄","example":"Each bed has its own geological age.","exampleCN":"每层都有自己的地质年代。"},{"word":"geology","structure":"geo- + -logy","meaning":"study of the earth","meaningCN":"地质学","example":"Geology grew from mining and mapping.","exampleCN":"地质学从采矿与测绘发展而来。"},{"word":"geologist","structure":"geology + -ist","meaning":"a student of the earth","meaningCN":"地质学家","example":"The geologist logged the section.","exampleCN":"地质学家记录了剖面。"},{"word":"geochronology","structure":"geo- + chronology","meaning":"measurement of earth time","meaningCN":"地质年代学","example":"Geochronology dates the flow.","exampleCN":"地质年代学给熔岩流定年。"},{"word":"geological timescale","structure":"geological + timescale","meaning":"the framework of earth history","meaningCN":"地质年代表","example":"The timescale orders all ages.","exampleCN":"年代表给所有年代排序。"}],"latinEntries":[{"word":"aetas","structure":"aetas, aetatis (f., third declension)","meaning":"lifetime, age, period","meaningCN":"寿命；年龄；时期"},{"word":"aeternus","structure":"aeternus, aeterna, aeternum (adj.)","meaning":"lasting, eternal","meaningCN":"持久的；永恒的"},{"word":"aevum","structure":"aevum, aevi (n., second declension)","meaning":"an age, eternity","meaningCN":"年代；永恒"},{"word":"geologia","structure":"geologia, geologiae (f., Modern Latin)","meaning":"study of the earth","meaningCN":"地质学"}]}}]);
